impl ProviderTerminalSession {
    fn new(provider: &str) -> Arc<Self> {
        Arc::new(Self {
            provider: provider.to_string(),
            phase: Arc::new(Mutex::new("idle".to_string())),
            message: Arc::new(Mutex::new("Ready".to_string())),
            output: Arc::new(Mutex::new("Ready.".to_string())),
            writer: Arc::new(Mutex::new(None)),
            master: Arc::new(Mutex::new(None)),
            child: Arc::new(Mutex::new(None)),
            pid: Arc::new(Mutex::new(None)),
            running: Arc::new(AtomicBool::new(false)),
            ready_for_input: Arc::new(AtomicBool::new(false)),
        })
    }

    fn snapshot(&self) -> ProviderTerminalSnapshot {
        ProviderTerminalSnapshot {
            provider: self.provider.clone(),
            phase: self.phase.lock().map(|v| v.clone()).unwrap_or_else(|_| "error".to_string()),
            message: self.message.lock().map(|v| v.clone()).unwrap_or_default(),
            running: self.running.load(Ordering::Relaxed),
            ready_for_input: self.ready_for_input.load(Ordering::Relaxed),
            pid: self.pid.lock().ok().and_then(|v| *v),
            output: self.output.lock().map(|v| v.clone()).unwrap_or_default(),
        }
    }
}

static GEMINI_ACTIVE_PID: OnceLock<Mutex<Option<u32>>> = OnceLock::new();
static CLAUDE_ACTIVE_PID: OnceLock<Mutex<Option<u32>>> = OnceLock::new();
static CANCELLED_CANVAS_TURNS_GLOBAL: OnceLock<Mutex<HashSet<String>>> = OnceLock::new();
static CODEX_PROVIDER_TERMINAL: OnceLock<Mutex<Option<Arc<ProviderTerminalSession>>>> = OnceLock::new();
static GEMINI_PROVIDER_TERMINAL: OnceLock<Mutex<Option<Arc<ProviderTerminalSession>>>> = OnceLock::new();
static CLAUDE_PROVIDER_TERMINAL: OnceLock<Mutex<Option<Arc<ProviderTerminalSession>>>> = OnceLock::new();
static PROVIDER_CLI_HEALTH: OnceLock<Mutex<HashMap<String, ProviderCliHealth>>> = OnceLock::new();

#[cfg(windows)]
const WINDOWS_CREATE_NO_WINDOW: u32 = 0x08000000;
#[cfg(windows)]
const WINDOWS_BELOW_NORMAL_PRIORITY_CLASS: u32 = 0x00004000;
const PROVIDER_CLI_HEALTH_TTL_MS: u128 = 12 * 60 * 60 * 1000;

fn configure_forge_llm_cli_command(command: &mut Command) {
    command.env("NO_COLOR", "1");
    #[cfg(windows)]
    {
        command.creation_flags(WINDOWS_CREATE_NO_WINDOW | WINDOWS_BELOW_NORMAL_PRIORITY_CLASS);
    }
}

fn gemini_active_pid_lock() -> &'static Mutex<Option<u32>> {
    GEMINI_ACTIVE_PID.get_or_init(|| Mutex::new(None))
}

fn codex_provider_terminal_lock() -> &'static Mutex<Option<Arc<ProviderTerminalSession>>> {
    CODEX_PROVIDER_TERMINAL.get_or_init(|| Mutex::new(None))
}

fn claude_active_pid_lock() -> &'static Mutex<Option<u32>> {
    CLAUDE_ACTIVE_PID.get_or_init(|| Mutex::new(None))
}

fn cancelled_canvas_turns_global() -> &'static Mutex<HashSet<String>> {
    CANCELLED_CANVAS_TURNS_GLOBAL.get_or_init(|| Mutex::new(HashSet::new()))
}

fn gemini_provider_terminal_lock() -> &'static Mutex<Option<Arc<ProviderTerminalSession>>> {
    GEMINI_PROVIDER_TERMINAL.get_or_init(|| Mutex::new(None))
}

fn claude_provider_terminal_lock() -> &'static Mutex<Option<Arc<ProviderTerminalSession>>> {
    CLAUDE_PROVIDER_TERMINAL.get_or_init(|| Mutex::new(None))
}

fn provider_cli_health_lock() -> &'static Mutex<HashMap<String, ProviderCliHealth>> {
    PROVIDER_CLI_HEALTH.get_or_init(|| Mutex::new(HashMap::new()))
}

fn provider_display_name(provider: &str) -> &'static str {
    match provider {
        "codex" => "Codex",
        "gemini" => "Gemini",
        "claude" => "Claude",
        _ => "CLI",
    }
}

fn provider_terminal_running(provider: &str) -> bool {
    let session = match provider {
        "codex" => codex_provider_terminal_lock().lock().ok().and_then(|guard| guard.clone()),
        "gemini" => gemini_provider_terminal_lock().lock().ok().and_then(|guard| guard.clone()),
        "claude" => claude_provider_terminal_lock().lock().ok().and_then(|guard| guard.clone()),
        _ => None,
    };
    session
        .as_ref()
        .map(|session| session.running.load(Ordering::Relaxed))
        .unwrap_or(false)
}

fn remember_provider_cli_health(provider: &str, status: &OpenAiSubscriptionStatus) {
    if !status.installed && !status.connected {
        return;
    }
    if let Ok(mut guard) = provider_cli_health_lock().lock() {
        guard.insert(
            provider.to_string(),
            ProviderCliHealth {
                status: status.clone(),
                observed_ms: now_epoch_ms(),
            },
        );
    }
}

fn recent_provider_cli_health(provider: &str) -> Option<ProviderCliHealth> {
    let now = now_epoch_ms();
    provider_cli_health_lock()
        .lock()
        .ok()
        .and_then(|guard| guard.get(provider).cloned())
        .filter(|entry| now.saturating_sub(entry.observed_ms) <= PROVIDER_CLI_HEALTH_TTL_MS)
}

fn sticky_provider_cli_status(
    provider: &str,
    mut status: OpenAiSubscriptionStatus,
    hard_failure: bool,
) -> OpenAiSubscriptionStatus {
    if status.connected {
        return status;
    }
    let Some(cached) = recent_provider_cli_health(provider) else {
        return status;
    };
    let live_hint = if provider_terminal_running(provider) {
        format!(
            " The embedded {} terminal is still live in Forge.",
            provider_display_name(provider)
        )
    } else {
        String::new()
    };
    if cached.status.connected {
        status.connected = true;
        status.installed = true;
        status.auth_source = cached.status.auth_source.clone();
        status.account_label = status.account_label.or(cached.status.account_label.clone());
        status.last_refresh = status.last_refresh.or(cached.status.last_refresh.clone());
        status.message = if hard_failure {
            format!(
                "{} was recently validated by Forge, but the latest CLI probe failed. Keeping it connected while Forge rechecks the local install.{}",
                provider_display_name(provider),
                live_hint
            )
        } else {
            format!(
                "{} was recently validated by Forge. Keeping it connected while Forge rechecks the local CLI.{}",
                provider_display_name(provider),
                live_hint
            )
        };
        return status;
    }
    if !status.installed && cached.status.installed {
        status.installed = true;
        status.account_label = status.account_label.or(cached.status.account_label.clone());
        if status.auth_source == "none" {
            status.auth_source = cached.status.auth_source.clone();
        }
        status.message = format!(
            "{} CLI was recently validated by Forge. Keeping it available while Forge rechecks the local install.{}",
            provider_display_name(provider),
            live_hint
        );
    }
    status
}

fn mark_canvas_turn_cancelled_global(turn_id: &str) {
    if turn_id.trim().is_empty() {
        return;
    }
    if let Ok(mut guard) = cancelled_canvas_turns_global().lock() {
        guard.insert(turn_id.to_string());
    }
}

fn canvas_turn_cancelled_global(turn_id: &str) -> bool {
    if turn_id.trim().is_empty() {
        return false;
    }
    cancelled_canvas_turns_global()
        .lock()
        .map(|guard| guard.contains(turn_id))
        .unwrap_or(false)
}

fn clear_canvas_turn_cancelled_global(turn_id: &str) {
    if turn_id.trim().is_empty() {
        return;
    }
    if let Ok(mut guard) = cancelled_canvas_turns_global().lock() {
        guard.remove(turn_id);
    }
}

impl Drop for CodexAppServerClient {
    fn drop(&mut self) {
        if let Ok(mut child) = self.child.lock() {
            let _ = kill_process_tree(child.id());
            let _ = child.kill();
            let _ = child.wait();
        }
    }
}

fn codex_request_id_key(id: &JsonValue) -> String {
    id.as_str()
        .map(|s| s.to_string())
        .unwrap_or_else(|| id.to_string())
}

fn codex_rpc_error_message(value: &JsonValue) -> String {
    let message = value
        .get("message")
        .and_then(JsonValue::as_str)
        .unwrap_or("unknown app-server error");
    let code = value.get("code").and_then(JsonValue::as_i64).unwrap_or(0);
    format!("{message} ({code})")
}

fn write_codex_rpc_message(stdin: &Arc<Mutex<ChildStdin>>, value: &JsonValue) {
    let Ok(mut guard) = stdin.lock() else {
        return;
    };
    let _ = writeln!(&mut *guard, "{value}");
    let _ = guard.flush();
}

fn codex_chatgpt_auth_tokens_for_app_server() -> Option<JsonValue> {
    let path = forge_home_dir()?.join(".codex").join("auth.json");
    let text = std::fs::read_to_string(path).ok()?;
    let value: JsonValue = serde_json::from_str(&text).ok()?;
    let tokens = value.get("tokens")?;
    let access = tokens
        .get("access_token")
        .and_then(JsonValue::as_str)
        .filter(|s| !s.trim().is_empty())?;
    let account = tokens
        .get("account_id")
        .or_else(|| tokens.get("chatgpt_account_id"))
        .or_else(|| value.get("chatgpt_account_id"))
        .and_then(JsonValue::as_str)
        .filter(|s| !s.trim().is_empty())?;
    let plan = tokens
        .get("plan_type")
        .or_else(|| tokens.get("chatgpt_plan_type"))
        .or_else(|| value.get("chatgpt_plan_type"))
        .and_then(JsonValue::as_str);
    Some(json!({
        "accessToken": access,
        "chatgptAccountId": account,
        "chatgptPlanType": plan,
    }))
}

fn forge_dynamic_tool_text_response(id: JsonValue, success: bool, value: JsonValue) -> JsonValue {
    let text = serde_json::to_string_pretty(&value).unwrap_or_else(|_| value.to_string());
    json!({
        "id": id,
        "result": {
            "success": success,
            "contentItems": [{
                "type": "inputText",
                "text": text
            }]
        }
    })
}

fn forge_dynamic_tool_error_response(id: JsonValue, message: impl Into<String>) -> JsonValue {
    forge_dynamic_tool_text_response(
        id,
        false,
        json!({
            "error": message.into(),
            "transport": "forge_dynamic_tool",
        }),
    )
}

fn forge_json_string_at(value: &JsonValue, pointers: &[&str]) -> Option<String> {
    for pointer in pointers {
        if let Some(text) = value
            .pointer(pointer)
            .and_then(JsonValue::as_str)
            .filter(|text| !text.trim().is_empty())
        {
            return Some(text.to_string());
        }
    }
    None
}

fn forge_canonical_dynamic_tool_name(tool: &str) -> &str {
    match tool.trim() {
        "/create_" | "create_" => "forge_create_program",
        "/indicator" | "indicator" | "/indicator_" | "indicator_" => "forge_create_program",
        "/alert_" | "alert_" => "forge_create_program",
        "/program_" | "program_" => "forge_run_program",
        "/strategy_" | "strategy_" => "forge_run_program",
        "/metric" | "metric" => "forge_compile_validate_route",
        "/visualprogram_" | "visualprogram_" | "/visualprogram" | "visualprogram" => "forge_run_visual_program",
        "/geo" | "geo" | "/geo_" | "geo_" | "/minigeo" | "minigeo" | "/minigeo_" | "minigeo_" => "forge_upsert_geonode",
        other => other,
    }
}

fn forge_public_command_for_tool(tool: &str) -> &'static str {
    match forge_canonical_dynamic_tool_name(tool) {
        "forge_create_program" => "/create_",
        "forge_run_program" => "/program_",
        "forge_compile_validate_route" | "forge_list_capabilities" | "forge_3d_metric_catalog" => "/metric",
        "forge_run_visual_program" | "forge_model_3d_mapping" | "forge_analyze_3d_mapping" | "forge_interpret_visual_mapping" => "/visualprogram_",
        "forge_upsert_geonode" => "/geo",
        "trading_transcript" => "/transcript_",
        "forge_atlas_overview" => "/atlas",
        _ => "",
    }
}

fn forge_public_tool_label(tool: &str) -> String {
    let public = forge_public_command_for_tool(tool);
    if public.is_empty() {
        tool.to_string()
    } else {
        public.to_string()
    }
}

fn forge_normalized_public_command(requested_tool: &str, canonical_tool: &str) -> String {
    match requested_tool.trim() {
        "/indicator_" | "indicator_" => "/indicator".to_string(),
        "/geo_" | "geo_" => "/geo".to_string(),
        "/minigeo_" | "minigeo_" => "/minigeo".to_string(),
        "/visualprogram" | "visualprogram" => "/visualprogram_".to_string(),
        "/strategy_" | "strategy_" => "/strategy_".to_string(),
        "/alert_" | "alert_" => "/alert_".to_string(),
        "/transcript_" | "transcript_" => "/transcript_".to_string(),
        "/indicator" | "indicator" => "/indicator".to_string(),
        "/geo" | "geo" => "/geo".to_string(),
        "/minigeo" | "minigeo" => "/minigeo".to_string(),
        other if other.starts_with('/') => other.to_string(),
        _ => forge_public_tool_label(canonical_tool),
    }
}

fn forge_dynamic_tool_result_summary(tool: &str, result: &JsonValue) -> JsonValue {
    let job_id = forge_json_string_at(
        result,
        &[
            "/data/job/job_id",
            "/data/job/jobId",
            "/data/job_id",
            "/data/jobId",
            "/data/manifest/job_id",
            "/data/manifest/jobId",
            "/job/job_id",
            "/job/jobId",
            "/job_id",
            "/jobId",
            "/manifest/job_id",
            "/manifest/jobId",
        ],
    );
    let program_hash = forge_json_string_at(
        result,
        &[
            "/data/program/program_hash",
            "/data/program/programHash",
            "/data/program_hash",
            "/data/programHash",
            "/program/program_hash",
            "/program/programHash",
            "/program_hash",
            "/programHash",
        ],
    );
    let program_title = forge_json_string_at(
        result,
        &[
            "/data/program/title",
            "/data/title",
            "/program/title",
            "/title",
        ],
    );
    let public_command = forge_public_command_for_tool(tool);
    json!({
        "tool": tool,
        "publicCommand": if public_command.is_empty() { JsonValue::Null } else { json!(public_command) },
        "jobId": job_id,
        "programHash": program_hash,
        "programTitle": program_title,
        "status": result
            .pointer("/data/status")
            .or_else(|| result.pointer("/status"))
            .cloned()
            .unwrap_or(JsonValue::Null),
        "result": result,
    })
}

fn emit_forge_dynamic_tool_event(
    context: &CodexDynamicToolContext,
    stage: &str,
    message: impl Into<String>,
    data: JsonValue,
) {
    let Some(app) = context.app.as_ref() else {
        return;
    };
    let Some(turn_id) = context.canvas_turn_id.as_deref() else {
        return;
    };
    emit_canvas_assistant_event(Some(app), turn_id, stage, message, data);
}

