fn webexplorer_dom_snapshot_hash(
    current_url: &str,
    title: &str,
    root_id: &str,
    nodes: &[WebExplorerMemoryNode],
) -> String {
    let mut hasher = Sha256::new();
    hasher.update(current_url.as_bytes());
    hasher.update(title.as_bytes());
    hasher.update(root_id.as_bytes());
    if let Ok(encoded_nodes) = serde_json::to_vec(nodes) {
        hasher.update(encoded_nodes);
    }
    format!("{:x}", hasher.finalize())
}

#[derive(Clone)]
