#[tauri::command]
async fn claude_subscription_login() -> Result<OpenAiSubscriptionLoginResult, String> {
    let candidate = claude_cli_binary_path();
    let appdata_npm = std::env::var_os("APPDATA")
        .map(PathBuf::from)
        .map(|dir| dir.join("npm"));
    let claude_cmd = candidate
        .clone()
        .or_else(|| appdata_npm.as_ref().map(|dir| dir.join("claude.cmd")))
        .unwrap_or_else(|| PathBuf::from("claude.cmd"));
    let claude_exe = appdata_npm
        .as_ref()
        .map(|dir| dir.join("node_modules").join("@anthropic-ai").join("claude-code").join("bin").join("claude.exe"))
        .unwrap_or_else(|| PathBuf::from("claude.exe"));
    let npm = npm_binary_path().unwrap_or_else(|| PathBuf::from("npm.cmd"));
    let command = if candidate.is_some() {
        format!("{} auth login", claude_cmd.display())
    } else {
        format!("{} install -g @anthropic-ai/claude-code && claude auth login", npm.display())
    };
    #[cfg(windows)]
    {
        let quoted_claude_cmd = claude_cmd.display().to_string().replace('\'', "''");
        let quoted_claude_exe = claude_exe.display().to_string().replace('\'', "''");
        let quoted_npm = npm.display().to_string().replace('\'', "''");
        let script = format!(
            "$ErrorActionPreference='Continue'; \
             $claudeCmd = '{quoted_claude_cmd}'; \
             $claudeExe = '{quoted_claude_exe}'; \
             $npmBin = '{quoted_npm}'; \
             if (-not (Test-Path -LiteralPath $claudeExe) -and -not (Test-Path -LiteralPath $claudeCmd)) {{ \
                 Write-Host 'Forge is installing Claude Code CLI for this machine...'; \
                 if (Test-Path -LiteralPath $npmBin) {{ & $npmBin install -g @anthropic-ai/claude-code; }} \
                 elseif (Get-Command npm -ErrorAction SilentlyContinue) {{ npm install -g @anthropic-ai/claude-code; }} \
                 else {{ Write-Host 'npm was not found. Install Node.js first, then retry from Forge.'; return; }}; \
                 Write-Host ''; \
             }}; \
             Write-Host 'Forge is starting Claude.ai subscription OAuth.'; \
             if (Test-Path -LiteralPath $claudeExe) {{ & $claudeExe auth login; }} \
             elseif (Test-Path -LiteralPath $claudeCmd) {{ cmd /c $claudeCmd auth login; }} \
             else {{ Write-Host 'Claude Code CLI install did not produce the expected files. Reopen Forge and retry.'; return; }}; \
             Write-Host ''; \
             Write-Host 'When the login is finished, return to Forge and refresh LLM providers.'"
        );
        std::process::Command::new("cmd")
            .args([
                "/C",
                "start",
                "",
                "powershell",
                "-NoExit",
                "-ExecutionPolicy",
                "Bypass",
                "-Command",
                &script,
            ])
            .spawn()
            .map_err(|e| format!("failed to start Claude subscription login: {e}"))?;
        return Ok(OpenAiSubscriptionLoginResult {
            started: true,
            command,
            message: if candidate.is_some() {
                "Claude Code subscription login opened. Choose Claude.ai Pro/Max OAuth, then refresh."
                    .to_string()
            } else {
                "Claude Code install/login opened. Forge will install the CLI if needed, then start Claude.ai OAuth."
                    .to_string()
            },
        });
    }
    #[cfg(not(windows))]
    {
        let mut command_proc = if candidate.is_some() {
            let mut cmd = std::process::Command::new(&claude_cmd);
            cmd.args(["auth", "login"]);
            cmd
        } else {
            let mut install = std::process::Command::new(&npm);
            install.args(["install", "-g", "@anthropic-ai/claude-code"]);
            install
        };
        command_proc
            .spawn()
            .map_err(|e| format!("failed to start Claude subscription login: {e}"))?;
        Ok(OpenAiSubscriptionLoginResult {
            started: true,
            command,
            message: "Claude Code subscription login started. Choose Claude.ai Pro/Max OAuth, then refresh."
                .to_string(),
        })
    }
}

#[tauri::command]
async fn gemini_subscription_login() -> Result<OpenAiSubscriptionLoginResult, String> {
    let candidate = gemini_cli_binary_path();
    let workspace = forge_workspace_dir();
    let appdata_npm = std::env::var_os("APPDATA")
        .map(PathBuf::from)
        .map(|dir| dir.join("npm"));
    let gemini_cmd = candidate
        .clone()
        .or_else(|| appdata_npm.as_ref().map(|dir| dir.join("gemini.cmd")))
        .unwrap_or_else(|| PathBuf::from("gemini.cmd"));
    let gemini_script = appdata_npm
        .as_ref()
        .map(|dir| dir.join("node_modules").join("@google").join("gemini-cli").join("bundle").join("gemini.js"))
        .unwrap_or_else(|| PathBuf::from("gemini.js"));
    let node = node_binary_path().unwrap_or_else(|| PathBuf::from("node"));
    let npm = npm_binary_path().unwrap_or_else(|| PathBuf::from("npm.cmd"));
    let command = if candidate.is_some() {
        format!("{} (interactive Gemini CLI)", gemini_cmd.display())
    } else {
        format!("{} install -g @google/gemini-cli && gemini", npm.display())
    };
    #[cfg(windows)]
    {
        let quoted_workspace = workspace.display().to_string().replace('\'', "''");
        let quoted_gemini_cmd = gemini_cmd.display().to_string().replace('\'', "''");
        let quoted_gemini_script = gemini_script.display().to_string().replace('\'', "''");
        let quoted_node = node.display().to_string().replace('\'', "''");
        let quoted_npm = npm.display().to_string().replace('\'', "''");
        let script = format!(
            "$ErrorActionPreference='Continue'; \
             Set-Location '{quoted_workspace}'; \
             $geminiCmd = '{quoted_gemini_cmd}'; \
             $geminiScript = '{quoted_gemini_script}'; \
             $nodeBin = '{quoted_node}'; \
             $npmBin = '{quoted_npm}'; \
             if (-not (Test-Path -LiteralPath $geminiScript)) {{ \
                 Write-Host 'Forge is installing Gemini CLI for this machine...'; \
                 if (Test-Path -LiteralPath $npmBin) {{ & $npmBin install -g @google/gemini-cli; }} \
                 elseif (Get-Command npm -ErrorAction SilentlyContinue) {{ npm install -g @google/gemini-cli; }} \
                 else {{ Write-Host 'npm was not found. Install Node.js first, then retry from Forge.'; return; }}; \
                 Write-Host ''; \
             }}; \
             Write-Host 'Forge is starting Gemini CLI.'; \
             if (Test-Path -LiteralPath $geminiScript) {{ \
                 if (Test-Path -LiteralPath $nodeBin) {{ & $nodeBin $geminiScript; }} \
                 else {{ Write-Host 'Node.js was not found. Install Node.js, then retry from Forge.'; }} \
             }} elseif (Test-Path -LiteralPath $geminiCmd) {{ \
                 cmd /c $geminiCmd; \
             }} else {{ \
                 Write-Host 'Gemini CLI install did not produce the expected files. Reopen Forge and retry.'; \
             }}; \
             Write-Host ''; \
             Write-Host 'When Gemini is ready, return to Forge and click Refresh.'"
        );
        std::process::Command::new("cmd")
            .args([
                "/C",
                "start",
                "",
                "powershell",
                "-NoExit",
                "-ExecutionPolicy",
                "Bypass",
                "-Command",
                &script,
            ])
            .spawn()
            .map_err(|e| format!("failed to start Gemini setup: {e}"))?;
        return Ok(OpenAiSubscriptionLoginResult {
            started: true,
            command,
            message: if candidate.is_some() {
                "Gemini CLI opened. Finish any Google sign-in there, then return to Forge and click Refresh."
                    .to_string()
            } else {
                "Gemini CLI install/setup opened. Forge will install it if needed, then launch Gemini in the same window."
                    .to_string()
            },
        });
    }
    #[cfg(not(windows))]
    {
        let mut command_proc = if candidate.is_some() {
            Command::new(&gemini_cmd)
        } else {
            let mut install = Command::new(&npm);
            install.args(["install", "-g", "@google/gemini-cli"]);
            install
        };
        command_proc
            .current_dir(workspace)
            .spawn()
            .map_err(|e| format!("failed to start Gemini setup: {e}"))?;
        Ok(OpenAiSubscriptionLoginResult {
            started: true,
            command,
            message: "Gemini setup started. When the CLI is ready, return to Forge and refresh."
                .to_string(),
        })
    }
}

#[tauri::command]
async fn openai_subscription_login() -> Result<OpenAiSubscriptionLoginResult, String> {
    let command = "codex login".to_string();
    #[cfg(windows)]
    {
        let script = "$ErrorActionPreference='Continue'; \
            $localCodex = Join-Path $env:USERPROFILE '.codex\\.sandbox-bin\\codex.exe'; \
            if (Test-Path -LiteralPath $localCodex) { \
                Write-Host 'Forge is starting Codex OAuth for your OpenAI subscription.'; \
                & $localCodex login; \
            } elseif (Get-Command codex -ErrorAction SilentlyContinue) { \
                Write-Host 'Forge is starting Codex OAuth for your OpenAI subscription.'; \
                codex login; \
            } else { \
                Write-Host 'Codex CLI was not found in PATH.'; \
            }; \
            Write-Host ''; \
            Write-Host 'Forge detects Codex OAuth at ~/.codex/auth.json.'";
        std::process::Command::new("cmd")
            .args([
                "/C",
                "start",
                "",
                "powershell",
                "-NoExit",
                "-ExecutionPolicy",
                "Bypass",
                "-Command",
                script,
            ])
            .spawn()
            .map_err(|e| format!("failed to start OpenAI sign-in: {e}"))?;
        return Ok(OpenAiSubscriptionLoginResult {
            started: true,
            command,
            message: "Codex OAuth sign-in opened in a terminal for your OpenAI subscription.".to_string(),
        });
    }
    #[cfg(not(windows))]
    {
        Ok(OpenAiSubscriptionLoginResult {
            started: false,
            command,
            message: "Open a terminal and run `codex login`, then refresh Forge provider status.".to_string(),
        })
    }
}

impl ForgeBackend {
    fn new(store_path: PathBuf) -> std::io::Result<Self> {
        let open_t0 = Instant::now();
        std::fs::create_dir_all(&store_path)?;
        let store_t0 = Instant::now();
        let store = Store::open(&store_path)?;
        eprintln!(
            "[forge-backend-open] Store::open {} ms path={}",
            store_t0.elapsed().as_millis(),
            store_path.display()
        );
        let node_t0 = Instant::now();
        let node = MonsterNode::new(store, MemoryGovernor::new(1024 * 1024 * 1024));
        eprintln!(
            "[forge-backend-open] MonsterNode::new {} ms",
            node_t0.elapsed().as_millis()
        );

        // Open the unified redundancy atlas next to forge.cas, attach to
        // MonsterNode so both layers share the same persisted hash store.
        let atlas_path = store_path.join("forge.atlas");
        let atlas_t0 = Instant::now();
        let atlas = std::sync::Arc::new(scan::atlas::Atlas::open(&atlas_path)?);
        eprintln!(
            "[forge-backend-open] Atlas::open {} ms path={}",
            atlas_t0.elapsed().as_millis(),
            atlas_path.display()
        );
        node.attach_atlas(std::sync::Arc::clone(&atlas));

        let programs_t0 = Instant::now();
        let mut programs: HashMap<&'static str, Hash> = HashMap::new();
        programs.insert(
            "kmer_hash",
            node.store().store(build_kmer_hash().bytes())?,
        );
        programs.insert(
            "kmer_complement",
            node.store().store(build_kmer_complement_hash().bytes())?,
        );
        programs.insert(
            "kmer_double_mix",
            node.store().store(build_kmer_double_mix().bytes())?,
        );
        programs.insert(
            "kmer_strobemer",
            node.store().store(build_kmer_strobemer().bytes())?,
        );
        programs.insert(
            "kmer_minhash_10",
            node.store().store(build_kmer_minhash_10().bytes())?,
        );
        programs.insert(
            "kmer_spaced_seed",
            node.store().store(build_kmer_spaced_seed().bytes())?,
        );
        programs.insert(
            "kmer_heavy_hash_64",
            node.store().store(build_kmer_heavy_hash_64().bytes())?,
        );
        programs.insert(
            "kmer_branched_hash",
            node.store().store(build_kmer_branched_hash().bytes())?,
        );
        eprintln!(
            "[forge-backend-open] programs registered {} ms total={} ms",
            programs_t0.elapsed().as_millis(),
            open_t0.elapsed().as_millis()
        );

        Ok(Self {
            node,
            atlas,
            programs,
            run_cache: HashMap::new(),
            inspect_cache: HashMap::new(),
        })
    }
}

static WEB_EXPLORER_CLASSIFIER: OnceLock<Program> = OnceLock::new();

struct WebExplorerResolution {
    intent: WebExplorerIntent,
    url: String,
    message: String,
}

fn webexplorer_classifier_program() -> &'static Program {
    WEB_EXPLORER_CLASSIFIER.get_or_init(build_webexplorer_classifier)
}

fn build_webexplorer_classifier() -> Program {
    fn push(nodes: &mut Vec<Node>, node: Node) -> u16 {
        nodes.push(node);
        (nodes.len() - 1) as u16
    }

    fn const_slot(nodes: &mut Vec<Node>, value: i16) -> u16 {
        push(nodes, Node::const_i64(value))
    }

    fn char_eq(nodes: &mut Vec<Node>, vec_slot: u16, idx_slot: u16, ch: i16) -> u16 {
        let chr = push(nodes, Node::v_get(vec_slot, idx_slot));
        let target = const_slot(nodes, ch);
        push(nodes, Node::eq(chr, target))
    }

    fn all(nodes: &mut Vec<Node>, refs: &[u16]) -> u16 {
        let mut iter = refs.iter().copied();
        let Some(mut acc) = iter.next() else { return const_slot(nodes, 1); };
        for next in iter {
            acc = push(nodes, Node::and(acc, next));
        }
        acc
    }

    let mut nodes = Vec::new();
    let vec_input = push(&mut nodes, Node::input_vec(0));
    let has_space_i64 = push(&mut nodes, Node::input(1));
    let has_dot_i64 = push(&mut nodes, Node::input(2));
    let has_slash_i64 = push(&mut nodes, Node::input(3));
    let has_colon_i64 = push(&mut nodes, Node::input(4));
    let len = push(&mut nodes, Node::v_len(vec_input));

    let zero = const_slot(&mut nodes, 0);
    let one = const_slot(&mut nodes, 1);
    let three = const_slot(&mut nodes, 3);
    let four = const_slot(&mut nodes, 4);
    let seven = const_slot(&mut nodes, 7);
    let eight = const_slot(&mut nodes, 8);
    let nine = const_slot(&mut nodes, 9);

    let idx0 = zero;
    let idx1 = one;
    let idx2 = push(&mut nodes, Node::const_i64(2));
    let idx3 = three;
    let idx4 = four;
    let idx5 = push(&mut nodes, Node::const_i64(5));
    let idx6 = push(&mut nodes, Node::const_i64(6));
    let idx7 = seven;
    let idx8 = eight;

    let len_ge_7 = push(&mut nodes, Node::le(seven, len));
    let len_ge_8 = push(&mut nodes, Node::le(eight, len));
    let len_ge_9 = push(&mut nodes, Node::le(nine, len));
    let len_ge_4 = push(&mut nodes, Node::le(four, len));
    let len_ge_3 = push(&mut nodes, Node::le(three, len));

    let http_h0 = char_eq(&mut nodes, vec_input, idx0, 'h' as i16);
    let http_h1 = char_eq(&mut nodes, vec_input, idx1, 't' as i16);
    let http_h2 = char_eq(&mut nodes, vec_input, idx2, 't' as i16);
    let http_h3 = char_eq(&mut nodes, vec_input, idx3, 'p' as i16);
    let http_h4 = char_eq(&mut nodes, vec_input, idx4, ':' as i16);
    let http_h5 = char_eq(&mut nodes, vec_input, idx5, '/' as i16);
    let http_h6 = char_eq(&mut nodes, vec_input, idx6, '/' as i16);
    let http = all(&mut nodes, &[len_ge_7, http_h0, http_h1, http_h2, http_h3, http_h4, http_h5, http_h6]);

    let https_h0 = char_eq(&mut nodes, vec_input, idx0, 'h' as i16);
    let https_h1 = char_eq(&mut nodes, vec_input, idx1, 't' as i16);
    let https_h2 = char_eq(&mut nodes, vec_input, idx2, 't' as i16);
    let https_h3 = char_eq(&mut nodes, vec_input, idx3, 'p' as i16);
    let https_h4 = char_eq(&mut nodes, vec_input, idx4, 's' as i16);
    let https_h5 = char_eq(&mut nodes, vec_input, idx5, ':' as i16);
    let https_h6 = char_eq(&mut nodes, vec_input, idx6, '/' as i16);
    let https_h7 = char_eq(&mut nodes, vec_input, idx7, '/' as i16);
    let https = all(&mut nodes, &[len_ge_8, https_h0, https_h1, https_h2, https_h3, https_h4, https_h5, https_h6, https_h7]);

    let local_h0 = char_eq(&mut nodes, vec_input, idx0, 'l' as i16);
    let local_h1 = char_eq(&mut nodes, vec_input, idx1, 'o' as i16);
    let local_h2 = char_eq(&mut nodes, vec_input, idx2, 'c' as i16);
    let local_h3 = char_eq(&mut nodes, vec_input, idx3, 'a' as i16);
    let local_h4 = char_eq(&mut nodes, vec_input, idx4, 'l' as i16);
    let local_h5 = char_eq(&mut nodes, vec_input, idx5, 'h' as i16);
    let local_h6 = char_eq(&mut nodes, vec_input, idx6, 'o' as i16);
    let local_h7 = char_eq(&mut nodes, vec_input, idx7, 's' as i16);
    let local_h8 = char_eq(&mut nodes, vec_input, idx8, 't' as i16);
    let localhost = all(&mut nodes, &[len_ge_9, local_h0, local_h1, local_h2, local_h3, local_h4, local_h5, local_h6, local_h7, local_h8]);

    let ip127_h0 = char_eq(&mut nodes, vec_input, idx0, '1' as i16);
    let ip127_h1 = char_eq(&mut nodes, vec_input, idx1, '2' as i16);
    let ip127_h2 = char_eq(&mut nodes, vec_input, idx2, '7' as i16);
    let ip127_h3 = char_eq(&mut nodes, vec_input, idx3, '.' as i16);
    let ip_127 = all(&mut nodes, &[len_ge_4, ip127_h0, ip127_h1, ip127_h2, ip127_h3]);

    let ip10_h0 = char_eq(&mut nodes, vec_input, idx0, '1' as i16);
    let ip10_h1 = char_eq(&mut nodes, vec_input, idx1, '0' as i16);
    let ip10_h2 = char_eq(&mut nodes, vec_input, idx2, '.' as i16);
    let ip_10 = all(&mut nodes, &[len_ge_3, ip10_h0, ip10_h1, ip10_h2]);

    let ip192_h0 = char_eq(&mut nodes, vec_input, idx0, '1' as i16);
    let ip192_h1 = char_eq(&mut nodes, vec_input, idx1, '9' as i16);
    let ip192_h2 = char_eq(&mut nodes, vec_input, idx2, '2' as i16);
    let ip192_h3 = char_eq(&mut nodes, vec_input, idx3, '.' as i16);
    let ip192_h4 = char_eq(&mut nodes, vec_input, idx4, '1' as i16);
    let ip192_h5 = char_eq(&mut nodes, vec_input, idx5, '6' as i16);
    let ip192_h6 = char_eq(&mut nodes, vec_input, idx6, '8' as i16);
    let ip192_h7 = char_eq(&mut nodes, vec_input, idx7, '.' as i16);
    let ip_192 = all(&mut nodes, &[len_ge_8, ip192_h0, ip192_h1, ip192_h2, ip192_h3, ip192_h4, ip192_h5, ip192_h6, ip192_h7]);

    let ip000_h0 = char_eq(&mut nodes, vec_input, idx0, '0' as i16);
    let ip000_h1 = char_eq(&mut nodes, vec_input, idx1, '.' as i16);
    let ip000_h2 = char_eq(&mut nodes, vec_input, idx2, '0' as i16);
    let ip000_h3 = char_eq(&mut nodes, vec_input, idx3, '.' as i16);
    let ip000_h4 = char_eq(&mut nodes, vec_input, idx4, '0' as i16);
    let ip000_h5 = char_eq(&mut nodes, vec_input, idx5, '.' as i16);
    let ip000_h6 = char_eq(&mut nodes, vec_input, idx6, '0' as i16);
    let ip_000 = all(&mut nodes, &[len_ge_7, ip000_h0, ip000_h1, ip000_h2, ip000_h3, ip000_h4, ip000_h5, ip000_h6]);

    let scheme_match = push(&mut nodes, Node::or(http, https));
    let local_left = push(&mut nodes, Node::or(localhost, ip_127));
    let local_mid = push(&mut nodes, Node::or(ip_10, ip_192));
    let local_right = push(&mut nodes, Node::or(local_mid, ip_000));
    let local_match = push(&mut nodes, Node::or(local_left, local_right));

    let has_space_eq0 = push(&mut nodes, Node::eq(has_space_i64, zero));
    let has_dot_eq0 = push(&mut nodes, Node::eq(has_dot_i64, zero));
    let has_slash_eq0 = push(&mut nodes, Node::eq(has_slash_i64, zero));
    let has_colon_eq0 = push(&mut nodes, Node::eq(has_colon_i64, zero));
    let has_space = push(&mut nodes, Node::not(has_space_eq0));
    let has_dot = push(&mut nodes, Node::not(has_dot_eq0));
    let has_slash = push(&mut nodes, Node::not(has_slash_eq0));
    let has_colon = push(&mut nodes, Node::not(has_colon_eq0));
    let punct_a = push(&mut nodes, Node::or(has_dot, has_slash));
    let punct = push(&mut nodes, Node::or(punct_a, has_colon));

    let code_search = one;
    let code_url = push(&mut nodes, Node::const_i64(WebExplorerIntent::Url as i16));
    let code_local = push(&mut nodes, Node::const_i64(WebExplorerIntent::Local as i16));

    let choose_punct = push(&mut nodes, Node::select_i64(punct, code_url, code_search));
    let choose_space = push(&mut nodes, Node::select_i64(has_space, code_search, choose_punct));
    let choose_local = push(&mut nodes, Node::select_i64(local_match, code_local, choose_space));
    let final_choice = push(&mut nodes, Node::select_i64(scheme_match, code_url, choose_local));
    push(&mut nodes, Node::output(final_choice, Ty::I64));

    Program::new(Target::Cpu, 5, 1, nodes.len() as u32, nodes)
        .expect("web explorer classifier KASM bien formé")
}

fn webexplorer_feature_flags(input: &str) -> (i64, i64, i64, i64) {
    let lower = input.to_ascii_lowercase();
    let has_space = lower.chars().any(char::is_whitespace) as i64;
    let has_dot = lower.contains('.') as i64;
    let has_slash = lower.contains('/') as i64;
    let has_colon = lower.contains(':') as i64;
    (has_space, has_dot, has_slash, has_colon)
}

fn encode_webexplorer_classifier_args(input: &str) -> Vec<u8> {
    let normalized = input.trim().to_ascii_lowercase();
    let ascii: Vec<i64> = normalized.bytes().map(i64::from).collect();
    let (has_space, has_dot, has_slash, has_colon) = webexplorer_feature_flags(input);
    let mut out = Vec::with_capacity(4 + ascii.len() * 8 + 32);
    out.extend_from_slice(&(ascii.len() as u32).to_le_bytes());
    for value in ascii {
        out.extend_from_slice(&value.to_le_bytes());
    }
    for scalar in [has_space, has_dot, has_slash, has_colon] {
        out.extend_from_slice(&scalar.to_le_bytes());
    }
    out
}

fn classify_webexplorer_input(input: &str) -> Result<WebExplorerIntent, String> {
    let args = encode_webexplorer_classifier_args(input);
    let output = scan::kasm::execute(webexplorer_classifier_program(), &args)
        .map_err(|e| format!("web explorer classifier execute failed: {e}"))?;
    let code_bytes: [u8; 8] = output
        .get(..8)
        .ok_or_else(|| "web explorer classifier returned no scalar output".to_string())?
        .try_into()
        .map_err(|_| "web explorer classifier output shape mismatch".to_string())?;
    Ok(WebExplorerIntent::from_code(i64::from_le_bytes(code_bytes)))
}

fn normalize_webexplorer_query_url(input: &str) -> Result<String, String> {
    Url::parse_with_params("https://www.google.com/search", &[("q", input.trim())])
        .map(|url| url.to_string())
        .map_err(|e| format!("search url build failed: {e}"))
}

fn normalize_webexplorer_direct_url(input: &str, local: bool) -> Result<String, String> {
    let trimmed = input.trim();
    if let Ok(url) = Url::parse(trimmed) {
        return Ok(url.to_string());
    }
    let scheme = if local { "http" } else { "https" };
    Url::parse(&format!("{scheme}://{trimmed}"))
        .map(|url| url.to_string())
        .map_err(|e| format!("direct url parse failed: {e}"))
}

fn build_kmer_hash() -> Program {
    Program::new(
        Target::Cpu,
        1,
        1,
        3,
        vec![Node::input(0), Node::hash64(0), Node::output(1, Ty::I64)],
    )
    .expect("kmer_hash KASM bien formé")
}

fn build_kmer_complement_hash() -> Program {
    Program::new(
        Target::Cpu,
        1,
        1,
        4,
        vec![
            Node::input(0),
            Node::bit_flip(0),
            Node::hash64(1),
            Node::output(2, Ty::I64),
        ],
    )
    .expect("kmer_complement KASM bien formé")
}

fn build_kmer_double_mix() -> Program {
    Program::new(
        Target::Cpu,
        1,
        1,
        4,
        vec![
            Node::input(0),
            Node::hash64(0),
            Node::hash64(1),
            Node::output(2, Ty::I64),
        ],
    )
    .expect("kmer_double_mix KASM bien formé")
}

/// Programme 4 — Strobemer-style : hash low-16 bases + hash high-16
/// bases + XOR combine (9 nœuds). Inspiration : Sahlin 2021,
/// "Effective sequence similarity detection with strobemers and
/// multi-context seeds" (Genome Research). Utilisé en production dans
/// strobealign et le fork minimap2-strobemer pour aligner des reads
/// long ADN. Structurellement décomposable (2× `Hash64`, 2× `Shr`) →
/// candidat type pour Phase 12 cache multi-échelle.
fn build_kmer_strobemer() -> Program {
    Program::new(
        Target::Cpu,
        1,
        1,
        9,
        vec![
            Node::input(0),                // 0 : packed 32-mer
            Node::const_i64(32),           // 1 : décalage 32 bits = 16 bases × 2 bits
            Node::shl(0, 1),               // 2 : clear high half
            Node::shr(2, 1),               // 3 : low 16 bases zero-extended
            Node::hash64(3),               // 4 : hash low half
            Node::shr(0, 1),               // 5 : high 16 bases en bas
            Node::hash64(5),               // 6 : hash high half
            Node::bit_xor(4, 6),           // 7 : combine
            Node::output(7, Ty::I64),
        ],
    )
    .expect("kmer_strobemer KASM bien formé")
}

/// Programme 5 — MinHash signature : chaîne de 10 hash SplitMix64
/// successifs sur le même k-mer. Utilisé en métagénomique (Mash, sourmash)
/// pour construire des sketches comparables entre échantillons. Plus
/// lourd que kmer_hash (×10 ops) — démontre la transition entre "bypass
/// Rust gagne" et "brain cache vaut sa plomberie".
fn build_kmer_minhash_10() -> Program {
    let mut nodes: Vec<Node> = Vec::with_capacity(12);
    nodes.push(Node::input(0)); // 0
    for i in 0..10 {
        nodes.push(Node::hash64(i as u16)); // 1..=10
    }
    nodes.push(Node::output(10, Ty::I64));
    Program::new(Target::Cpu, 1, 1, nodes.len() as u32, nodes)
        .expect("kmer_minhash_10 KASM bien formé")
}

/// Programme 6 — Spaced seed : extrait 4 sous-motifs de 8 bp à des
/// positions espacées (0, 8, 16, 24 = positions de bp dans le k-mer
/// 32 bp), les XOR-mixe, puis hash le résultat. Pattern utilisé par
/// les outils d'alignement type PatternHunter, où les "spaced seeds"
/// donnent une meilleure sensibilité que les contiguous k-mers pour
/// détecter des homologies distantes (séquences évolutivement séparées).
///
/// Structure : 4 const + 4 shifts/masks + 3 XORs + 1 hash + I/O = 16 nodes.
fn build_kmer_spaced_seed() -> Program {
    let nodes = vec![
        Node::input(0),                 // 0 : packed 32-mer
        Node::const_i64(0xFF),          // 1 : mask 8 bits = 4 bp
        Node::const_i64(16),            // 2 : shift 16 = pos bp 8
        Node::const_i64(32),            // 3 : shift 32 = pos bp 16
        Node::const_i64(48),            // 4 : shift 48 = pos bp 24
        Node::bit_and(0, 1),            // 5 : seed_0 = bp[0..4]
        Node::shr(0, 2),                // 6 : k >> 16
        Node::bit_and(6, 1),            // 7 : seed_8 = bp[8..12]
        Node::shr(0, 3),                // 8 : k >> 32
        Node::bit_and(8, 1),            // 9 : seed_16 = bp[16..20]
        Node::shr(0, 4),                // 10: k >> 48
        Node::bit_xor(5, 7),            // 11: seed_0 ^ seed_8
        Node::bit_xor(11, 9),           // 12: + seed_16
        Node::bit_xor(12, 10),          // 13: + seed_24 → final mix
        Node::hash64(13),               // 14: hash mixed
        Node::output(14, Ty::I64),      // 15: output
    ];
    Program::new(Target::Cpu, 1, 1, nodes.len() as u32, nodes)
        .expect("kmer_spaced_seed KASM bien formé")
}

/// Programme 7-bis — Branched hash (KASM v1.0 mutation, utilise Op::Cond).
/// Démontre l'adoption du nouveau opcode `Op::Cond` (JAX `lax.cond`) dans
/// un programme réellement exécuté en production : selon la parité du
/// dernier bit du k-mer (last base = A=00 / C=01 / G=10 / T=11 → parité
/// du LSB), on hash l'original (path "even") ou l'inverse-bytes (path
/// "odd"). C'est un cas d'usage légitime en bioinformatique : les
/// "balanced k-mers" pour réduire la corrélation des sketches.
///
/// Structure : 10 nodes. Le `Op::Cond` apparaît au node 8.
fn build_kmer_branched_hash() -> Program {
    let nodes = vec![
        Node::input(0),                  // 0 : packed 32-mer
        Node::const_i64(1),              // 1 : mask LSB
        Node::const_i64(0),              // 2 : zero (pour Eq)
        Node::bit_and(0, 1),             // 3 : parity bit
        Node::eq(3, 2),                  // 4 : Bool (parity == 0) → even
        Node::hash64(0),                 // 5 : hash(input)
        Node::byteswap(0),               // 6 : byteswap(input)
        Node::hash64(6),                 // 7 : hash(byteswap)
        Node::cond(4, 5, 7),             // 8 : if even then 5 else 7  ← v1.0 Op::Cond !
        Node::output(8, Ty::I64),        // 9 : output
    ];
    Program::new(Target::Cpu, 1, 1, nodes.len() as u32, nodes)
        .expect("kmer_branched_hash KASM bien formé")
}

/// Programme 7 — Heavy hash : chaîne de 64 SplitMix64 successifs.
/// Démonstration "compute > plumbing" : à 64 ops de hash par k-mer,
/// le bypass Rust pur prend le temps de faire 64×5ns = 320 ns par call,
/// et le brain cache amortit sa plomberie (~9 µs/call) sur les
/// 1.47M k-mers distincts seulement (les 3.93M dupes hit RamMemo).
/// Le GPU dominer enfin parce que 64 ops × 5.4M k-mers = ~350M ops
/// se massivent en quelques ms sur les ~1800 cores du RTX 3050.
///
/// Cas d'usage scientifique : "iterated hashing" pour proof-of-work
/// génomique, ou hash chains anti-tampering pour archiver des reads.
fn build_kmer_heavy_hash_64() -> Program {
    let rounds = 64usize;
    let mut nodes: Vec<Node> = Vec::with_capacity(rounds + 2);
    nodes.push(Node::input(0));
    for i in 0..rounds {
        nodes.push(Node::hash64(i as u16));
    }
    nodes.push(Node::output(rounds as u16, Ty::I64));
    Program::new(Target::Cpu, 1, 1, nodes.len() as u32, nodes)
        .expect("kmer_heavy_hash_64 KASM bien formé")
}

/// Slide a k-base window across each DNA sequence + extract class label
/// from each line. Returns parallel vecs : kmers[i] est issu de la classe
/// classes[i]. Format : "<DNA>\t<class>\n", header "sequence\tclass\n".
fn encode_kmers_with_class(bytes: &[u8]) -> (Vec<i64>, Vec<u8>) {
    let mut kmers: Vec<i64> = Vec::new();
    let mut classes: Vec<u8> = Vec::new();
    for line in bytes.split(|&b| b == b'\n') {
        if line.is_empty() || line.starts_with(b"sequence") {
            continue;
        }
        let mut parts = line.split(|&b| b == b'\t');
        let seq = parts.next().unwrap_or(&[]);
        let class_field = parts.next().unwrap_or(&[]);
        let class: u8 = class_field
            .iter()
            .find(|&&b| b.is_ascii_digit())
            .map(|&b| b - b'0')
            .unwrap_or(UNKNOWN_CLASS);
        if seq.len() < K {
            continue;
        }

        let mut window: u64 = 0;
        let mut filled = 0usize;
        for &b in seq {
            let bits: u64 = match b {
                b'A' | b'a' => 0,
                b'C' | b'c' => 1,
                b'G' | b'g' => 2,
                b'T' | b't' => 3,
                _ => {
                    filled = 0;
                    window = 0;
                    continue;
                }
            };
            window = ((window << 2) | bits) & KMER_MASK;
            filled += 1;
            if filled >= K {
                kmers.push(window as i64);
                classes.push(class);
            }
        }
    }
    (kmers, classes)
}

/// Decode a packed i64 k-mer back to its ACGT string for display.
fn decode_kmer(packed: i64) -> String {
    let mut s = vec![0u8; K];
    let mut bits = packed as u64;
    for i in (0..K).rev() {
        s[i] = match bits & 0b11 {
            0 => b'A',
            1 => b'C',
            2 => b'G',
            _ => b'T',
        };
        bits >>= 2;
    }
    String::from_utf8(s).expect("ACGT bytes valid utf8")
}

#[derive(Clone, Serialize)]
struct ProcessReport {
    kind: String,
    total_kmers: usize,
    distinct: usize,
    elapsed_ms: f64,
    ns_per_kmer: f64,
}

