fn native_bounds_equal(a: &WebExplorerMemoryBounds, b: &WebExplorerMemoryBounds) -> bool {
    (a.x - b.x).abs() <= 0.5
        && (a.y - b.y).abs() <= 0.5
        && (a.width - b.width).abs() <= 0.5
        && (a.height - b.height).abs() <= 0.5
}

const NATIVE_CHILD_TOP_INTERACTION_GUARD: f64 = 52.0;

fn guarded_native_visible_bounds(mut bounds: WebExplorerMemoryBounds) -> WebExplorerMemoryBounds {
    if bounds.y < NATIVE_CHILD_TOP_INTERACTION_GUARD {
        let delta = NATIVE_CHILD_TOP_INTERACTION_GUARD - bounds.y;
        bounds.y = NATIVE_CHILD_TOP_INTERACTION_GUARD;
        bounds.height = (bounds.height - delta).max(2.0);
    }
    bounds
}

fn native_logical_bounds(bounds: &WebExplorerMemoryBounds) -> Rect {
    Rect {
        position: Position::Logical(LogicalPosition::new(bounds.x, bounds.y)),
        size: Size::Logical(LogicalSize::new(bounds.width, bounds.height)),
    }
}

fn set_native_webview_bounds<R: Runtime>(
    webview: &Webview<R>,
    bounds: &WebExplorerMemoryBounds,
) -> Result<(), String> {
    webview
        .set_bounds(native_logical_bounds(bounds))
        .map_err(|e| e.to_string())
}

