#[tauri::command]
fn webexplorer_analysis_snapshot(
    app: tauri::AppHandle,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<WebExplorerAnalysisSnapshot, String> {
    let mut state = state.lock().map_err(|e| e.to_string())?;
    let mut analysis = state.active_web_explorer_mut().analysis_snapshot();
    let (atlas_checked, atlas_hit) = if let Some(backend) = state.backend.as_ref() {
        let key = webexplorer_atlas_cache_key(&analysis.snapshot.tree_hash);
        if backend.atlas.lookup_result(&key).is_some() {
            (true, true)
        } else {
            let result_hash = webexplorer_atlas_result_hash(&analysis);
            let _ = backend.atlas.record_result(&key, &result_hash);
            (true, false)
        }
    } else {
        (false, false)
    };
    state
        .active_web_explorer_mut()
        .apply_atlas_proof(&mut analysis, atlas_checked, atlas_hit);
    if webexplorer_auto_export_enabled() && analysis.snapshot.node_count > 0 {
        match build_webexplorer_clone_export(&analysis.snapshot) {
            Ok(result) => alpha_trace(
                &app,
                "webexplorer.clone",
                format!(
                    "analysis.export.ok html={} json={} nodes={} frames={} text={} images={}",
                    result.html_path,
                    result.json_path,
                    result.exported_nodes,
                    result.exported_frames,
                    result.exported_text,
                    result.exported_images
                ),
            ),
            Err(err) => alpha_trace(&app, "webexplorer.clone", format!("analysis.export.error {err}")),
        }
    }
    Ok(analysis)
}

