#[tauri::command]
async fn voice_tts_generate(
    request: VoiceTtsRequest,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<VoiceTtsResponse, String> {
    let store_path = state
        .lock()
        .map_err(|_| "Forge state lock poisoned.".to_string())?
        .store_path
        .clone();
    let text = sanitize_voice_text(&request.text);
    if text.is_empty() {
        return Err("No text to speak.".to_string());
    }
    let chars = text.chars().count();
    let eleven_voice = request
        .eleven_voice_id
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .unwrap_or(ELEVENLABS_DEFAULT_VOICE_ID);
    let eleven_model = request
        .eleven_model_id
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .unwrap_or("eleven_v3");
    let orpheus_endpoint = request.orpheus_endpoint.as_deref().map(str::trim).unwrap_or("");
    let orpheus_voice = request
        .orpheus_voice
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .unwrap_or("tara");
    let monthly_limit = request.monthly_limit.unwrap_or(10_000).max(500);
    let cache_dir = voice_cache_dir(&store_path);
    std::fs::create_dir_all(&cache_dir).map_err(|e| format!("create voice cache: {e}"))?;

    let mut errors = Vec::<String>::new();
    let prefer_orpheus = request.prefer_orpheus.unwrap_or(false);
    let mut engines = Vec::<&str>::new();
    if prefer_orpheus {
        engines.extend(["orpheus", "elevenlabs"]);
    } else {
        engines.extend(["elevenlabs", "orpheus"]);
    }

    for engine in engines {
        if engine == "elevenlabs" {
            let Some((api_key, _)) = elevenlabs_configured_api_key() else {
                errors.push("ElevenLabs key is not configured.".to_string());
                continue;
            };
            let mut usage = read_voice_usage();
            if usage.eleven_chars.saturating_add(chars as u64) > monthly_limit {
                errors.push(format!(
                    "ElevenLabs local quota guard reached: {} + {} > {} chars.",
                    usage.eleven_chars, chars, monthly_limit
                ));
                continue;
            }

            let expressive_model = "eleven_v3";
            let natural_model = "eleven_multilingual_v2";
            let mut attempts = Vec::<(String, String, bool, bool)>::new();
            attempts.push((eleven_voice.to_string(), eleven_model.to_string(), false, false));
            if eleven_model != expressive_model {
                attempts.push((eleven_voice.to_string(), expressive_model.to_string(), false, true));
            }
            if eleven_model != natural_model {
                attempts.push((eleven_voice.to_string(), natural_model.to_string(), false, true));
            }
            for (voice_id, model_id, fallback_voice, fallback_model) in attempts {
                let cache_key = voice_cache_key("elevenlabs", &model_id, &voice_id, &text);
                let cache_path = cache_dir.join(format!("{cache_key}.mp3"));
                if let Ok(bytes) = std::fs::read(&cache_path) {
                    let message = match (fallback_voice, fallback_model) {
                        (true, true) => format!("Custom ElevenLabs voice `{eleven_voice}` and model `{eleven_model}` were unavailable; replayed cached audio with the default voice on `{model_id}`."),
                        (true, false) => format!("Custom ElevenLabs voice `{eleven_voice}` was unavailable; replayed cached audio with the default voice."),
                        (false, true) => format!("Model `{eleven_model}` was unavailable for voice `{eleven_voice}`; replayed cached audio with `{model_id}`."),
                        (false, false) => "Voice audio replayed from local cache.".to_string(),
                    };
                    return Ok(VoiceTtsResponse {
                        ok: true,
                        engine: "elevenlabs".to_string(),
                        cached: true,
                        chars,
                        content_type: "audio/mpeg".to_string(),
                        audio_base64: BASE64_STANDARD.encode(bytes),
                        cache_key,
                        message,
                    });
                }
                match request_elevenlabs_speech(&api_key, &text, &voice_id, &model_id).await {
                    Ok((bytes, content_type)) => {
                        std::fs::write(&cache_path, &bytes).map_err(|e| format!("write voice cache: {e}"))?;
                        usage.eleven_chars = usage.eleven_chars.saturating_add(chars as u64);
                        let _ = write_voice_usage(&usage);
                        let message = match (fallback_voice, fallback_model) {
                            (true, true) => format!("Custom ElevenLabs voice `{eleven_voice}` and model `{eleven_model}` were unavailable via API; generated audio with the default voice on `{model_id}`."),
                            (true, false) => format!("Custom ElevenLabs voice `{eleven_voice}` was unavailable via API; generated audio with the default voice."),
                            (false, true) => format!("Voice `{eleven_voice}` worked after falling back from `{eleven_model}` to `{model_id}`."),
                            (false, false) => "Voice audio generated with ElevenLabs stream.".to_string(),
                        };
                        return Ok(VoiceTtsResponse {
                            ok: true,
                            engine: "elevenlabs".to_string(),
                            cached: false,
                            chars,
                            content_type,
                            audio_base64: BASE64_STANDARD.encode(bytes),
                            cache_key,
                            message,
                        });
                    }
                    Err(err) => {
                        errors.push(format!("ElevenLabs voice `{voice_id}` with model `{model_id}` failed: {err}"));
                    }
                }
            }
        } else {
            if orpheus_endpoint.is_empty() {
                errors.push("Orpheus endpoint is not configured.".to_string());
                continue;
            }
            let cache_key = voice_cache_key("orpheus", "orpheus", orpheus_voice, &text);
            let cache_path = cache_dir.join(format!("{cache_key}.mp3"));
            if let Ok(bytes) = std::fs::read(&cache_path) {
                return Ok(VoiceTtsResponse {
                    ok: true,
                    engine: "orpheus".to_string(),
                    cached: true,
                    chars,
                    content_type: "audio/mpeg".to_string(),
                    audio_base64: BASE64_STANDARD.encode(bytes),
                    cache_key,
                    message: "Voice audio replayed from local Orpheus cache.".to_string(),
                });
            }
            match request_orpheus_speech(orpheus_endpoint, &text, orpheus_voice).await {
                Ok((bytes, content_type)) => {
                    std::fs::write(&cache_path, &bytes).map_err(|e| format!("write Orpheus voice cache: {e}"))?;
                    return Ok(VoiceTtsResponse {
                        ok: true,
                        engine: "orpheus".to_string(),
                        cached: false,
                        chars,
                        content_type,
                        audio_base64: BASE64_STANDARD.encode(bytes),
                        cache_key,
                        message: "Voice audio generated with Orpheus fallback.".to_string(),
                    });
                }
                Err(err) => errors.push(err),
            }
        }
    }

    Err(format!("Voice generation failed. {}", errors.join(" | ")))
}

#[tauri::command]
async fn voice_stt_transcribe(request: VoiceSttRequest) -> Result<VoiceSttResponse, String> {
    let Some((api_key, _)) = elevenlabs_configured_api_key() else {
        return Err("No ElevenLabs API key configured for dictation.".to_string());
    };
    let audio = BASE64_STANDARD
        .decode(request.audio_base64.trim())
        .map_err(|e| format!("decode dictation audio: {e}"))?;
    if audio.len() < 512 {
        return Err("Dictation audio is too short.".to_string());
    }
    if audio.len() > 25 * 1024 * 1024 {
        return Err("Dictation audio is too large for this Forge request.".to_string());
    }
    let model_id = request
        .model_id
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .unwrap_or("scribe_v2")
        .to_string();
    let mime_type = request
        .mime_type
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .unwrap_or("audio/webm")
        .to_string();
    let value = request_elevenlabs_transcript(
        &api_key,
        audio,
        &mime_type,
        &model_id,
        request.language_code.as_deref(),
    )
    .await?;
    let text = value
        .get("text")
        .and_then(JsonValue::as_str)
        .unwrap_or("")
        .trim()
        .to_string();
    if text.is_empty() {
        return Err("ElevenLabs returned an empty transcript.".to_string());
    }
    Ok(VoiceSttResponse {
        ok: true,
        engine: "elevenlabs_scribe".to_string(),
        model_id,
        text: text.clone(),
        language_code: value
            .get("language_code")
            .and_then(JsonValue::as_str)
            .map(|s| s.to_string()),
        language_probability: value.get("language_probability").and_then(JsonValue::as_f64),
        message: format!(
            "Dictation transcribed with ElevenLabs Scribe ({} chars).",
            text.chars().count()
        ),
    })
}

fn gemini_command_candidates() -> Vec<PathBuf> {
    let mut out = Vec::new();
    let mut seen = HashSet::<PathBuf>::new();
    let mut push = |path: PathBuf| {
        if seen.insert(path.clone()) {
            out.push(path);
        }
    };
    if let Some(path) = std::env::var_os("FORGE_GEMINI_BIN") {
        push(PathBuf::from(path));
    }
    if let Some(appdata) = std::env::var_os("APPDATA") {
        let npm = PathBuf::from(appdata).join("npm");
        push(npm.join("gemini.exe"));
        push(npm.join("gemini.cmd"));
        push(npm.join("gemini"));
    }
    if let Some(home) = forge_home_dir() {
        let npm = home.join("AppData").join("Roaming").join("npm");
        push(npm.join("gemini.exe"));
        push(npm.join("gemini.cmd"));
        push(npm.join("gemini"));
    }
    if let Some(paths) = std::env::var_os("PATH") {
        for dir in std::env::split_paths(&paths) {
            push(dir.join("gemini.exe"));
            push(dir.join("gemini.cmd"));
            push(dir.join("gemini"));
        }
    }
    push(PathBuf::from("gemini.exe"));
    push(PathBuf::from("gemini.cmd"));
    push(PathBuf::from("gemini"));
    out
}

fn gemini_cli_probe(candidate: &Path) -> bool {
    if !candidate.exists() && candidate.is_absolute() {
        return false;
    }
    let mut command = gemini_cli_command(candidate);
    command.arg("--version");
    run_command_capture_timeout(command, Duration::from_secs(3))
        .map(|(ok, _, _)| ok)
        .unwrap_or(false)
}

fn gemini_cli_any_candidate_exists() -> bool {
    gemini_command_candidates()
        .into_iter()
        .any(|path| path.is_absolute() && path.exists())
}

fn gemini_cli_binary_path() -> Option<PathBuf> {
    let candidates = gemini_command_candidates();
    candidates
        .into_iter()
        .find(|path| gemini_cli_probe(path))
}

fn is_windows_batch_candidate(path: &Path) -> bool {
    path.extension()
        .and_then(|ext| ext.to_str())
        .map(|ext| ext.eq_ignore_ascii_case("cmd") || ext.eq_ignore_ascii_case("bat"))
        .unwrap_or(false)
}

fn nested_npm_target(parent: &Path, parts: &[&str]) -> PathBuf {
    let mut path = parent.to_path_buf();
    for part in parts {
        path = path.join(part);
    }
    path
}

fn command_for_node_npm_shim(candidate: &Path, script_parts: &[&str]) -> Option<Command> {
    if !is_windows_batch_candidate(candidate) {
        return None;
    }
    let parent = candidate.parent()?;
    let script = nested_npm_target(parent, script_parts);
    if !script.exists() {
        return None;
    }
    let local_node = parent.join("node.exe");
    let node = if local_node.exists() {
        local_node
    } else {
        node_binary_path().unwrap_or_else(|| PathBuf::from("node"))
    };
    let mut command = Command::new(node);
    command.arg(script);
    Some(command)
}

fn node_binary_path() -> Option<PathBuf> {
    let mut candidates = Vec::<PathBuf>::new();
    let mut seen = HashSet::<PathBuf>::new();
    let mut push = |path: PathBuf| {
        if seen.insert(path.clone()) {
            candidates.push(path);
        }
    };
    if let Some(path) = std::env::var_os("FORGE_NODE_BIN") {
        push(PathBuf::from(path));
    }
    if let Some(paths) = std::env::var_os("PATH") {
        for dir in std::env::split_paths(&paths) {
            push(dir.join("node.exe"));
            push(dir.join("node"));
        }
    }
    if let Some(program_files) = std::env::var_os("ProgramFiles") {
        push(PathBuf::from(program_files).join("nodejs").join("node.exe"));
    }
    if let Some(program_files_x86) = std::env::var_os("ProgramFiles(x86)") {
        push(PathBuf::from(program_files_x86).join("nodejs").join("node.exe"));
    }
    push(PathBuf::from("node.exe"));
    push(PathBuf::from("node"));
    candidates.into_iter().find(|path| {
        if path.is_absolute() {
            path.exists()
        } else {
            let mut command = Command::new(path);
            command.arg("--version");
            run_command_capture_timeout(command, Duration::from_secs(2))
                .map(|(ok, _, _)| ok)
                .unwrap_or(false)
        }
    })
}

fn npm_binary_path() -> Option<PathBuf> {
    let mut candidates = Vec::<PathBuf>::new();
    let mut seen = HashSet::<PathBuf>::new();
    let mut push = |path: PathBuf| {
        if seen.insert(path.clone()) {
            candidates.push(path);
        }
    };
    if let Some(path) = std::env::var_os("FORGE_NPM_BIN") {
        push(PathBuf::from(path));
    }
    if let Some(paths) = std::env::var_os("PATH") {
        for dir in std::env::split_paths(&paths) {
            push(dir.join("npm.cmd"));
            push(dir.join("npm.exe"));
            push(dir.join("npm"));
        }
    }
    if let Some(program_files) = std::env::var_os("ProgramFiles") {
        let base = PathBuf::from(program_files).join("nodejs");
        push(base.join("npm.cmd"));
        push(base.join("npm.exe"));
    }
    if let Some(program_files_x86) = std::env::var_os("ProgramFiles(x86)") {
        let base = PathBuf::from(program_files_x86).join("nodejs");
        push(base.join("npm.cmd"));
        push(base.join("npm.exe"));
    }
    push(PathBuf::from("npm.cmd"));
    push(PathBuf::from("npm"));
    candidates.into_iter().find(|path| {
        if path.is_absolute() {
            path.exists()
        } else {
            let mut command = Command::new(path);
            command.arg("--version");
            run_command_capture_timeout(command, Duration::from_secs(2))
                .map(|(ok, _, _)| ok)
                .unwrap_or(false)
        }
    })
}

fn command_for_exe_npm_shim(candidate: &Path, exe_parts: &[&str]) -> Option<Command> {
    if !is_windows_batch_candidate(candidate) {
        return None;
    }
    let parent = candidate.parent()?;
    let exe = nested_npm_target(parent, exe_parts);
    if exe.exists() {
        Some(Command::new(exe))
    } else {
        None
    }
}

#[derive(Clone, Copy)]
struct GeminiBootstrapStatus {
    node_available: bool,
    npm_available: bool,
}

fn gemini_bootstrap_status() -> GeminiBootstrapStatus {
    GeminiBootstrapStatus {
        node_available: node_binary_path().is_some(),
        npm_available: npm_binary_path().is_some(),
    }
}

fn gemini_cli_command(candidate: &Path) -> Command {
    command_for_node_npm_shim(
        candidate,
        &["node_modules", "@google", "gemini-cli", "bundle", "gemini.js"],
    )
    .unwrap_or_else(|| Command::new(candidate))
}

fn claude_cli_command(candidate: &Path) -> Command {
    command_for_exe_npm_shim(
        candidate,
        &[
            "node_modules",
            "@anthropic-ai",
            "claude-code",
            "bin",
            "claude.exe",
        ],
    )
    .unwrap_or_else(|| Command::new(candidate))
}

fn gemini_cli_status(model_ref: Option<&str>) -> OpenAiSubscriptionStatus {
    let candidate = gemini_cli_binary_path();
    let installed = candidate.is_some();
    let candidate_exists_but_unusable = !installed && gemini_cli_any_candidate_exists();
    let bootstrap = gemini_bootstrap_status();
    let api_key = gemini_configured_api_key();
    let oauth_present = gemini_oauth_credentials_present();
    let connected = installed && (api_key.is_some() || oauth_present);
    let auth_source = if !installed {
        if candidate_exists_but_unusable {
            "Gemini CLI found but not executable".to_string()
        } else {
            "none".to_string()
        }
    } else if let Some((_, source)) = api_key.as_ref() {
        format!("Gemini API key ({source})")
    } else if oauth_present {
        "Google OAuth (~/.gemini/oauth_creds.json)".to_string()
    } else {
        "Gemini CLI installed".to_string()
    };
    let message = if candidate_exists_but_unusable {
        "Gemini CLI was found on disk, but Forge could not execute it. Reinstall Gemini CLI or fix its permissions, then refresh.".to_string()
    } else if !installed && !bootstrap.node_available {
        "Gemini CLI is missing, and Node.js is not available on this machine yet. Forge needs Node.js to install Gemini CLI automatically.".to_string()
    } else if !installed && !bootstrap.npm_available {
        "Gemini CLI is missing, and npm is not available on this machine yet. Forge needs a working Node.js/npm runtime to install Gemini CLI automatically.".to_string()
    } else if !installed {
        "Gemini CLI is missing, but Forge can install it automatically inside the embedded Gemini terminal.".to_string()
    } else if api_key.is_some() {
        "Gemini CLI is ready with a Forge configured API key.".to_string()
    } else if oauth_present {
        "Gemini CLI is ready through existing Google OAuth. You can save an API key for headless reliability."
            .to_string()
    } else {
        "Gemini CLI is installed, but no Gemini API key or Google OAuth credentials were found."
            .to_string()
    };
    let status = OpenAiSubscriptionStatus {
        connected,
        installed,
        auth_source,
        account_label: candidate.as_ref().map(|path| {
            path.file_name()
                .and_then(|s| s.to_str())
                .unwrap_or("gemini")
                .to_string()
        }),
        last_refresh: None,
        model_ref: gemini_bridge_model_arg(model_ref)
            .unwrap_or_else(|| "gemini-2.5-pro".to_string()),
        message,
    };
    if status.installed || status.connected {
        remember_provider_cli_health("gemini", &status);
    }
    sticky_provider_cli_status("gemini", status, candidate_exists_but_unusable)
}

fn gemini_bridge_model_arg(model_ref: Option<&str>) -> Option<String> {
    let raw = model_ref.unwrap_or("").trim();
    if raw.is_empty() {
        return None;
    }
    let model = raw
        .strip_prefix("google-gemini/")
        .or_else(|| raw.strip_prefix("google/"))
        .unwrap_or(raw)
        .trim();
    if model.is_empty()
        || model.len() > 90
        || !model
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '.' | '-' | '_' | '/'))
    {
        return None;
    }
    Some(model.to_string())
}

