fn env_value_present(key: &str) -> bool {
    std::env::var(key)
        .map(|value| !value.trim().is_empty())
        .unwrap_or(false)
}

fn claude_credentials_present() -> bool {
    let config_dir = std::env::var_os("CLAUDE_CONFIG_DIR")
        .map(PathBuf::from)
        .or_else(|| forge_home_dir().map(|home| home.join(".claude")));
    config_dir
        .map(|dir| dir.join(".credentials.json"))
        .filter(|path| {
            std::fs::metadata(path)
                .map(|meta| meta.len() > 16)
                .unwrap_or(false)
        })
        .is_some()
}

fn run_command_capture_timeout(
    mut command: Command,
    timeout: Duration,
) -> Result<(bool, String, String), String> {
    command
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    let mut child = command
        .spawn()
        .map_err(|e| format!("start command: {e}"))?;
    let pid = child.id();
    let stdout = child.stdout.take();
    let stderr = child.stderr.take();
    let stdout_handle = stdout.map(|stream| {
        thread::spawn(move || {
            let mut text = String::new();
            let _ = BufReader::new(stream).read_to_string(&mut text);
            text
        })
    });
    let stderr_handle = stderr.map(|stream| {
        thread::spawn(move || {
            let mut text = String::new();
            let _ = BufReader::new(stream).read_to_string(&mut text);
            text
        })
    });
    let started = Instant::now();
    let status = loop {
        match child.try_wait() {
            Ok(Some(status)) => break status,
            Ok(None) => {}
            Err(err) => return Err(format!("wait command: {err}")),
        }
        if started.elapsed() >= timeout {
            let _ = kill_process_tree(pid);
            let _ = child.kill();
            let _ = child.wait();
            return Err("command timed out".to_string());
        }
        thread::sleep(Duration::from_millis(80));
    };
    let stdout_text = stdout_handle
        .and_then(|handle| handle.join().ok())
        .unwrap_or_default();
    let stderr_text = stderr_handle
        .and_then(|handle| handle.join().ok())
        .unwrap_or_default();
    Ok((status.success(), stdout_text, stderr_text))
}

fn claude_auth_status_from_cli(candidate: &Path) -> Option<(bool, String, String)> {
    let mut command = claude_cli_command(candidate);
    command
        .arg("auth")
        .arg("status")
        .env_remove("ANTHROPIC_API_KEY")
        .env_remove("ANTHROPIC_AUTH_TOKEN")
        .env_remove("CLAUDE_CODE_USE_BEDROCK")
        .env_remove("CLAUDE_CODE_USE_VERTEX")
        .env_remove("CLAUDE_CODE_USE_FOUNDRY");
    let (_, stdout, stderr) = run_command_capture_timeout(command, Duration::from_secs(4)).ok()?;
    let text = if stdout.trim().is_empty() {
        stderr.trim()
    } else {
        stdout.trim()
    };
    let value: JsonValue = serde_json::from_str(text).ok()?;
    let logged_in = value
        .get("loggedIn")
        .or_else(|| value.get("logged_in"))
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let auth_method = value
        .get("authMethod")
        .or_else(|| value.get("auth_method"))
        .and_then(|v| v.as_str())
        .unwrap_or("unknown")
        .to_string();
    let api_provider = value
        .get("apiProvider")
        .or_else(|| value.get("api_provider"))
        .and_then(|v| v.as_str())
        .unwrap_or("unknown")
        .to_string();
    Some((logged_in, auth_method, api_provider))
}

fn claude_bridge_model_arg(model_ref: Option<&str>) -> Option<String> {
    let raw = model_ref.unwrap_or("").trim();
    if raw.is_empty()
        || raw.eq_ignore_ascii_case("default")
        || raw.eq_ignore_ascii_case("claude-default")
        || raw.eq_ignore_ascii_case("claude-code-default")
    {
        return None;
    }
    let model = raw
        .strip_prefix("anthropic/")
        .or_else(|| raw.strip_prefix("claude/"))
        .unwrap_or(raw)
        .trim();
    if model.is_empty()
        || model.len() > 90
        || !model
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '.' | '-' | '_' | '/'))
    {
        return None;
    }
    Some(model.to_string())
}

fn claude_cli_status(model_ref: Option<&str>) -> OpenAiSubscriptionStatus {
    let candidate = claude_cli_binary_path();
    let installed = candidate.is_some();
    let candidate_exists_but_unusable = !installed && claude_cli_any_candidate_exists();
    let bootstrap = gemini_bootstrap_status();
    let cli_auth = candidate
        .as_ref()
        .and_then(|path| claude_auth_status_from_cli(path));
    let oauth_env = env_value_present("CLAUDE_CODE_OAUTH_TOKEN");
    let credentials_fallback = cli_auth.is_none() && claude_credentials_present();
    let cli_logged_in = cli_auth
        .as_ref()
        .map(|(logged_in, _, _)| *logged_in)
        .unwrap_or(false);
    let connected = installed && (cli_logged_in || oauth_env || credentials_fallback);
    let auth_source = if !installed {
        if candidate_exists_but_unusable {
            "Claude CLI found but not executable".to_string()
        } else {
            "none".to_string()
        }
    } else if oauth_env {
        "Claude subscription OAuth token (CLAUDE_CODE_OAUTH_TOKEN)".to_string()
    } else if let Some((true, auth_method, api_provider)) = cli_auth.as_ref() {
        if api_provider.eq_ignore_ascii_case("firstParty")
            || auth_method.to_ascii_lowercase().contains("oauth")
        {
            "Claude.ai subscription OAuth".to_string()
        } else {
            format!("Claude Code auth ({auth_method}/{api_provider})")
        }
    } else if credentials_fallback {
        "Claude Code credentials file".to_string()
    } else {
        "Claude Code CLI installed".to_string()
    };
    let message = if candidate_exists_but_unusable {
        "Claude Code CLI was found on disk, but Forge could not execute it. Reinstall Claude Code or fix its permissions, then refresh.".to_string()
    } else if !installed && !bootstrap.node_available {
        "Claude Code CLI is missing, and Node.js is not available on this machine yet. Forge needs Node.js to install Claude automatically.".to_string()
    } else if !installed && !bootstrap.npm_available {
        "Claude Code CLI is missing, and npm is not available on this machine yet. Forge needs a working Node.js/npm runtime to install Claude automatically.".to_string()
    } else if !installed {
        "Claude Code CLI is missing, but Forge can install it automatically inside the embedded Claude terminal.".to_string()
    } else if connected && oauth_env {
        "Claude Code is ready through a Claude subscription OAuth token.".to_string()
    } else if let Some((true, _, api_provider)) = cli_auth.as_ref() {
        if api_provider.eq_ignore_ascii_case("firstParty") {
            "Claude Code is ready through Claude.ai subscription OAuth.".to_string()
        } else {
            "Claude Code is authenticated, but not explicitly through first-party Claude.ai OAuth."
                .to_string()
        }
    } else if credentials_fallback {
        "Claude Code credentials are present. Refresh if the CLI reports auth issues.".to_string()
    } else if let Some((false, auth_method, api_provider)) = cli_auth.as_ref() {
        format!(
            "Claude Code CLI is installed but not logged in ({auth_method}/{api_provider}). Use Connect Claude subscription."
        )
    } else {
        "Claude Code CLI is installed, but Forge could not verify Claude.ai auth. Use Connect Claude subscription."
            .to_string()
    };
    let status = OpenAiSubscriptionStatus {
        connected,
        installed,
        auth_source,
        account_label: candidate.as_ref().map(|path| {
            path.file_name()
                .and_then(|s| s.to_str())
                .unwrap_or("claude")
                .to_string()
        }),
        last_refresh: None,
        model_ref: claude_bridge_model_arg(model_ref)
            .unwrap_or_else(|| "claude-code-default".to_string()),
        message,
    };
    if status.installed || status.connected {
        remember_provider_cli_health("claude", &status);
    }
    sticky_provider_cli_status("claude", status, candidate_exists_but_unusable)
}

fn ensure_gemini_forge_mcp_settings(
    store_path: &Path,
    active_job_id: Option<&str>,
) -> Result<PathBuf, String> {
    let workspace = forge_workspace_dir();
    let gemini_dir = workspace.join(".gemini");
    std::fs::create_dir_all(&gemini_dir)
        .map_err(|e| format!("create Gemini settings directory: {e}"))?;
    let settings_path = gemini_dir.join("settings.json");
    let mut settings = std::fs::read_to_string(&settings_path)
        .ok()
        .and_then(|text| serde_json::from_str::<JsonValue>(&text).ok())
        .unwrap_or_else(|| json!({}));
    if !settings.is_object() {
        settings = json!({});
    }
    let forge_mcp = forge_mcp_binary_path()?;
    let root = settings.as_object_mut().expect("settings object");
    let servers = root
        .entry("mcpServers".to_string())
        .or_insert_with(|| json!({}));
    if !servers.is_object() {
        *servers = json!({});
    }
    let mut env = json!({
        "FORGE_STORE_DIR": store_path.display().to_string(),
        "FORGE_MCP_MODEL": "forge-gemini-cli"
    });
    if let Some(job_id) = active_job_id.map(str::trim).filter(|v| !v.is_empty()) {
        env["FORGE_ACTIVE_JOB_ID"] = json!(job_id);
    }
    servers
        .as_object_mut()
        .expect("mcpServers object")
        .insert(
            "forge".to_string(),
            json!({
                "command": forge_mcp.display().to_string(),
                "cwd": workspace.display().to_string(),
                "env": env,
                "timeout": 600000,
                "trust": true
            }),
        );
    let bytes = serde_json::to_vec_pretty(&settings)
        .map_err(|e| format!("encode Gemini settings: {e}"))?;
    std::fs::write(&settings_path, bytes)
        .map_err(|e| format!("write Gemini settings: {e}"))?;
    Ok(settings_path)
}

fn ensure_claude_forge_mcp_config(
    store_path: &Path,
    active_job_id: Option<&str>,
) -> Result<PathBuf, String> {
    let workspace = forge_workspace_dir();
    let claude_dir = workspace.join(".claude");
    std::fs::create_dir_all(&claude_dir)
        .map_err(|e| format!("create Claude config directory: {e}"))?;
    let config_path = claude_dir.join("forge-mcp.json");
    let forge_mcp = forge_mcp_binary_path()?;
    let mut env = json!({
        "FORGE_STORE_DIR": store_path.display().to_string(),
        "FORGE_MCP_MODEL": "forge-claude-code"
    });
    if let Some(job_id) = active_job_id.map(str::trim).filter(|v| !v.is_empty()) {
        env["FORGE_ACTIVE_JOB_ID"] = json!(job_id);
    }
    let config = json!({
        "mcpServers": {
            "forge": {
                "command": forge_mcp.display().to_string(),
                "cwd": workspace.display().to_string(),
                "env": env
            }
        }
    });
    let bytes = serde_json::to_vec_pretty(&config)
        .map_err(|e| format!("encode Claude MCP config: {e}"))?;
    std::fs::write(&config_path, bytes)
        .map_err(|e| format!("write Claude MCP config: {e}"))?;
    Ok(config_path)
}

#[allow(dead_code)]
fn wait_child_with_timeout(
    child: &mut std::process::Child,
    timeout: Duration,
) -> Result<Option<std::process::ExitStatus>, String> {
    let started = Instant::now();
    loop {
        match child.try_wait() {
            Ok(Some(status)) => return Ok(Some(status)),
            Ok(None) => {}
            Err(err) => return Err(format!("wait Codex process: {err}")),
        }
        if started.elapsed() >= timeout {
            let _ = child.kill();
            let _ = child.wait();
            return Ok(None);
        }
        thread::sleep(Duration::from_millis(120));
    }
}

