fn semantic_cache_signature(text: &str) -> (String, Vec<String>) {
    const STOP_WORDS: &[&str] = &[
        "a", "ai", "au", "aux", "avec", "ce", "ces", "cest", "c'est", "dans", "de", "des",
        "du", "elle", "en", "est", "et", "il", "je", "j", "la", "le", "les", "me", "moi",
        "mon", "ma", "mes", "ne", "on", "ou", "où", "pas", "peux", "peut", "pour", "que",
        "qui", "quoi", "se", "sur", "ta", "te", "tes", "toi", "ton", "tu", "un", "une",
        "vous", "the", "a", "an", "and", "are", "can", "for", "how", "i", "in", "is",
        "it", "me", "of", "on", "or", "that", "to", "what", "you",
    ];
    let mut cleaned = String::with_capacity(text.len());
    for ch in text.to_lowercase().chars() {
        if ch.is_alphanumeric() {
            cleaned.push(ch);
        } else {
            cleaned.push(' ');
        }
    }
    let mut tokens = cleaned
        .split_whitespace()
        .filter(|token| token.len() >= 2 && !STOP_WORDS.contains(token))
        .take(64)
        .map(str::to_string)
        .collect::<Vec<_>>();
    tokens.sort();
    tokens.dedup();
    let normalized = tokens.join(" ");
    (normalized, tokens)
}

fn semantic_cache_similarity(left: &[String], right: &[String]) -> f64 {
    if left.is_empty() || right.is_empty() {
        return 0.0;
    }
    let mut i = 0usize;
    let mut j = 0usize;
    let mut intersection = 0usize;
    while i < left.len() && j < right.len() {
        match left[i].cmp(&right[j]) {
            std::cmp::Ordering::Equal => {
                intersection += 1;
                i += 1;
                j += 1;
            }
            std::cmp::Ordering::Less => i += 1,
            std::cmp::Ordering::Greater => j += 1,
        }
    }
    if intersection == 0 {
        return 0.0;
    }
    let union = left.len() + right.len() - intersection;
    let jaccard = intersection as f64 / union as f64;
    let containment = intersection as f64 / left.len().min(right.len()) as f64;
    let length_ratio = left.len().min(right.len()) as f64 / left.len().max(right.len()) as f64;
    (jaccard * 0.7 + containment * 0.3) * length_ratio.sqrt()
}

fn semantic_cache_is_cacheable(user_message: &str, assistant_message: &str) -> bool {
    let user_len = user_message.trim().chars().count();
    let assistant_len = assistant_message.trim().chars().count();
    (8..=700).contains(&user_len) && (2..=2_000).contains(&assistant_len)
}

fn sanitize_canvas_assistant_message(text: &str) -> String {
    let cleaned_lines: Vec<&str> = text
        .lines()
        .filter(|line| {
            let normalized = normalized_canvas_micro_text(line);
            !normalized.contains("dans ce tour precis")
                && !normalized.contains("dans ce tour")
                && !normalized.contains("sans executer d outils")
                && !normalized.contains("sans execution d outils")
                && !normalized.contains("je n ai rien lance")
                && !normalized.contains("aucun outil")
                && !normalized.contains("outil forge n est attache")
                && !normalized.contains("outils forge ne sont")
                && !normalized.contains("au tour suivant")
        })
        .collect();
    let cleaned = cleaned_lines.join("\n").trim().to_string();
    if cleaned.is_empty() {
        text.trim().to_string()
    } else {
        cleaned
    }
}

fn forge_canvas_on_demand_context(job_id: Option<String>, has_active_job: bool) -> JsonValue {
    json!({
        "mode": "on_demand",
        "reason": "conversation_only",
        "session": {
            "status": if has_active_job { "active_not_loaded" } else { "no active Forge job" },
            "job_id": job_id,
            "file_count": 0
        },
        "programs": [],
        "log_tail": []
    })
}

struct ForgeDirectBackendReply {
    message: String,
    tool: &'static str,
    data: JsonValue,
}

fn text_has_any(text: &str, needles: &[&str]) -> bool {
    needles.iter().any(|needle| text.contains(needle))
}

fn text_has_word(text: &str, words: &[&str]) -> bool {
    text.split(|ch: char| !ch.is_alphanumeric())
        .filter(|part| !part.is_empty())
        .any(|part| words.contains(&part))
}

fn direct_backend_read_intent(lower: &str) -> bool {
    text_has_any(
        lower,
        &[
            "list",
            "liste",
            "affiche",
            "montre",
            "show",
            "combien",
            "how many",
            "quel",
            "quels",
            "quelle",
            "which",
            "what",
            "status",
            "statut",
            "dispo",
            "disponible",
            "available",
        ],
    )
}

fn direct_backend_is_blocked_action(lower: &str) -> bool {
    text_has_any(
        lower,
        &[
            "run",
            "lance",
            "lancer",
            "execute",
            "exécute",
            "calcul",
            "calculer",
            "backtest",
            "analyse",
            "analyser",
            "analyze",
            "create",
            "cree",
            "crée",
            "créer",
            "select",
            "sélection",
            "optimise",
            "optimiser",
            "optimize",
            "compare",
            "comparer",
        ],
    )
}

fn json_string_at(value: &JsonValue, keys: &[&str]) -> Option<String> {
    keys.iter()
        .filter_map(|key| value.get(*key))
        .find_map(|item| match item {
            JsonValue::String(s) if !s.trim().is_empty() => Some(s.trim().to_string()),
            JsonValue::Number(n) => Some(n.to_string()),
            _ => None,
        })
}

fn json_u64_at(value: &JsonValue, keys: &[&str]) -> Option<u64> {
    keys.iter()
        .filter_map(|key| value.get(*key))
        .find_map(|item| {
            item.as_u64().or_else(|| {
                item.as_str()
                    .and_then(|s| s.trim().parse::<u64>().ok())
            })
        })
}

fn json_string_array(value: &JsonValue) -> Vec<String> {
    value
        .as_array()
        .map(|items| {
            items
                .iter()
                .filter_map(JsonValue::as_str)
                .filter(|s| !s.trim().is_empty())
                .map(|s| s.trim().to_string())
                .collect()
        })
        .unwrap_or_default()
}

fn session_file_labels(session: &JsonValue) -> Vec<String> {
    let paths = session
        .get("file_paths")
        .or_else(|| session.get("filePaths"))
        .map(json_string_array)
        .unwrap_or_default();
    paths
        .into_iter()
        .map(|path| {
            Path::new(&path)
                .file_name()
                .and_then(|s| s.to_str())
                .filter(|s| !s.trim().is_empty())
                .unwrap_or(path.as_str())
                .to_string()
        })
        .collect()
}

fn program_label(program: &JsonValue) -> String {
    let title = json_string_at(program, &["title"]).unwrap_or_else(|| "Untitled program".to_string());
    let hash = json_string_at(program, &["programHash", "program_hash"]).unwrap_or_default();
    let domain = json_string_at(program, &["domain"]).unwrap_or_default();
    let status = json_string_at(program, &["status"]).unwrap_or_default();
    let mut parts = vec![title];
    if !domain.is_empty() {
        parts.push(domain);
    }
    if !status.is_empty() {
        parts.push(status);
    }
    if !hash.is_empty() {
        parts.push(format!("hash {hash}"));
    }
    parts.join(" · ")
}

fn forge_canvas_direct_backend_reply(
    user_message: &str,
    context: &JsonValue,
) -> Option<ForgeDirectBackendReply> {
    let lower = user_message.to_lowercase();
    if direct_backend_is_blocked_action(&lower) {
        return None;
    }
    let session = context.get("session").unwrap_or(&JsonValue::Null);
    let programs = context
        .get("programs")
        .and_then(JsonValue::as_array)
        .cloned()
        .unwrap_or_default();
    let logs = context
        .get("log_tail")
        .and_then(JsonValue::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(JsonValue::as_str)
                .filter(|line| !line.trim().is_empty())
                .map(|line| line.trim().to_string())
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let wants_logs = text_has_word(&lower, &["log", "logs", "journal"]);
    let wants_programs = text_has_word(&lower, &["program", "programs", "programme", "programmes"]);
    let wants_files = text_has_word(&lower, &["file", "files", "fichier", "fichiers", "csv", "json", "pdf", "txt"]);
    let wants_tools = text_has_word(
        &lower,
        &["outil", "outils", "tool", "tools", "capability", "capabilities", "capacite", "capacité"],
    );
    let wants_status = text_has_word(&lower, &["status", "statut", "session"]);

    if wants_logs && direct_backend_read_intent(&lower) {
        let message = if logs.is_empty() {
            "Aucun log Forge récent n'est disponible pour cette session.".to_string()
        } else {
            let mut lines = vec![format!("Derniers logs Forge ({} ligne(s)):", logs.len())];
            lines.extend(logs.iter().rev().take(12).collect::<Vec<_>>().into_iter().rev().cloned());
            lines.join("\n")
        };
        return Some(ForgeDirectBackendReply {
            message,
            tool: "backend_logs",
            data: json!({ "logTailLines": logs.len() }),
        });
    }

    if wants_programs && direct_backend_read_intent(&lower) {
        let message = if programs.is_empty() {
            "Aucun programme Forge local n'est enregistré pour l'instant.".to_string()
        } else {
            let mut lines = vec![format!("Programmes Forge disponibles ({} affiché(s)):", programs.len())];
            for (idx, program) in programs.iter().take(12).enumerate() {
                lines.push(format!("{}. {}", idx + 1, program_label(program)));
            }
            lines.join("\n")
        };
        return Some(ForgeDirectBackendReply {
            message,
            tool: "backend_programs",
            data: json!({ "programs": programs.len() }),
        });
    }

    if wants_files && direct_backend_read_intent(&lower) {
        let files = session_file_labels(session);
        let file_count = json_u64_at(session, &["file_count", "fileCount"]).unwrap_or(files.len() as u64);
        let message = if file_count == 0 {
            "Aucun fichier n'est attaché à la session Forge actuelle.".to_string()
        } else {
            let mut lines = vec![format!("La session Forge contient {file_count} fichier(s):")];
            if files.is_empty() {
                lines.push("Les chemins exacts ne sont pas exposés dans le contexte compact.".to_string());
            } else {
                for (idx, file) in files.iter().take(16).enumerate() {
                    lines.push(format!("{}. {}", idx + 1, file));
                }
            }
            lines.join("\n")
        };
        return Some(ForgeDirectBackendReply {
            message,
            tool: "backend_files",
            data: json!({ "files": file_count }),
        });
    }

    if wants_tools && direct_backend_read_intent(&lower) {
        return Some(ForgeDirectBackendReply {
            message: [
                "Actions backend directes disponibles:",
                "1. Statut de session",
                "2. Liste des fichiers",
                "3. Derniers logs",
                "4. Liste des programmes Forge",
                "5. Indication cache local / usage token",
                "",
                "Les calculs, creations de programmes et analyses restent routes vers l'agent choisi + outils Forge.",
            ]
            .join("\n"),
            tool: "backend_tools",
            data: json!({ "directActions": ["session_status", "files", "logs", "programs", "cache_usage"] }),
        });
    }

    if wants_status && direct_backend_read_intent(&lower) {
        let job_id = json_string_at(session, &["job_id", "jobId"]).unwrap_or_else(|| {
            context
                .get("selected_job_id")
                .and_then(JsonValue::as_str)
                .unwrap_or("")
                .to_string()
        });
        let title = json_string_at(session, &["title"]).unwrap_or_else(|| "Session Forge".to_string());
        let status = json_string_at(session, &["status"]).unwrap_or_else(|| "unknown".to_string());
        let kind = json_string_at(session, &["kind"]).unwrap_or_default();
        let file_count = json_u64_at(session, &["file_count", "fileCount"]).unwrap_or(0);
        let mut lines = vec![
            format!("{title}: {status}"),
            format!("Fichiers: {file_count}"),
            format!("Programmes disponibles: {}", programs.len()),
            format!("Logs chargés: {}", logs.len()),
        ];
        if !job_id.trim().is_empty() {
            lines.push(format!("Job: {job_id}"));
        }
        if !kind.is_empty() {
            lines.push(format!("Type: {kind}"));
        }
        return Some(ForgeDirectBackendReply {
            message: lines.join("\n"),
            tool: "backend_status",
            data: json!({
                "jobId": job_id,
                "status": status,
                "files": file_count,
                "programs": programs.len(),
                "logTailLines": logs.len()
            }),
        });
    }

    None
}

fn truncate_for_thread_memory(text: &str, max_chars: usize) -> String {
    let compact = text.split_whitespace().collect::<Vec<_>>().join(" ");
    if compact.chars().count() <= max_chars {
        return compact;
    }
    let mut out = compact.chars().take(max_chars.saturating_sub(3)).collect::<String>();
    out.push_str("...");
    out
}

fn compact_thread_memory_preserve_tail(text: &str, max_chars: usize) -> String {
    let compact = text.split_whitespace().collect::<Vec<_>>().join(" ");
    let len = compact.chars().count();
    if len <= max_chars {
        return compact;
    }
    let head_len = (max_chars.saturating_sub(7) * 2) / 3;
    let tail_len = max_chars.saturating_sub(7).saturating_sub(head_len);
    let head = compact.chars().take(head_len).collect::<String>();
    let tail_vec = compact.chars().rev().take(tail_len).collect::<Vec<_>>();
    let tail = tail_vec.into_iter().rev().collect::<String>();
    format!("{head} [...] {tail}")
}

fn canvas_memory_entry_is_summary(entry: &str) -> bool {
    let trimmed = entry.trim_start();
    trimmed.starts_with("Memoire cumulative session:")
        || trimmed.starts_with("Memoire compacte precedente:")
}

fn canvas_thread_memory_total_chars(memory: &[String]) -> usize {
    memory.iter().map(|entry| entry.chars().count()).sum()
}

fn compact_canvas_thread_state_memory(state: &mut CodexThreadState, force: bool) {
    let should_compact = force
        || state.memory.len() > CODEX_CANVAS_THREAD_COMPACT_TRIGGER_ITEMS
        || canvas_thread_memory_total_chars(&state.memory)
            > CODEX_CANVAS_COMPACT_MEMORY_MAX_CHARS.saturating_mul(2);
    if !should_compact || state.memory.len() <= CODEX_CANVAS_THREAD_RECENT_ITEMS {
        return;
    }
    let recent_start = state
        .memory
        .len()
        .saturating_sub(CODEX_CANVAS_THREAD_RECENT_ITEMS);
    let mut previous_summary = String::new();
    let mut older = Vec::new();
    for entry in &state.memory[..recent_start] {
        if canvas_memory_entry_is_summary(entry) {
            if !previous_summary.is_empty() {
                previous_summary.push('\n');
            }
            previous_summary.push_str(entry.trim());
        } else {
            older.push(entry.as_str());
        }
    }
    let mut source = String::new();
    if !previous_summary.is_empty() {
        source.push_str(&previous_summary);
        source.push('\n');
    }
    if !older.is_empty() {
        source.push_str("Anciens echanges compactes:\n");
        source.push_str(&older.join("\n"));
    }
    let summary_body = compact_thread_memory_preserve_tail(
        &source,
        CODEX_CANVAS_SESSION_SUMMARY_MAX_CHARS,
    );
    let summary = format!(
        "Memoire cumulative session: generation={} resume_toute_session={}",
        state.generation, summary_body
    );
    let mut next = Vec::with_capacity(1 + CODEX_CANVAS_THREAD_RECENT_ITEMS);
    if !summary.trim().is_empty() {
        next.push(summary);
    }
    next.extend(state.memory[recent_start..].iter().cloned());
    state.memory = next;
}

fn normalize_canvas_reasoning_effort(raw: Option<&str>) -> String {
    let key = raw
        .unwrap_or("")
        .trim()
        .to_ascii_lowercase()
        .replace('_', " ")
        .replace('-', " ");
    let key = key.split_whitespace().collect::<Vec<_>>().join(" ");
    match key.as_str() {
        "high" | "eleve" | "elevated" => "high".to_string(),
        "xhigh" | "extra high" | "very high" | "tres eleve" | "tres approfondi"
        | "approfondi" => "xhigh".to_string(),
        _ => "medium".to_string(),
    }
}

fn canvas_reasoning_instruction(effort: &str) -> &'static str {
    match effort {
        "high" => {
            "Raisonnement: eleve. Verifie davantage les hypotheses et les effets de bord avant de conclure, tout en restant compact."
        }
        "xhigh" => {
            "Raisonnement: tres approfondi. Prends le temps de decomposer le probleme, verifier les choix et signaler les incertitudes utiles."
        }
        _ => {
            "Raisonnement: moyen. Reponds directement, avec assez de verification pour eviter les erreurs evidentes."
        }
    }
}

fn build_codex_canvas_prompt_light(
    user_message: &str,
    tools_enabled: bool,
    compact_memory: Option<&str>,
    reasoning_effort: &str,
) -> String {
    let bridge = if tools_enabled {
        "Forge tools available. Use them only when useful. For Instrument/Lens creation, first settle objective, Nodes, formulas/routes and validation; ask/propose if vague, create after a clear decision. Run only after explicit launch approval."
    } else {
        ""
    };
    let memory = compact_memory
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(|s| format!("\nMEMOIRE_COMPACTE:\n{s}\n"))
        .unwrap_or_default();
    let reasoning = if tools_enabled {
        canvas_reasoning_instruction(reasoning_effort)
    } else {
        ""
    };
    let capability_instruction = if tools_enabled {
        forge_capability_prompt_instruction(user_message)
    } else {
        ""
    };
    format!(
        "Tu es Codex dans Forge. Reponds en francais naturel et concis.\n\
        {reasoning}\n\
        {bridge}\n\
        {capability_instruction}\n\
        {memory}\n\
        MESSAGE_UTILISATEUR:\n{user_message}\n"
    )
}

