fn first_gemini_response_text(value: &JsonValue) -> Option<String> {
    for pointer in ["/response", "/text", "/content", "/output", "/result/response", "/result/text"] {
        if let Some(text) = value
            .pointer(pointer)
            .and_then(JsonValue::as_str)
            .map(str::trim)
            .filter(|s| !s.is_empty())
        {
            return Some(text.to_string());
        }
    }
    if let Some(items) = value.get("messages").and_then(JsonValue::as_array) {
        let mut out = Vec::new();
        for item in items {
            if item.get("role").and_then(JsonValue::as_str) == Some("assistant") {
                if let Some(text) = item.get("content").and_then(JsonValue::as_str) {
                    out.push(text.trim().to_string());
                }
            }
        }
        if !out.is_empty() {
            return Some(out.join("\n").trim().to_string());
        }
    }
    None
}

fn gemini_usage_from_stats(stats: &JsonValue) -> JsonValue {
    let mut input = 0u64;
    let mut cached = 0u64;
    let mut output = 0u64;
    let mut total = 0u64;
    if let Some(models) = stats.get("models").and_then(JsonValue::as_object) {
        for model in models.values() {
            let tokens = model.get("tokens").unwrap_or(&JsonValue::Null);
            input = input.saturating_add(tokens.get("prompt").and_then(JsonValue::as_u64).unwrap_or(0));
            cached = cached.saturating_add(tokens.get("cached").and_then(JsonValue::as_u64).unwrap_or(0));
            output = output.saturating_add(tokens.get("candidates").and_then(JsonValue::as_u64).unwrap_or(0));
            total = total.saturating_add(tokens.get("total").and_then(JsonValue::as_u64).unwrap_or(0));
        }
    }
    json!({
        "last": {
            "inputTokens": input,
            "cachedInputTokens": cached,
            "outputTokens": output,
            "totalTokens": total
        },
        "total": {
            "inputTokens": input,
            "cachedInputTokens": cached,
            "outputTokens": output,
            "totalTokens": total
        }
    })
}

fn first_claude_response_text(value: &JsonValue) -> Option<String> {
    for pointer in [
        "/result",
        "/response",
        "/text",
        "/content",
        "/message/content",
        "/result/response",
        "/result/text",
    ] {
        if let Some(text) = value
            .pointer(pointer)
            .and_then(JsonValue::as_str)
            .map(str::trim)
            .filter(|s| !s.is_empty())
        {
            return Some(text.to_string());
        }
    }
    if let Some(items) = value.pointer("/message/content").and_then(JsonValue::as_array) {
        let mut out = Vec::new();
        for item in items {
            if let Some(text) = item.get("text").and_then(JsonValue::as_str) {
                let text = text.trim();
                if !text.is_empty() {
                    out.push(text.to_string());
                }
            }
        }
        if !out.is_empty() {
            return Some(out.join("\n").trim().to_string());
        }
    }
    None
}

fn claude_usage_from_json(value: &JsonValue) -> JsonValue {
    let usage = value
        .get("usage")
        .or_else(|| value.pointer("/message/usage"))
        .or_else(|| value.pointer("/result/usage"))
        .unwrap_or(&JsonValue::Null);
    let input = usage
        .get("input_tokens")
        .or_else(|| usage.get("inputTokens"))
        .and_then(JsonValue::as_u64)
        .unwrap_or(0);
    let cache_creation = usage
        .get("cache_creation_input_tokens")
        .or_else(|| usage.get("cacheCreationInputTokens"))
        .and_then(JsonValue::as_u64)
        .unwrap_or(0);
    let cached = usage
        .get("cache_read_input_tokens")
        .or_else(|| usage.get("cacheReadInputTokens"))
        .and_then(JsonValue::as_u64)
        .unwrap_or(0);
    let output = usage
        .get("output_tokens")
        .or_else(|| usage.get("outputTokens"))
        .and_then(JsonValue::as_u64)
        .unwrap_or(0);
    let total = input
        .saturating_add(cache_creation)
        .saturating_add(cached)
        .saturating_add(output);
    json!({
        "last": {
            "inputTokens": input.saturating_add(cache_creation),
            "cachedInputTokens": cached,
            "outputTokens": output,
            "totalTokens": total
        },
        "total": {
            "inputTokens": input.saturating_add(cache_creation),
            "cachedInputTokens": cached,
            "outputTokens": output,
            "totalTokens": total
        }
    })
}

fn kill_process_tree(pid: u32) -> bool {
    #[cfg(windows)]
    {
        Command::new("taskkill")
            .args(["/PID", &pid.to_string(), "/T", "/F"])
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status()
            .map(|status| status.success())
            .unwrap_or(false)
    }
    #[cfg(not(windows))]
    {
        Command::new("kill")
            .args(["-TERM", &pid.to_string()])
            .status()
            .map(|status| status.success())
            .unwrap_or(false)
    }
}

fn kill_gemini_active_process() -> bool {
    let pid = gemini_active_pid_lock()
        .lock()
        .ok()
        .and_then(|mut guard| guard.take());
    pid.map(kill_process_tree).unwrap_or(false)
}

fn kill_claude_active_process() -> bool {
    let pid = claude_active_pid_lock()
        .lock()
        .ok()
        .and_then(|mut guard| guard.take());
    pid.map(kill_process_tree).unwrap_or(false)
}

fn run_claude_canvas_cli(
    user_message: String,
    tools_enabled: bool,
    compact_memory: Option<String>,
    thread_generation: u32,
    model_ref: Option<String>,
    reasoning_effort: String,
    store_path: PathBuf,
    active_job_id: Option<String>,
    app: Option<tauri::AppHandle>,
    turn_id: String,
) -> Result<(String, JsonValue), String> {
    let config_path = ensure_claude_forge_mcp_config(&store_path, active_job_id.as_deref())?;
    let candidate = claude_cli_binary_path().ok_or_else(|| {
        "Claude Code CLI was not found. Install @anthropic-ai/claude-code with npm, then run `claude` once to login.".to_string()
    })?;
    let model = claude_bridge_model_arg(model_ref.as_deref());
    let model_label = model
        .clone()
        .unwrap_or_else(|| "claude-code-default".to_string());
    emit_canvas_assistant_event(
        app.as_ref(),
        &turn_id,
        "claude_cli",
        "Claude Code CLI rejoint cette session Forge.",
        json!({
            "runtime": "Claude Code CLI",
            "path": candidate.display().to_string(),
            "model": model_label,
            "reasoningEffort": reasoning_effort.as_str(),
            "mcpConfig": config_path.display().to_string(),
            "toolsEnabled": tools_enabled,
            "threadGeneration": thread_generation,
            "compacted": compact_memory.is_some(),
            "compactMemoryChars": compact_memory
                .as_ref()
                .map(|s| s.chars().count())
                .unwrap_or(0)
        }),
    );
    let prompt =
        build_claude_canvas_prompt_light(&user_message, tools_enabled, compact_memory.as_deref(), &reasoning_effort);
    let mut command = claude_cli_command(&candidate);
    configure_forge_llm_cli_command(&mut command);
    command
        .current_dir(forge_workspace_dir())
        .arg("-p")
        .arg(prompt)
        .arg("--output-format")
        .arg("json")
        .arg("--mcp-config")
        .arg(&config_path)
        .arg("--strict-mcp-config")
        .arg("--allowedTools")
        .arg("mcp__forge__*")
        .env("FORGE_STORE_DIR", &store_path)
        .env("FORGE_MCP_MODEL", "forge-claude-code")
        .env_remove("ANTHROPIC_API_KEY")
        .env_remove("ANTHROPIC_AUTH_TOKEN")
        .env_remove("CLAUDE_CODE_USE_BEDROCK")
        .env_remove("CLAUDE_CODE_USE_VERTEX")
        .env_remove("CLAUDE_CODE_USE_FOUNDRY")
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    if let Some(job_id) = active_job_id.as_deref() {
        command.env("FORGE_ACTIVE_JOB_ID", job_id);
    }
    if let Some(model) = model.as_ref() {
        command.arg("--model").arg(model);
    }
    let mut child = command
        .spawn()
        .map_err(|e| format!("start Claude Code CLI: {e}"))?;
    let pid = child.id();
    if let Ok(mut guard) = claude_active_pid_lock().lock() {
        *guard = Some(pid);
    }
    let stdout = child.stdout.take();
    let stderr = child.stderr.take();
    let stdout_handle = stdout.map(|stream| {
        thread::spawn(move || {
            let mut text = String::new();
            let _ = BufReader::new(stream).read_to_string(&mut text);
            text
        })
    });
    let stderr_handle = stderr.map(|stream| {
        thread::spawn(move || {
            let mut text = String::new();
            let _ = BufReader::new(stream).read_to_string(&mut text);
            text
        })
    });
    let started = Instant::now();
    let status = loop {
        match child.try_wait() {
            Ok(Some(status)) => break status,
            Ok(None) => {}
            Err(err) => return Err(format!("wait Claude Code CLI: {err}")),
        }
        if canvas_turn_cancelled_global(&turn_id) {
            let _ = kill_process_tree(pid);
            let _ = child.kill();
            let _ = child.wait();
            if let Ok(mut guard) = claude_active_pid_lock().lock() {
                if *guard == Some(pid) {
                    *guard = None;
                }
            }
            return Err("Claude Code CLI stopped by user.".to_string());
        }
        if started.elapsed() >= Duration::from_secs(180) {
            let _ = kill_process_tree(pid);
            let _ = child.kill();
            let _ = child.wait();
            if let Ok(mut guard) = claude_active_pid_lock().lock() {
                if *guard == Some(pid) {
                    *guard = None;
                }
            }
            return Err("Claude Code CLI timed out after 180 seconds.".to_string());
        }
        thread::sleep(Duration::from_millis(120));
    };
    if let Ok(mut guard) = claude_active_pid_lock().lock() {
        if *guard == Some(pid) {
            *guard = None;
        }
    }
    let stdout_text = stdout_handle
        .and_then(|handle| handle.join().ok())
        .unwrap_or_default();
    let stderr_text = stderr_handle
        .and_then(|handle| handle.join().ok())
        .unwrap_or_default();
    if !status.success() {
        return Err(format!(
            "Claude Code CLI exited with {status}: {}",
            truncate_for_thread_memory(
                if stderr_text.trim().is_empty() {
                    &stdout_text
                } else {
                    &stderr_text
                },
                1200
            )
        ));
    }
    let parsed = serde_json::from_str::<JsonValue>(&stdout_text).ok();
    let assistant_message = parsed
        .as_ref()
        .and_then(first_claude_response_text)
        .unwrap_or_else(|| stdout_text.trim().to_string());
    if assistant_message.trim().is_empty() {
        return Err("Claude Code CLI returned no usable text.".to_string());
    }
    let usage = parsed
        .as_ref()
        .map(claude_usage_from_json)
        .unwrap_or_else(|| claude_usage_from_json(&JsonValue::Null));
    emit_canvas_assistant_event(
        app.as_ref(),
        &turn_id,
        "claude_cli",
        "Claude Code CLI a renvoye sa reponse pour Forge.",
        json!({
            "runtime": "Claude Code CLI",
            "path": candidate.display().to_string(),
            "status": "ok",
            "model": model_label,
            "reasoningEffort": reasoning_effort.as_str(),
        }),
    );
    clear_canvas_turn_cancelled_global(&turn_id);
    Ok((
        assistant_message.trim().to_string(),
        json!({
            "status": "ok",
            "runtime": "Claude Code CLI",
            "path": candidate.display().to_string(),
            "mode": "claude headless",
            "model": model_label,
            "reasoningEffort": reasoning_effort,
            "mcpConfig": config_path.display().to_string(),
            "toolsEnabled": tools_enabled,
            "threadGeneration": thread_generation,
            "compacted": compact_memory.is_some(),
            "compactMemoryChars": compact_memory
                .as_ref()
                .map(|s| s.chars().count())
                .unwrap_or(0),
            "usage": usage,
            "raw": parsed.unwrap_or(JsonValue::Null)
        }),
    ))
}

fn run_gemini_canvas_cli(
    user_message: String,
    tools_enabled: bool,
    compact_memory: Option<String>,
    thread_generation: u32,
    model_ref: Option<String>,
    reasoning_effort: String,
    store_path: PathBuf,
    active_job_id: Option<String>,
    app: Option<tauri::AppHandle>,
    turn_id: String,
) -> Result<(String, JsonValue), String> {
    let settings_path = ensure_gemini_forge_mcp_settings(&store_path, active_job_id.as_deref())?;
    let candidate = gemini_cli_binary_path()
        .ok_or_else(|| "Gemini CLI was not found. Install @google/gemini-cli with npm.".to_string())?;
    let model = gemini_bridge_model_arg(model_ref.as_deref())
        .unwrap_or_else(|| "gemini-2.5-pro".to_string());
    emit_canvas_assistant_event(
        app.as_ref(),
        &turn_id,
        "gemini_cli",
        "Gemini CLI rejoint cette session Forge.",
        json!({
            "runtime": "Gemini CLI",
            "path": candidate.display().to_string(),
            "model": model,
            "reasoningEffort": reasoning_effort.as_str(),
            "settings": settings_path.display().to_string(),
            "toolsEnabled": tools_enabled,
            "threadGeneration": thread_generation,
            "compacted": compact_memory.is_some(),
            "compactMemoryChars": compact_memory
                .as_ref()
                .map(|s| s.chars().count())
                .unwrap_or(0)
        }),
    );
    let prompt =
        build_gemini_canvas_prompt_light(&user_message, tools_enabled, compact_memory.as_deref(), &reasoning_effort);
    let mut command = gemini_cli_command(&candidate);
    configure_forge_llm_cli_command(&mut command);
    command
        .current_dir(forge_workspace_dir())
        .arg("-p")
        .arg(prompt)
        .arg("--output-format")
        .arg("json")
        .arg("--model")
        .arg(&model)
        .env("FORGE_STORE_DIR", &store_path)
        .env("FORGE_MCP_MODEL", "forge-gemini-cli")
        .env("NO_COLOR", "1")
        .env("TERM", "xterm-256color")
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    if let Some(job_id) = active_job_id.as_deref() {
        command.env("FORGE_ACTIVE_JOB_ID", job_id);
    }
    if let Some((api_key, _)) = gemini_configured_api_key() {
        command.env("GEMINI_API_KEY", api_key);
    }
    let mut child = command
        .spawn()
        .map_err(|e| format!("start Gemini CLI: {e}"))?;
    let pid = child.id();
    if let Ok(mut guard) = gemini_active_pid_lock().lock() {
        *guard = Some(pid);
    }
    let stdout = child.stdout.take();
    let stderr = child.stderr.take();
    let stdout_handle = stdout.map(|stream| {
        thread::spawn(move || {
            let mut text = String::new();
            let _ = BufReader::new(stream).read_to_string(&mut text);
            text
        })
    });
    let stderr_handle = stderr.map(|stream| {
        thread::spawn(move || {
            let mut text = String::new();
            let _ = BufReader::new(stream).read_to_string(&mut text);
            text
        })
    });
    let started = Instant::now();
    let status = loop {
        match child.try_wait() {
            Ok(Some(status)) => break status,
            Ok(None) => {}
            Err(err) => return Err(format!("wait Gemini CLI: {err}")),
        }
        if canvas_turn_cancelled_global(&turn_id) {
            let _ = kill_process_tree(pid);
            let _ = child.kill();
            let _ = child.wait();
            if let Ok(mut guard) = gemini_active_pid_lock().lock() {
                if *guard == Some(pid) {
                    *guard = None;
                }
            }
            return Err("Gemini CLI stopped by user.".to_string());
        }
        if started.elapsed() >= Duration::from_secs(180) {
            let _ = kill_process_tree(pid);
            let _ = child.kill();
            let _ = child.wait();
            if let Ok(mut guard) = gemini_active_pid_lock().lock() {
                if *guard == Some(pid) {
                    *guard = None;
                }
            }
            return Err("Gemini CLI timed out after 180 seconds.".to_string());
        }
        thread::sleep(Duration::from_millis(120));
    };
    if let Ok(mut guard) = gemini_active_pid_lock().lock() {
        if *guard == Some(pid) {
            *guard = None;
        }
    }
    let stdout_text = stdout_handle
        .and_then(|handle| handle.join().ok())
        .unwrap_or_default();
    let stderr_text = stderr_handle
        .and_then(|handle| handle.join().ok())
        .unwrap_or_default();
    if !status.success() {
        return Err(format!(
            "Gemini CLI exited with {status}: {}",
            truncate_for_thread_memory(
                if stderr_text.trim().is_empty() {
                    &stdout_text
                } else {
                    &stderr_text
                },
                1200
            )
        ));
    }
    let parsed = serde_json::from_str::<JsonValue>(&stdout_text).ok();
    let assistant_message = parsed
        .as_ref()
        .and_then(first_gemini_response_text)
        .unwrap_or_else(|| stdout_text.trim().to_string());
    if assistant_message.trim().is_empty() {
        return Err("Gemini CLI returned no usable text.".to_string());
    }
    let stats = parsed
        .as_ref()
        .and_then(|value| value.get("stats"))
        .cloned()
        .unwrap_or(JsonValue::Null);
    emit_canvas_assistant_event(
        app.as_ref(),
        &turn_id,
        "gemini_cli",
        "Gemini CLI a renvoye sa reponse pour Forge.",
        json!({
            "runtime": "Gemini CLI",
            "path": candidate.display().to_string(),
            "status": "ok",
            "model": model,
            "reasoningEffort": reasoning_effort.as_str(),
        }),
    );
    clear_canvas_turn_cancelled_global(&turn_id);
    Ok((
        assistant_message.trim().to_string(),
        json!({
            "status": "ok",
            "runtime": "Gemini CLI",
            "path": candidate.display().to_string(),
            "mode": "gemini headless",
            "model": model,
            "reasoningEffort": reasoning_effort,
            "settings": settings_path.display().to_string(),
            "toolsEnabled": tools_enabled,
            "threadGeneration": thread_generation,
            "compacted": compact_memory.is_some(),
            "compactMemoryChars": compact_memory
                .as_ref()
                .map(|s| s.chars().count())
                .unwrap_or(0),
            "usage": gemini_usage_from_stats(&stats),
            "stats": stats
        }),
    ))
}

fn emit_canvas_assistant_event(
    app: Option<&tauri::AppHandle>,
    turn_id: &str,
    stage: &str,
    message: impl Into<String>,
    data: JsonValue,
) {
    if let Some(app) = app {
        let _ = app.emit(
            "forge-canvas-assistant-event",
            json!({
                "turnId": turn_id,
                "stage": stage,
                "message": message.into(),
                "data": data,
            }),
        );
    }
}

#[allow(dead_code)]
fn summarize_codex_json_event(value: &JsonValue) -> Option<String> {
    let event_type = value.get("type").and_then(JsonValue::as_str).unwrap_or("");
    match event_type {
        "thread.started" => Some("Codex ouvre un tour local pour cette session Forge.".to_string()),
        "turn.started" => Some("Codex commence à raisonner sur la session actuelle.".to_string()),
        "turn.completed" => {
            if let Some(usage) = value.get("usage") {
                let input = usage
                    .get("input_tokens")
                    .and_then(JsonValue::as_u64)
                    .unwrap_or(0);
                let output = usage
                    .get("output_tokens")
                    .and_then(JsonValue::as_u64)
                    .unwrap_or(0);
                Some(format!("Codex a terminé le tour · entrée={input} tokens · sortie={output} tokens."))
            } else {
                Some("Codex a terminé le tour.".to_string())
            }
        }
        "turn.failed" => Some("Codex n'a pas réussi à terminer ce tour.".to_string()),
        "error" => value
            .get("message")
            .and_then(JsonValue::as_str)
            .map(|message| format!("Erreur Codex: {message}")),
        "item.started" | "item.completed" => {
            let item = value.get("item").unwrap_or(&JsonValue::Null);
            let item_type = item.get("type").and_then(JsonValue::as_str).unwrap_or("");
            match item_type {
                "agent_message" => None,
                "reasoning" => Some("Codex travaille avec le contexte compact de Forge.".to_string()),
                "command_execution" => item
                    .get("command")
                    .and_then(JsonValue::as_str)
                    .map(|command| format!("Codex prépare une commande locale: {command}"))
                    .or_else(|| Some("Codex prépare une commande locale.".to_string())),
                "mcp_tool_call" => item
                    .get("name")
                    .and_then(JsonValue::as_str)
                    .map(|name| format!("Codex appelle l'outil MCP {name}."))
                    .or_else(|| Some("Codex appelle un outil MCP.".to_string())),
                "web_search" => Some("Codex consulte le web.".to_string()),
                _ if !item_type.is_empty() => Some(format!("Événement Codex: {item_type}.")),
                _ => None,
            }
        }
        _ => None,
    }
}

fn codex_notification_thread_id(value: &JsonValue) -> Option<&str> {
    value
        .get("params")
        .and_then(|params| params.get("threadId"))
        .and_then(JsonValue::as_str)
}

fn codex_notification_turn_id(value: &JsonValue) -> Option<&str> {
    let params = value.get("params")?;
    params
        .get("turnId")
        .and_then(JsonValue::as_str)
        .or_else(|| {
            params
                .get("turn")
                .and_then(|turn| turn.get("id"))
                .and_then(JsonValue::as_str)
        })
}

fn codex_notification_matches_turn(
    value: &JsonValue,
    thread_id: &str,
    codex_turn_id: &str,
) -> bool {
    if let Some(value_thread_id) = codex_notification_thread_id(value) {
        if value_thread_id != thread_id {
            return false;
        }
    }
    if let Some(value_turn_id) = codex_notification_turn_id(value) {
        if value_turn_id != codex_turn_id {
            return false;
        }
    }
    true
}

fn codex_token_usage_summary(params: &JsonValue) -> Option<(u64, u64)> {
    let usage = params.get("tokenUsage")?;
    let last = usage.get("last").unwrap_or(usage);
    let input = last
        .get("inputTokens")
        .or_else(|| last.get("input_tokens"))
        .and_then(JsonValue::as_u64)
        .unwrap_or(0);
    let output = last
        .get("outputTokens")
        .or_else(|| last.get("output_tokens"))
        .and_then(JsonValue::as_u64)
        .unwrap_or(0);
    Some((input, output))
}

fn summarize_codex_app_server_notification(value: &JsonValue) -> Option<String> {
    let method = value.get("method").and_then(JsonValue::as_str).unwrap_or("");
    let params = value.get("params").unwrap_or(&JsonValue::Null);
    match method {
        "turn/started" => Some("Codex commence ce tour dans la session Forge.".to_string()),
        "turn/completed" => Some("Codex a termine ce tour dans le runtime persistant.".to_string()),
        "thread/tokenUsage/updated" => codex_token_usage_summary(params).map(|(input, output)| {
            format!(
                "Codex a traite le contexte: entree={input} tokens, sortie={output} tokens (usage abonnement, pas API)."
            )
        }),
        "item/started" | "item/completed" => {
            let item_type = params
                .get("item")
                .and_then(|item| item.get("type"))
                .and_then(JsonValue::as_str)
                .unwrap_or("");
            match item_type {
                "reasoning" => Some("Codex travaille avec le contexte compact de Forge.".to_string()),
                "commandExecution" => Some(
                    "Codex a demande une commande locale; Forge garde ce premier pont en lecture seule."
                        .to_string(),
                ),
                "fileChange" => Some(
                    "Codex a prepare un changement de fichier; Forge ne l'applique pas dans ce mode lecture seule."
                        .to_string(),
                ),
                "mcpToolCall" => params
                    .get("item")
                    .and_then(|item| item.get("tool"))
                    .and_then(JsonValue::as_str)
                    .map(|tool| format!("Codex appelle l'outil MCP {tool}."))
                    .or_else(|| Some("Codex appelle un outil MCP.".to_string())),
                "dynamicToolCall" => None,
                "webSearch" => Some("Codex consulte le web.".to_string()),
                _ => None,
            }
        }
        "server/request" => {
            let request_method = params
                .get("method")
                .and_then(JsonValue::as_str)
                .unwrap_or("");
            if request_method.contains("Approval") || request_method.contains("permissions") {
                Some(
                    "Codex a demande une autorisation; Forge reste en lecture seule pour ce tour."
                        .to_string(),
                )
            } else {
                None
            }
        }
        "error" => params
            .get("error")
            .and_then(|error| error.get("message"))
            .and_then(JsonValue::as_str)
            .map(|message| format!("Erreur Codex: {message}")),
        _ => None,
    }
}

fn run_codex_canvas_app_server(
    client: Arc<CodexAppServerClient>,
    user_message: String,
    session_key: String,
    tools_enabled: bool,
    model_ref: Option<String>,
    reasoning_effort: String,
    app: Option<tauri::AppHandle>,
    turn_id: String,
) -> Result<(String, JsonValue), String> {
    let model = codex_bridge_model_arg(model_ref.as_deref());
    emit_canvas_assistant_event(
        app.as_ref(),
        &turn_id,
        "codex_bridge",
        "J'accroche ce message au runtime Codex persistant de Forge.",
        json!({
            "runtime": "Codex app-server",
            "mode": "persistent_stdio",
            "path": client.runtime_path.display().to_string(),
            "reasoningEffort": reasoning_effort.as_str(),
        }),
    );
    let dynamic_tools = if tools_enabled {
        forge_dynamic_tool_specs_compact()
    } else {
        Vec::new()
    };
    let (thread_id, compact_memory, thread_generation) =
        client.ensure_thread(&session_key, model_ref.as_deref(), dynamic_tools)?;
    let compact_memory_chars = compact_memory
        .as_ref()
        .map(|s| s.chars().count())
        .unwrap_or(0);
    let prompt =
        build_codex_canvas_prompt_light(&user_message, tools_enabled, compact_memory.as_deref(), &reasoning_effort);
    let _ = client.drain_notifications();
    let turn_result = client.request(
        "turn/start",
        json!({
            "threadId": thread_id,
            "input": [{
                "type": "text",
                "text": prompt,
                "text_elements": [],
            }],
            "cwd": null,
            "approvalPolicy": null,
            "approvalsReviewer": null,
            "sandboxPolicy": null,
            "model": model.clone(),
            "serviceTier": null,
            "effort": reasoning_effort.as_str(),
            "summary": null,
            "personality": null,
            "outputSchema": null,
            "collaborationMode": null,
        }),
        Duration::from_secs(30),
    )?;
    let codex_turn_id = turn_result
        .get("turn")
        .and_then(|turn| turn.get("id"))
        .and_then(JsonValue::as_str)
        .ok_or_else(|| "Codex app-server did not return a turn id".to_string())?
        .to_string();
    emit_canvas_assistant_event(
        app.as_ref(),
        &turn_id,
        "codex_bridge",
        "Codex a ouvert un tour dans la session persistante.",
        json!({
            "runtime": "Codex app-server",
            "threadId": thread_id,
            "turnId": codex_turn_id,
            "reasoningEffort": reasoning_effort.as_str(),
        }),
    );

    let started = Instant::now();
    let mut final_message = String::new();
    let mut usage = JsonValue::Null;
    let mut completed = false;
    let mut failed: Option<String> = None;
    while !completed {
        if started.elapsed() > Duration::from_secs(180) {
            return Err("Codex app-server turn timed out after 180s".to_string());
        }
        let notifications = client.wait_for_notifications(Duration::from_millis(500))?;
        for notification in notifications {
            if !codex_notification_matches_turn(&notification, &thread_id, &codex_turn_id) {
                continue;
            }
            let method = notification
                .get("method")
                .and_then(JsonValue::as_str)
                .unwrap_or("");
            match method {
                "item/agentMessage/delta" => {
                    if let Some(delta) = notification
                        .get("params")
                        .and_then(|params| params.get("delta"))
                        .and_then(JsonValue::as_str)
                    {
                        final_message.push_str(delta);
                    }
                }
                "thread/tokenUsage/updated" => {
                    if let Some(token_usage) = notification
                        .get("params")
                        .and_then(|params| params.get("tokenUsage"))
                    {
                        usage = token_usage.clone();
                    }
                    if let Some(summary) = summarize_codex_app_server_notification(&notification)
                    {
                        emit_canvas_assistant_event(
                            app.as_ref(),
                            &turn_id,
                            "codex_event",
                            summary,
                            notification.clone(),
                        );
                    }
                }
                "turn/completed" => {
                    if let Some(error) = notification
                        .get("params")
                        .and_then(|params| params.get("turn"))
                        .and_then(|turn| turn.get("error"))
                        .filter(|error| !error.is_null())
                    {
                        failed = Some(error.to_string());
                    }
                    completed = true;
                    if let Some(summary) = summarize_codex_app_server_notification(&notification)
                    {
                        emit_canvas_assistant_event(
                            app.as_ref(),
                            &turn_id,
                            "codex_event",
                            summary,
                            notification.clone(),
                        );
                    }
                }
                "error" => {
                    failed = notification
                        .get("params")
                        .and_then(|params| params.get("error"))
                        .and_then(|error| error.get("message"))
                        .and_then(JsonValue::as_str)
                        .map(|message| message.to_string())
                        .or_else(|| Some(notification.to_string()));
                    completed = true;
                    if let Some(summary) = summarize_codex_app_server_notification(&notification)
                    {
                        emit_canvas_assistant_event(
                            app.as_ref(),
                            &turn_id,
                            "codex_event",
                            summary,
                            notification.clone(),
                        );
                    }
                }
                _ => {
                    if let Some(summary) = summarize_codex_app_server_notification(&notification)
                    {
                        emit_canvas_assistant_event(
                            app.as_ref(),
                            &turn_id,
                            "codex_event",
                            summary,
                            notification.clone(),
                        );
                    }
                }
            }
        }
    }
    if let Some(error) = failed {
        return Err(format!("Codex app-server turn failed: {error}"));
    }
    if final_message.trim().is_empty() {
        return Err("Codex app-server returned an empty assistant message".to_string());
    }
    client.record_thread_turn(&session_key, &user_message, final_message.trim());
    emit_canvas_assistant_event(
        app.as_ref(),
        &turn_id,
        "codex_bridge",
        "Codex a renvoye la reponse finale depuis le runtime persistant.",
        json!({
            "runtime": "Codex app-server",
            "status": "ok",
            "threadId": thread_id,
            "turnId": codex_turn_id,
        }),
    );
    Ok((
        final_message.trim().to_string(),
        json!({
            "status": "ok",
            "runtime": "Codex app-server",
            "path": client.runtime_path.display().to_string(),
            "mode": "persistent_stdio",
            "sandbox": "read-only",
            "model": model,
            "reasoningEffort": reasoning_effort,
            "toolsEnabled": tools_enabled,
            "threadGeneration": thread_generation,
            "compacted": compact_memory.is_some(),
            "compactMemoryChars": compact_memory_chars,
            "threadId": thread_id,
            "turnId": codex_turn_id,
            "usage": usage,
        }),
    ))
}

#[allow(dead_code)]
fn run_codex_canvas_exec(
    user_message: String,
    _context: JsonValue,
    model_ref: Option<String>,
    app: Option<tauri::AppHandle>,
    turn_id: String,
) -> Result<(String, JsonValue), String> {
    let reasoning_effort = "medium";
    let prompt = build_codex_canvas_prompt_light(&user_message, true, None, reasoning_effort);
    let model = codex_bridge_model_arg(model_ref.as_deref());
    let output_path = std::env::temp_dir().join(format!(
        "forge-codex-canvas-{}-{}.md",
        std::process::id(),
        now_epoch_ms()
    ));
    let mut errors = Vec::new();
    for candidate in codex_command_candidates() {
        if candidate.is_absolute() && !candidate.exists() {
            continue;
        }
        let mut command = Command::new(&candidate);
        command
            .current_dir(forge_workspace_dir())
            .arg("-a")
            .arg("never")
            .arg("exec")
            .arg("--ephemeral")
            .arg("--json")
            .arg("--sandbox")
            .arg("read-only")
            .arg("-c")
            .arg(format!("model_reasoning_effort=\"{reasoning_effort}\""))
            .arg("--output-last-message")
            .arg(&output_path);
        if let Some(ref model) = model {
            command.arg("-m").arg(model);
        }
        command
            .arg("-")
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::null());
        let mut child = match command.spawn() {
            Ok(child) => child,
            Err(err) => {
                errors.push(format!("{}: {err}", candidate.display()));
                continue;
            }
        };
        emit_canvas_assistant_event(
            app.as_ref(),
            &turn_id,
            "codex_bridge",
            "J'ouvre Codex avec le contexte compact de cette session.",
            json!({
                "runtime": "Codex CLI",
                "mode": "codex exec",
                "path": candidate.display().to_string()
            }),
        );
        let stdout_handle = child.stdout.take().map(|stdout| {
            let app_for_stdout = app.clone();
            let turn_for_stdout = turn_id.clone();
            thread::spawn(move || {
                let reader = BufReader::new(stdout);
                for line in reader.lines().flatten() {
                    let Ok(value) = serde_json::from_str::<JsonValue>(&line) else {
                        continue;
                    };
                    if let Some(summary) = summarize_codex_json_event(&value) {
                        emit_canvas_assistant_event(
                            app_for_stdout.as_ref(),
                            &turn_for_stdout,
                            "codex_event",
                            summary,
                            value,
                        );
                    }
                }
            })
        });
        if let Some(stdin) = child.stdin.as_mut() {
            if let Err(err) = stdin.write_all(prompt.as_bytes()) {
                let _ = child.kill();
                if let Some(handle) = stdout_handle {
                    let _ = handle.join();
                }
                errors.push(format!("{} stdin: {err}", candidate.display()));
                continue;
            }
        }
        drop(child.stdin.take());
        let status = wait_child_with_timeout(&mut child, Duration::from_secs(90))?;
        if let Some(handle) = stdout_handle {
            let _ = handle.join();
        }
        let Some(status) = status else {
            emit_canvas_assistant_event(
                app.as_ref(),
                &turn_id,
                "codex_bridge",
                "Codex n'a pas fini ce tour en 90 secondes.",
                json!({
                    "runtime": "Codex CLI",
                    "path": candidate.display().to_string(),
                    "timeout_seconds": 90
                }),
            );
            errors.push(format!("{} timed out after 90s", candidate.display()));
            continue;
        };
        let final_message = std::fs::read_to_string(&output_path).unwrap_or_default();
        let _ = std::fs::remove_file(&output_path);
        if status.success() && !final_message.trim().is_empty() {
            emit_canvas_assistant_event(
                app.as_ref(),
                &turn_id,
                "codex_bridge",
                "Codex a renvoyé la réponse finale pour le canva.",
                json!({
                    "runtime": "Codex CLI",
                    "path": candidate.display().to_string(),
                    "status": "ok"
                }),
            );
            return Ok((
                final_message.trim().to_string(),
                json!({
                    "status": "ok",
                    "runtime": "Codex CLI",
                    "path": candidate.display().to_string(),
                    "mode": "codex exec",
                    "sandbox": "read-only",
                    "model": model,
                }),
            ));
        }
        errors.push(format!(
            "{} exited with {}{}",
            candidate.display(),
            status,
            if final_message.trim().is_empty() {
                ""
            } else {
                " and wrote a partial message"
            }
        ));
    }
    let _ = std::fs::remove_file(&output_path);
    Err(if errors.is_empty() {
        "No Codex CLI runtime candidate was found.".to_string()
    } else {
        errors.join(" | ")
    })
}

#[tauri::command]
async fn forge_canvas_assistant_turn(
    request: ForgeCanvasAssistantRequest,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
    app: tauri::AppHandle,
) -> Result<ForgeCanvasAssistantResponse, String> {
    let max_log_lines = request.max_log_lines.unwrap_or(24).clamp(0, 80);
    let turn_id = request
        .turn_id
        .clone()
        .filter(|s| !s.trim().is_empty())
        .unwrap_or_else(|| format!("forge-canvas-{}", now_epoch_ms()));
    let requested_runtime = request
        .runtime
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .unwrap_or("codex")
        .to_ascii_lowercase();
    let requested_model_ref = request.model_ref.as_deref();
    let codex_status = codex_canvas_status(if requested_runtime == "codex" {
        requested_model_ref
    } else {
        None
    });
    let gemini_status = gemini_cli_status(if requested_runtime == "gemini" {
        requested_model_ref
    } else {
        None
    });
    let claude_status = claude_cli_status(if requested_runtime == "claude" {
        requested_model_ref
    } else {
        None
    });
    let (runtime, provider, auto_rerouted) = select_canvas_runtime(
        &requested_runtime,
        &codex_status,
        &gemini_status,
        &claude_status,
    );
    if auto_rerouted {
        emit_canvas_assistant_event(
            Some(&app),
            &turn_id,
            "runtime_fallback",
            format!(
                "{} prend automatiquement le relais pour ce tour.",
                provider_display_name(&runtime)
            ),
            json!({
                "requestedRuntime": requested_runtime,
                "fallbackRuntime": runtime,
                "runtime": runtime,
                "modelRef": provider.model_ref.clone(),
            }),
        );
    }
    let effective_model_ref = if runtime == requested_runtime {
        request.model_ref.clone()
    } else {
        None
    };
    let reasoning_effort = normalize_canvas_reasoning_effort(request.reasoning_effort.as_deref());
    let use_gemini = runtime == "gemini";
    let use_claude = runtime == "claude";
    let user_message = request.message.trim();
    let current_user_message = current_canvas_user_message(user_message);
    let has_active_job = request
        .job_id
        .as_deref()
        .map(|s| !s.trim().is_empty())
        .unwrap_or(false);
    let request_job_id_for_response = request.job_id.clone();
    let tools_enabled = canvas_message_needs_forge_tools(
        if user_message.contains("CURRENT_TURN_DECISION_POINT:") {
            user_message
        } else {
            current_user_message
        },
        has_active_job,
    );
    let context_loaded = tools_enabled;
    if !tools_enabled {
        if let Some(reply) = local_canvas_micro_reply(current_user_message) {
            return Ok(ForgeCanvasAssistantResponse {
                assistant_message: reply,
                provider,
                context: forge_canvas_on_demand_context(request.job_id.clone(), has_active_job),
                tool_events: vec![json!({
                    "tool": "token_usage",
                    "label": "0 fresh · local"
                })],
                codex_bridge: json!({
                    "status": "ok",
                    "runtime": "local_micro_reply",
                    "direct": true,
                    "toolsEnabled": false,
                    "contextLoaded": false,
                    "contextMode": "on_demand_not_loaded",
                    "reasoningEffort": reasoning_effort
                }),
            });
        }
    }
    let runtime_kind = if use_gemini {
        "gemini"
    } else if use_claude {
        "claude"
    } else {
        "codex"
    };
    let cache_model_ref = format!(
        "{}:{}:{}",
        runtime_kind,
        provider.model_ref.clone(),
        reasoning_effort
    );
    let semantic_cache_probe = if context_loaded {
        None
    } else {
        Some(semantic_cache_signature(user_message))
    };
    if let Some((normalized, tokens)) = semantic_cache_probe.as_ref() {
        if !normalized.is_empty() && tokens.len() >= 2 {
            let now_ms = now_epoch_ms();
            let mut app_state = state.lock().map_err(|e| e.to_string())?;
            app_state.semantic_cache.retain(|entry| {
                now_ms.saturating_sub(entry.created_ms) <= CODEX_CANVAS_SEMANTIC_CACHE_MAX_AGE_MS
            });
            let mut best_idx = None;
            let mut best_score = 0.0f64;
            for (idx, entry) in app_state.semantic_cache.iter().enumerate() {
                if entry.model_ref != cache_model_ref {
                    continue;
                }
                let score = if entry.normalized == *normalized {
                    1.0
                } else {
                    semantic_cache_similarity(tokens, &entry.tokens)
                };
                if score > best_score {
                    best_score = score;
                    best_idx = Some(idx);
                }
            }
            if best_score >= CODEX_CANVAS_SEMANTIC_CACHE_MIN_SCORE {
                let entry = &mut app_state.semantic_cache[best_idx.expect("best cache index")];
                entry.last_hit_ms = now_ms;
                entry.hits = entry.hits.saturating_add(1);
                let assistant_message = sanitize_canvas_assistant_message(&entry.assistant_message);
                let hits = entry.hits;
                drop(app_state);
                return Ok(ForgeCanvasAssistantResponse {
                    assistant_message,
                    provider,
                    context: forge_canvas_on_demand_context(request.job_id.clone(), has_active_job),
                    tool_events: vec![
                        json!({
                            "tool": "semantic_cache",
                            "transport": "local",
                            "score": best_score,
                            "hits": hits
                        }),
                        json!({
                            "tool": "token_usage",
                            "label": "0 fresh · local cache"
                        })
                    ],
                    codex_bridge: json!({
                        "status": "ok",
                        "runtime": "local_semantic_cache",
                        "cached": true,
                        "semanticScore": best_score,
                        "cacheHits": hits,
                        "model": cache_model_ref,
                        "reasoningEffort": reasoning_effort,
                        "toolsEnabled": false,
                        "contextLoaded": false,
                        "contextMode": "on_demand_not_loaded"
                    }),
                });
            }
        }
    }
    let context = if context_loaded {
        forge_canvas_context_value(request.job_id.clone(), max_log_lines, &state)?
    } else {
        forge_canvas_on_demand_context(request.job_id.clone(), has_active_job)
    };
    let store_path_for_codex_tools = {
        let app_state = state.lock().map_err(|e| e.to_string())?;
        app_state.store_path.clone()
    };
    let session = context.get("session").cloned().unwrap_or(JsonValue::Null);
    let file_count = session
        .get("file_count")
        .or_else(|| session.get("fileCount"))
        .and_then(JsonValue::as_u64)
        .unwrap_or(0);
    let program_count = context
        .get("programs")
        .and_then(JsonValue::as_array)
        .map(|items| items.len())
        .unwrap_or(0);
    let log_count = context
        .get("log_tail")
        .and_then(JsonValue::as_array)
        .map(|items| items.len())
        .unwrap_or(0);
    if context_loaded {
        if let Some(reply) = forge_canvas_direct_backend_reply(user_message, &context) {
            return Ok(ForgeCanvasAssistantResponse {
                assistant_message: reply.message,
                provider,
                context,
                tool_events: vec![
                    json!({
                        "tool": "backend_direct",
                        "transport": "local",
                        "action": reply.tool,
                        "data": reply.data
                    }),
                    json!({
                        "tool": "token_usage",
                        "label": "0 fresh · backend"
                    }),
                ],
                codex_bridge: json!({
                    "status": "ok",
                    "runtime": "local_backend_direct",
                    "direct": true,
                    "action": reply.tool,
                    "toolsEnabled": false,
                    "contextLoaded": true,
                    "reasoningEffort": reasoning_effort,
                    "contextMode": "loaded_on_request"
                }),
            });
        }
    }
    let mut codex_bridge = json!({
        "status": "not_attempted",
        "reason": if use_gemini {
            provider.message.clone()
        } else if use_claude {
            provider.message.clone()
        } else {
            "OpenAI subscription auth is not connected".to_string()
        }
    });
    let gemini_canvas_available =
        use_gemini && (provider.connected || provider.installed || provider_terminal_running("gemini"));
    let claude_canvas_available =
        use_claude && (provider.connected || provider.installed || provider_terminal_running("claude"));
    let mut codex_client: Option<Arc<CodexAppServerClient>> = None;
    let mut codex_start_error: Option<String> = None;
    if provider.connected && !use_gemini && !use_claude {
        codex_client = {
            let app_state = state.lock().map_err(|e| e.to_string())?;
            app_state.codex_app_server.clone()
        };
        if codex_client.is_none() {
            emit_canvas_assistant_event(
                Some(&app),
                &turn_id,
                "codex_bridge",
                "Je demarre le runtime Codex persistant pour Forge.",
                json!({
                    "runtime": "Codex app-server",
                    "mode": "persistent_stdio",
                }),
            );
            match tauri::async_runtime::spawn_blocking(CodexAppServerClient::start)
                .await
                .map_err(|e| format!("join Codex app-server start: {e}"))?
            {
                Ok(client) => {
                    let new_client = Arc::new(client);
                    let mut app_state = state.lock().map_err(|e| e.to_string())?;
                    let client = if let Some(existing) = app_state.codex_app_server.as_ref() {
                        existing.clone()
                    } else {
                        app_state.codex_app_server = Some(new_client.clone());
                        new_client
                    };
                    codex_client = Some(client);
                }
                Err(err) => {
                    codex_start_error = Some(err);
                }
            }
        }
    }
    let codex_attempt_message = if gemini_canvas_available {
        let gemini_message = request.message.clone();
        let gemini_model = effective_model_ref.clone();
        let gemini_reasoning_effort = reasoning_effort.clone();
        let gemini_store_path = store_path_for_codex_tools.clone();
        let app_for_gemini = app.clone();
        let turn_for_gemini = turn_id.clone();
        let gemini_active_job_id = request.job_id.clone();
        let gemini_session_key = request
            .job_id
            .clone()
            .filter(|s| !s.trim().is_empty())
            .unwrap_or_else(|| "forge-default".to_string());
        let gemini_session_key = format!(
            "{}:{}",
            gemini_session_key,
            if tools_enabled { "tools" } else { "chat" }
        );
        let (gemini_compact_memory, gemini_generation) =
            prepare_gemini_thread_memory(&state, &gemini_session_key)?;
        match tauri::async_runtime::spawn_blocking(move || {
            run_gemini_canvas_cli(
                gemini_message,
                tools_enabled,
                gemini_compact_memory,
                gemini_generation,
                gemini_model,
                gemini_reasoning_effort,
                gemini_store_path,
                gemini_active_job_id,
                Some(app_for_gemini),
                turn_for_gemini,
            )
        })
        .await
        .map_err(|e| format!("join Gemini CLI bridge: {e}"))?
        {
            Ok((message, bridge)) => {
                record_gemini_thread_turn(
                    &state,
                    &gemini_session_key,
                    &request.message,
                    &message,
                );
                codex_bridge = bridge;
                Some(message)
            }
            Err(err) => {
                codex_bridge = json!({
                    "status": "unavailable",
                    "mode": "gemini headless",
                    "runtime": "Gemini CLI",
                    "error": err,
                });
                None
            }
        }
    } else if claude_canvas_available {
        let claude_message = request.message.clone();
        let claude_model = effective_model_ref.clone();
        let claude_reasoning_effort = reasoning_effort.clone();
        let claude_store_path = store_path_for_codex_tools.clone();
        let app_for_claude = app.clone();
        let turn_for_claude = turn_id.clone();
        let claude_active_job_id = request.job_id.clone();
        let claude_session_key = request
            .job_id
            .clone()
            .filter(|s| !s.trim().is_empty())
            .unwrap_or_else(|| "forge-default".to_string());
        let claude_session_key = format!(
            "{}:{}",
            claude_session_key,
            if tools_enabled { "tools" } else { "chat" }
        );
        let (claude_compact_memory, claude_generation) =
            prepare_claude_thread_memory(&state, &claude_session_key)?;
        match tauri::async_runtime::spawn_blocking(move || {
            run_claude_canvas_cli(
                claude_message,
                tools_enabled,
                claude_compact_memory,
                claude_generation,
                claude_model,
                claude_reasoning_effort,
                claude_store_path,
                claude_active_job_id,
                Some(app_for_claude),
                turn_for_claude,
            )
        })
        .await
        .map_err(|e| format!("join Claude Code CLI bridge: {e}"))?
        {
            Ok((message, bridge)) => {
                record_claude_thread_turn(
                    &state,
                    &claude_session_key,
                    &request.message,
                    &message,
                );
                codex_bridge = bridge;
                Some(message)
            }
            Err(err) => {
                codex_bridge = json!({
                    "status": "unavailable",
                    "mode": "claude headless",
                    "runtime": "Claude Code CLI",
                    "error": err,
                });
                None
            }
        }
    } else if provider.connected {
        if let Some(client) = codex_client {
            client.update_tool_context(CodexDynamicToolContext {
                store_path: Some(store_path_for_codex_tools.clone()),
                active_job_id: request.job_id.clone(),
                canvas_turn_id: Some(turn_id.clone()),
                app: Some(app.clone()),
                max_log_lines,
            })?;
            let codex_session_key = request
                .job_id
                .clone()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "forge-default".to_string());
            let codex_session_key = format!(
                "{}:{}",
                codex_session_key,
                if tools_enabled { "tools" } else { "chat" }
            );
            let codex_message = request.message.clone();
            let codex_model = effective_model_ref.clone();
            let codex_reasoning_effort = reasoning_effort.clone();
            let app_for_codex = app.clone();
            let turn_for_codex = turn_id.clone();
            let tools_for_codex = tools_enabled;
            match tauri::async_runtime::spawn_blocking(move || {
                run_codex_canvas_app_server(
                    client,
                    codex_message,
                    codex_session_key,
                    tools_for_codex,
                    codex_model,
                    codex_reasoning_effort,
                    Some(app_for_codex),
                    turn_for_codex,
                )
            })
            .await
            .map_err(|e| format!("join Codex app-server bridge: {e}"))?
            {
                Ok((message, bridge)) => {
                    codex_bridge = bridge;
                    Some(message)
                }
                Err(err) => {
                    if let Ok(mut app_state) = state.lock() {
                        app_state.codex_app_server = None;
                    }
                    codex_bridge = json!({
                        "status": "unavailable",
                        "mode": "codex app-server",
                        "error": err,
                    });
                    None
                }
            }
        } else if let Some(err) = codex_start_error {
            codex_bridge = json!({
                "status": "unavailable",
                "mode": "codex app-server",
                "error": err,
            });
            None
        } else {
            codex_bridge = json!({
                "status": "unavailable",
                "mode": "codex app-server",
                "error": "Codex app-server client was not available.",
            });
            None
        }
    } else {
        None
    };
    let context_mode = if context_loaded {
        "loaded_on_request"
    } else {
        "on_demand_not_loaded"
    };
    if let JsonValue::Object(ref mut bridge) = codex_bridge {
        bridge.insert(
            "requestedRuntime".to_string(),
            JsonValue::String(requested_runtime.clone()),
        );
        if auto_rerouted {
            bridge.insert(
                "fallbackRuntime".to_string(),
                JsonValue::String(runtime.clone()),
            );
        }
        bridge.insert("toolsEnabled".to_string(), JsonValue::Bool(tools_enabled));
        bridge.insert("contextLoaded".to_string(), JsonValue::Bool(context_loaded));
        bridge.insert(
            "contextMode".to_string(),
            JsonValue::String(context_mode.to_string()),
        );
        bridge.insert(
            "reasoningEffort".to_string(),
            JsonValue::String(reasoning_effort.clone()),
        );
    }
    let codex_responded = codex_attempt_message.is_some();
    let mut assistant_message = if let Some(message) = codex_attempt_message {
        message
    } else if provider.connected {
        if use_gemini {
            "Gemini n'a pas pu répondre cette fois. Forge va réessayer automatiquement.".to_string()
        } else if use_claude {
            "Claude n'a pas pu répondre cette fois. Forge va réessayer automatiquement.".to_string()
        } else {
            "Codex n'a pas pu répondre cette fois. Forge va réessayer automatiquement.".to_string()
        }
    } else {
        if use_gemini {
            if provider.installed || provider_terminal_running("gemini") {
                "Gemini est en cours de reconnexion. Réessaie dans un instant.".to_string()
            } else {
                "Gemini se prépare encore. Forge va terminer la connexion automatiquement.".to_string()
            }
        } else if use_claude {
            if provider.installed || provider_terminal_running("claude") {
                "Claude est en cours de reconnexion. Réessaie dans un instant.".to_string()
            } else {
                "Claude se prépare encore. Forge va terminer la connexion automatiquement.".to_string()
            }
        } else {
            "Codex est en cours de reconnexion. Réessaie dans un instant.".to_string()
        }
    };
    if assistant_message.trim().is_empty() {
        assistant_message = if use_gemini {
            "Gemini n'a pas renvoye de texte exploitable pour ce tour.".to_string()
        } else if use_claude {
            "Claude n'a pas renvoye de texte exploitable pour ce tour.".to_string()
        } else {
            "Codex n'a pas renvoye de texte exploitable pour ce tour.".to_string()
        };
    }
    assistant_message = sanitize_canvas_assistant_message(&assistant_message);
    if !context_loaded
        && provider.connected
        && codex_responded
        && codex_bridge
            .get("status")
            .and_then(JsonValue::as_str)
            .unwrap_or("")
            == "ok"
        && semantic_cache_is_cacheable(user_message, &assistant_message)
    {
        if let Some((normalized, tokens)) = semantic_cache_probe {
            if !normalized.is_empty() && tokens.len() >= 2 {
                let now_ms = now_epoch_ms();
                let mut app_state = state.lock().map_err(|e| e.to_string())?;
                app_state.semantic_cache.retain(|entry| {
                    now_ms.saturating_sub(entry.created_ms)
                        <= CODEX_CANVAS_SEMANTIC_CACHE_MAX_AGE_MS
                });
                if let Some(existing) = app_state
                    .semantic_cache
                    .iter_mut()
                    .find(|entry| entry.model_ref == cache_model_ref && entry.normalized == normalized)
                {
                    existing.assistant_message = assistant_message.clone();
                    existing.tokens = tokens;
                    existing.last_hit_ms = now_ms;
                } else {
                    app_state.semantic_cache.push(SemanticCacheEntry {
                        model_ref: cache_model_ref.clone(),
                        normalized,
                        tokens,
                        assistant_message: assistant_message.clone(),
                        created_ms: now_ms,
                        last_hit_ms: now_ms,
                        hits: 0,
                    });
                }
                app_state
                    .semantic_cache
                    .sort_by(|left, right| right.last_hit_ms.cmp(&left.last_hit_ms));
                if app_state.semantic_cache.len() > CODEX_CANVAS_SEMANTIC_CACHE_MAX_ENTRIES {
                    app_state
                        .semantic_cache
                        .truncate(CODEX_CANVAS_SEMANTIC_CACHE_MAX_ENTRIES);
                }
            }
        }
    }
    let tool_events = if context_loaded {
        vec![json!({
            "tool": "session_context",
            "transport": "internal_forge_tool_broker",
            "job_id": request_job_id_for_response,
            "files": file_count,
            "programs": program_count,
            "log_tail_lines": log_count
        })]
    } else {
        Vec::new()
    };
    Ok(ForgeCanvasAssistantResponse {
        assistant_message,
        provider,
        context,
        tool_events,
        codex_bridge,
    })
}

#[tauri::command]
async fn cancel_forge_canvas_activity(
    request: ForgeCanvasCancelRequest,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<JsonValue, String> {
    let turn_id = request
        .turn_id
        .as_deref()
        .map(str::trim)
        .filter(|v| !v.is_empty())
        .map(str::to_string);
    let job_id = request
        .job_id
        .as_deref()
        .map(str::trim)
        .filter(|v| !v.is_empty())
        .map(str::to_string);
    let reason = request
        .reason
        .as_deref()
        .map(str::trim)
        .filter(|v| !v.is_empty())
        .unwrap_or("Stopped from Forge canvas chat")
        .to_string();
    if let Some(ref job_id) = job_id {
        if !safe_forge_job_id(job_id) {
            return Err("invalid Forge job id".to_string());
        }
    }
    let (store_path, codex_client) = {
        let mut app_state = state.lock().map_err(|e| e.to_string())?;
        if let Some(ref turn_id) = turn_id {
            app_state.cancelled_canvas_turns.insert(turn_id.clone());
            mark_canvas_turn_cancelled_global(turn_id);
        }
        let codex_client = app_state.codex_app_server.take();
        (app_state.store_path.clone(), codex_client)
    };
    let codex_runtime_stopped = codex_client
        .as_ref()
        .map(|client| client.force_kill())
        .unwrap_or(false);
    let gemini_runtime_stopped = kill_gemini_active_process();
    let claude_runtime_stopped = kill_claude_active_process();
    let job_cancel = if let Some(job_id) = job_id.clone() {
        let cancel_reason = reason.clone();
        match tauri::async_runtime::spawn_blocking(move || {
            call_forge_mcp_tool(
                store_path,
                "cancel",
                json!({
                    "job_id": job_id,
                    "reason": cancel_reason,
                }),
            )
        })
        .await
        .map_err(|e| format!("join Forge MCP cancel: {e}"))?
        {
            Ok(value) => value,
            Err(err) => json!({
                "cancel_requested": false,
                "error": err,
            }),
        }
    } else {
        JsonValue::Null
    };
    Ok(json!({
        "turnId": turn_id,
        "jobId": job_id,
        "codexRuntimeStopped": codex_runtime_stopped,
        "geminiRuntimeStopped": gemini_runtime_stopped,
        "claudeRuntimeStopped": claude_runtime_stopped,
        "jobCancel": job_cancel,
    }))
}

fn safe_artifact_token(raw: &str, fallback: &str) -> String {
    let mut out = String::with_capacity(raw.len().max(1));
    for ch in raw.chars() {
        if ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_') {
            out.push(ch);
        } else if ch.is_whitespace() || matches!(ch, '.' | '/') {
            out.push('_');
        }
    }
    let out = out.trim_matches('_').to_string();
    if out.is_empty() {
        fallback.to_string()
    } else {
        out
    }
}

fn forge_3d_ply_bytes(mode: &Forge3dExportMode) -> Result<Vec<u8>, String> {
    if mode.positions.len() % 3 != 0 {
        return Err(format!("3D mode '{}' positions length is not divisible by 3", mode.mode));
    }
    let point_count = mode.positions.len() / 3;
    if point_count == 0 {
        return Err(format!("3D mode '{}' has no points", mode.mode));
    }
    if !mode.colors.is_empty() && mode.colors.len() != mode.positions.len() {
        return Err(format!("3D mode '{}' colors length does not match positions", mode.mode));
    }
    if let Some(sizes) = mode.sizes.as_ref() {
        if !sizes.is_empty() && sizes.len() != point_count {
            return Err(format!("3D mode '{}' sizes length does not match points", mode.mode));
        }
    }
    let mut text = String::with_capacity(256 + point_count.saturating_mul(64));
    text.push_str("ply\n");
    text.push_str("format ascii 1.0\n");
    text.push_str("comment Forge 3D mapping artifact; content-addressed by manifest hash\n");
    text.push_str(&format!("comment mode {}\n", safe_artifact_token(&mode.mode, "view")));
    text.push_str(&format!("element vertex {point_count}\n"));
    text.push_str("property float x\n");
    text.push_str("property float y\n");
    text.push_str("property float z\n");
    text.push_str("property uchar red\n");
    text.push_str("property uchar green\n");
    text.push_str("property uchar blue\n");
    text.push_str("property float size\n");
    text.push_str("end_header\n");
    for idx in 0..point_count {
        let p = idx * 3;
        let r = mode
            .colors
            .get(p)
            .copied()
            .unwrap_or(0.78)
            .clamp(0.0, 1.0);
        let g = mode
            .colors
            .get(p + 1)
            .copied()
            .unwrap_or(0.78)
            .clamp(0.0, 1.0);
        let b = mode
            .colors
            .get(p + 2)
            .copied()
            .unwrap_or(0.78)
            .clamp(0.0, 1.0);
        let size = mode
            .sizes
            .as_ref()
            .and_then(|sizes| sizes.get(idx))
            .copied()
            .unwrap_or(1.0);
        text.push_str(&format!(
            "{:.7} {:.7} {:.7} {} {} {} {:.4}\n",
            mode.positions[p],
            mode.positions[p + 1],
            mode.positions[p + 2],
            (r * 255.0).round() as u8,
            (g * 255.0).round() as u8,
            (b * 255.0).round() as u8,
            size
        ));
    }
    Ok(text.into_bytes())
}

#[tauri::command]
async fn export_forge_3d_artifacts(
    request: Forge3dExportRequest,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<JsonValue, String> {
    if !safe_forge_job_id(&request.job_id) {
        return Err("invalid Forge job id".to_string());
    }
    if request.modes.is_empty() {
        return Err("3D export requires at least one mode".to_string());
    }
    let jobs_dir = forge_jobs_dir_from_state(&state)?;
    let all_job_dirs = forge_job_mirror_dirs(&jobs_dir);
    let (manifest_path, bytes) = read_forge_job_manifest_from_dirs(&request.job_id, &all_job_dirs)?;
    let manifest_dir = manifest_path
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| jobs_dir.clone());
    let mut manifest: JsonValue = serde_json::from_slice(&bytes)
        .map_err(|e| format!("decode Forge job manifest: {e}"))?;
    let artifacts_dir = manifest_dir.join(format!("{}.artifacts", request.job_id));
    std::fs::create_dir_all(&artifacts_dir)
        .map_err(|e| format!("create Forge artifact dir '{}': {e}", artifacts_dir.display()))?;

    let mut artifacts = Vec::new();
    for mode in &request.modes {
        let mode_name = safe_artifact_token(&mode.mode, "view");
        let ply_bytes = forge_3d_ply_bytes(mode)?;
        let hash = quick_file_hash(&ply_bytes);
        let point_count = mode.positions.len() / 3;
        let ply_path = artifacts_dir.join(format!("{}.3d.{}.ply", request.job_id, mode_name));
        std::fs::write(&ply_path, &ply_bytes)
            .map_err(|e| format!("write Forge 3D artifact '{}': {e}", ply_path.display()))?;
        artifacts.push(json!({
            "kind": "visualization_3d",
            "artifact_type": "point_cloud",
            "mode": mode.mode,
            "format": "ply",
            "mime": "model/x.ply",
            "path": ply_path.display().to_string(),
            "bytes": ply_bytes.len() as u64,
            "hash_algorithm": "forge_fnv1a64",
            "hash": format!("{hash:016x}"),
            "point_count": point_count as u64,
            "draw_mode": mode.draw_mode.as_deref().unwrap_or("points"),
            "point_size": mode.point_size.unwrap_or(1.0),
            "legend": mode.legend.clone().unwrap_or(JsonValue::Null),
            "mcp_injectable": true,
            "download": {
                "delivery": "by_reference",
                "path": ply_path.display().to_string(),
                "do_not_inline": true
            }
        }));
    }

    let index_path = artifacts_dir.join(format!("{}.3d.index.json", request.job_id));
    let index = json!({
        "kind": "visualization_3d_index",
        "job_id": request.job_id,
        "title": request.title,
        "source_name": request.source_name,
        "source_path": request.source_path,
        "bars": request.bars,
        "created_ms": now_epoch_ms() as u64,
        "formats": ["ply"],
        "content_policy": {
            "source_content_included": false,
            "point_cloud_content_returned_to_llm": false,
            "download_by_reference_only": true
        },
        "artifacts": artifacts
    });
    let index_bytes = serde_json::to_vec_pretty(&index)
        .map_err(|e| format!("encode Forge 3D index: {e}"))?;
    std::fs::write(&index_path, &index_bytes)
        .map_err(|e| format!("write Forge 3D index '{}': {e}", index_path.display()))?;
    let index_hash = quick_file_hash(&index_bytes);

    let visual_mapping_path = artifacts_dir.join(format!("{}.visual_mapping.json", request.job_id));
    let mapping_views = artifacts
        .iter()
        .map(|artifact| {
            let mode = artifact
                .get("mode")
                .and_then(JsonValue::as_str)
                .unwrap_or("view");
            json!({
                "id": format!("alpha_3d_{mode}"),
                "title": format!("Alpha 3D {mode}"),
                "type": artifact.get("artifact_type").cloned().unwrap_or_else(|| json!("point_cloud")),
                "artifact_path": artifact.get("path").cloned().unwrap_or(JsonValue::Null),
                "artifact_hash": artifact.get("hash").cloned().unwrap_or(JsonValue::Null),
                "format": artifact.get("format").cloned().unwrap_or_else(|| json!("ply")),
                "point_count": artifact.get("point_count").cloned().unwrap_or(JsonValue::Null),
                "legend": artifact.get("legend").cloned().unwrap_or(JsonValue::Null),
                "axes": [
                    { "axis": "x", "meaning": "normalized time / phase coordinate selected by the view mode" },
                    { "axis": "y", "meaning": "price, feature height or manifold coordinate selected by the view mode" },
                    { "axis": "z", "meaning": "volatility, regime or separation coordinate selected by the view mode" }
                ],
                "selection_contract": {
                    "select_returns": ["job_id", "mode", "artifact_path", "artifact_hash", "source_name", "bar_index_when_available"],
                    "raw_input_returned": false
                }
            })
        })
        .collect::<Vec<_>>();
    let visual_mapping_doc = json!({
        "version": "forge.visual_mapping.v1",
        "kind": "alpha_result_visual_mapping",
        "job_id": request.job_id,
        "title": request.title,
        "source_name": request.source_name,
        "source_path": request.source_path,
        "bars": request.bars,
        "created_ms": now_epoch_ms() as u64,
        "source_artifacts": {
            "visualization_3d_index_path": index_path.display().to_string(),
            "visualization_3d_index_hash_algorithm": "forge_fnv1a64",
            "visualization_3d_index_hash": format!("{index_hash:016x}")
        },
        "views": mapping_views,
        "content_policy": {
            "raw_input_included": false,
            "point_cloud_content_inlined_to_llm": false,
            "download_by_reference_only": true
        },
        "agent_guidance": [
            "Use this mapping to choose the right 3D artifact for the completed compute result.",
            "Do not inline .ply contents into the LLM context.",
            "Use Forge MCP read { kind:'artifacts', job_id } to fetch downloadable file references and hashes."
        ]
    });
    let visual_mapping_bytes = serde_json::to_vec_pretty(&visual_mapping_doc)
        .map_err(|e| format!("encode Forge visual mapping: {e}"))?;
    std::fs::write(&visual_mapping_path, &visual_mapping_bytes).map_err(|e| {
        format!(
            "write Forge visual mapping '{}': {e}",
            visual_mapping_path.display()
        )
    })?;
    let visual_mapping_hash = quick_file_hash(&visual_mapping_bytes);

    if let JsonValue::Object(ref mut obj) = manifest {
        obj.insert(
            "visualization_3d".to_string(),
            json!({
                "available": true,
                "created_ms": now_epoch_ms() as u64,
                "mode_count": artifacts.len() as u64,
                "index_path": index_path.display().to_string(),
                "index_bytes": index_bytes.len() as u64,
                "index_hash_algorithm": "forge_fnv1a64",
                "index_hash": format!("{index_hash:016x}"),
                "download_by_reference_only": true,
                "mcp_injectable": true
            }),
        );
        obj.insert("artifacts_3d".to_string(), json!(artifacts));
        obj.insert("visualization_3d_index_path".to_string(), json!(index_path.display().to_string()));
        obj.insert("visual_mapping_path".to_string(), json!(visual_mapping_path.display().to_string()));
        obj.insert(
            "visual_mapping".to_string(),
            json!({
                "available": true,
                "version": "forge.visual_mapping.v1",
                "kind": "alpha_result_visual_mapping",
                "path": visual_mapping_path.display().to_string(),
                "bytes": visual_mapping_bytes.len() as u64,
                "hash_algorithm": "forge_fnv1a64",
                "hash": format!("{visual_mapping_hash:016x}"),
                "view_count": artifacts.len() as u64,
                "download_by_reference_only": true,
                "mcp_injectable": true
            }),
        );
    }
    let manifest_bytes = serde_json::to_vec_pretty(&manifest)
        .map_err(|e| format!("encode Forge job manifest: {e}"))?;
    write_forge_job_manifest_to_dirs(&request.job_id, &manifest_bytes, &all_job_dirs)?;
    Ok(json!({
        "job_id": request.job_id,
        "visualization_3d": manifest.get("visualization_3d").cloned().unwrap_or(JsonValue::Null),
        "artifacts_3d": manifest.get("artifacts_3d").cloned().unwrap_or(JsonValue::Null),
        "visual_mapping": manifest.get("visual_mapping").cloned().unwrap_or(JsonValue::Null),
        "index_path": index_path.display().to_string(),
        "index_hash": format!("{index_hash:016x}"),
        "visual_mapping_path": visual_mapping_path.display().to_string(),
        "visual_mapping_hash": format!("{visual_mapping_hash:016x}"),
        "content_policy": {
            "source_content_included": false,
            "artifact_content_included": false,
            "download_by_reference_only": true
        }
    }))
}

#[tauri::command]
async fn read_forge_job_file(
    job_id: String,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<ForgeJobFilePayload, String> {
    if !safe_forge_job_id(&job_id) {
        return Err("invalid Forge job id".to_string());
    }
    let jobs_dir = forge_jobs_dir_from_state(&state)?;
    let all_job_dirs = forge_job_mirror_dirs(&jobs_dir);
    let (_manifest_path, manifest_bytes) = read_forge_job_manifest_from_dirs(&job_id, &all_job_dirs)?;
    let manifest: JsonValue = serde_json::from_slice(&manifest_bytes)
        .map_err(|e| format!("decode Forge job manifest: {e}"))?;
    let file_path = manifest
        .get("file_path")
        .and_then(|v| v.as_str())
        .filter(|v| !v.trim().is_empty())
        .unwrap_or("");
    if file_path.is_empty()
        && manifest
            .get("file_paths")
            .and_then(|v| v.as_array())
            .map(|v| v.is_empty())
            .unwrap_or(true)
    {
        let file_name = manifest
            .get("title")
            .and_then(|v| v.as_str())
            .map(str::to_string)
            .unwrap_or_else(|| "Empty session".to_string());
        return Ok(ForgeJobFilePayload {
            file_name,
            file_path: String::new(),
            text: String::new(),
            bytes: 0,
            files: Vec::new(),
        });
    }
    let manifest_paths = manifest
        .get("file_paths")
        .and_then(|v| v.as_array())
        .map(|paths| {
            paths
                .iter()
                .filter_map(|v| v.as_str())
                .filter(|v| !v.trim().is_empty())
                .map(str::to_string)
                .collect::<Vec<_>>()
        })
        .filter(|paths| !paths.is_empty())
        .unwrap_or_else(|| vec![file_path.to_string()]);
    let manifest_names = manifest
        .get("original_file_names")
        .and_then(|v| v.as_array())
        .map(|names| {
            names
                .iter()
                .map(|v| v.as_str().unwrap_or("").to_string())
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let mut files = Vec::with_capacity(manifest_paths.len());
    for (idx, raw_path) in manifest_paths.iter().enumerate() {
        let path = PathBuf::from(raw_path);
        let bytes = std::fs::read(&path)
            .map_err(|e| format!("read Forge job file '{}': {e}", path.display()))?;
        let file_name = manifest_names
            .get(idx)
            .filter(|v| !v.trim().is_empty())
            .cloned()
            .or_else(|| path.file_name().and_then(|v| v.to_str()).map(str::to_string))
            .unwrap_or_else(|| "upload.csv".to_string());
        files.push(ForgeJobSourceFilePayload {
            file_name,
            file_path: path.display().to_string(),
            text: String::from_utf8_lossy(&bytes).to_string(),
            bytes: bytes.len() as u64,
        });
    }
    let primary = files
        .first()
        .ok_or_else(|| "Forge job has no readable source files".to_string())?;
    Ok(ForgeJobFilePayload {
        file_name: primary.file_name.clone(),
        file_path: primary.file_path.clone(),
        text: primary.text.clone(),
        bytes: primary.bytes,
        files,
    })
}

#[tauri::command]
async fn read_forge_job_artifact_text(
    job_id: String,
    kind: String,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<ForgeJobArtifactTextPayload, String> {
    if !safe_forge_job_id(&job_id) {
        return Err("invalid Forge job id".to_string());
    }
    let artifact_kind = safe_artifact_token(&kind, "manifest");
    let jobs_dir = forge_jobs_dir_from_state(&state)?;
    let all_job_dirs = forge_job_mirror_dirs(&jobs_dir);
    let (manifest_path, manifest_bytes) = read_forge_job_manifest_from_dirs(&job_id, &all_job_dirs)?;
    let manifest_dir = manifest_path
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| jobs_dir.clone());
    let manifest: JsonValue = serde_json::from_slice(&manifest_bytes)
        .map_err(|e| format!("decode Forge job manifest: {e}"))?;
    let path = match artifact_kind.as_str() {
        "manifest" => manifest_path,
        "log" => manifest_dir.join(format!("{job_id}.log")),
        "metrics" | "metrics_path" => manifest
            .get("metrics_path")
            .and_then(|v| v.as_str())
            .map(PathBuf::from)
            .unwrap_or_else(|| manifest_dir.join(format!("{job_id}.metrics.json"))),
        "proof" | "proof_path" => manifest
            .get("proof_path")
            .and_then(|v| v.as_str())
            .map(PathBuf::from)
            .unwrap_or_else(|| manifest_dir.join(format!("{job_id}.proof.json"))),
        "visual_mapping" | "visual_mapping_path" => manifest
            .get("visual_mapping_path")
            .and_then(|v| v.as_str())
            .map(PathBuf::from)
            .unwrap_or_else(|| manifest_dir.join(format!("{job_id}.visual_mapping.json"))),
        "visualization_3d_index" | "visualization_3d_index_path" | "3d_index" => manifest
            .get("visualization_3d_index_path")
            .and_then(|v| v.as_str())
            .map(PathBuf::from)
            .unwrap_or_else(|| {
                manifest_dir
                    .join(format!("{job_id}.artifacts"))
                    .join(format!("{job_id}.3d.index.json"))
            }),
        _ => {
            return Err(format!(
                "unsupported artifact kind '{}'; expected manifest, log, metrics, proof, visual_mapping or visualization_3d_index",
                kind
            ));
        }
    };
    let canonical_jobs_dir = std::fs::canonicalize(&manifest_dir)
        .map_err(|e| format!("canonicalize jobs dir '{}': {e}", manifest_dir.display()))?;
    let canonical_path = std::fs::canonicalize(&path)
        .map_err(|e| format!("artifact '{}' is not available yet: {e}", path.display()))?;
    if !canonical_path.starts_with(&canonical_jobs_dir) {
        return Err("artifact path escapes Forge jobs directory".to_string());
    }
    let bytes = std::fs::read(&canonical_path)
        .map_err(|e| format!("read Forge artifact '{}': {e}", canonical_path.display()))?;
    const MAX_TEXT_ARTIFACT_BYTES: usize = 2 * 1024 * 1024;
    if bytes.len() > MAX_TEXT_ARTIFACT_BYTES {
        return Err(format!(
            "artifact '{}' is too large for text download: {} > {} bytes",
            canonical_path.display(),
            bytes.len(),
            MAX_TEXT_ARTIFACT_BYTES
        ));
    }
    let hash = quick_file_hash(&bytes);
    Ok(ForgeJobArtifactTextPayload {
        kind: artifact_kind,
        file_name: canonical_path
            .file_name()
            .and_then(|v| v.to_str())
            .unwrap_or("forge-artifact.json")
            .to_string(),
        file_path: canonical_path.display().to_string(),
        text: String::from_utf8_lossy(&bytes).to_string(),
        bytes: bytes.len() as u64,
        hash_algorithm: "forge_fnv1a64".to_string(),
        hash: format!("{hash:016x}"),
        content_policy: json!({
            "ui_download_only": true,
            "source_content_included": false,
            "large_point_cloud_included": false,
            "mcp_should_use_references": true
        }),
    })
}

#[tauri::command]
async fn update_forge_job(
    request: ForgeJobUpdateRequest,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<(), String> {
    if !safe_forge_job_id(&request.job_id) {
        return Err("invalid Forge job id".to_string());
    }
    let jobs_dir = forge_jobs_dir_from_state(&state)?;
    let all_job_dirs = forge_job_mirror_dirs(&jobs_dir);
    let (_manifest_path, bytes) = read_forge_job_manifest_from_dirs(&request.job_id, &all_job_dirs)?;
    let mut value: JsonValue = serde_json::from_slice(&bytes)
        .map_err(|e| format!("decode Forge job manifest: {e}"))?;
    let obj = value
        .as_object_mut()
        .ok_or_else(|| "Forge job manifest is not an object".to_string())?;
    obj.insert("protected".to_string(), json!(true));
    obj.insert("history_protected".to_string(), json!(true));
    match request.action.as_str() {
        "pin" => {
            let next = !obj.get("pinned").and_then(|v| v.as_bool()).unwrap_or(false);
            obj.insert("pinned".to_string(), json!(next));
        }
        "rename" => {
            let title = request
                .title
                .as_deref()
                .map(str::trim)
                .filter(|v| !v.is_empty())
                .ok_or_else(|| "rename requires a non-empty title".to_string())?;
            obj.insert("title".to_string(), json!(title));
        }
        "archive" => {
            obj.insert("archived".to_string(), json!(true));
        }
        "delete" => {
            obj.insert("deleted".to_string(), json!(true));
            obj.insert("archived".to_string(), json!(true));
            obj.insert("deleted_ms".to_string(), json!(now_epoch_ms() as u64));
        }
        other => return Err(format!("unknown Forge job action: {other}")),
    }
    let manifest_bytes = serde_json::to_vec_pretty(&value)
        .map_err(|e| format!("encode Forge job manifest: {e}"))?;
    write_forge_job_manifest_to_dirs(&request.job_id, &manifest_bytes, &all_job_dirs)?;
    Ok(())
}

#[tauri::command]
async fn persist_forge_canvas_session_state(
    request: ForgeCanvasSessionStateRequest,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<(), String> {
    if !safe_forge_job_id(&request.job_id) {
        return Err("invalid Forge job id".to_string());
    }
    let jobs_dir = forge_jobs_dir_from_state(&state)?;
    let all_job_dirs = forge_job_mirror_dirs(&jobs_dir);
    let (_manifest_path, bytes) = read_forge_job_manifest_from_dirs(&request.job_id, &all_job_dirs)?;
    let mut value: JsonValue = serde_json::from_slice(&bytes)
        .map_err(|e| format!("decode Forge job manifest: {e}"))?;
    let obj = value
        .as_object_mut()
        .ok_or_else(|| "Forge job manifest is not an object".to_string())?;
    obj.insert("protected".to_string(), json!(true));
    obj.insert("history_protected".to_string(), json!(true));
    let messages: Vec<JsonValue> = request
        .messages
        .into_iter()
        .filter_map(|message| {
            let role = message.role.trim().to_string();
            let text = message.text.trim().to_string();
            if role.is_empty() || text.is_empty() {
                return None;
            }
            Some(json!({
                "id": message.id.unwrap_or(JsonValue::Null),
                "role": role,
                "text": text,
                "meta": message.meta.unwrap_or_else(|| json!({})),
                "at": message.at.unwrap_or_else(|| "".to_string()),
            }))
        })
        .take(80)
        .collect();
    obj.insert("canvas_chat".to_string(), json!({
        "target_mode": request.target_mode.unwrap_or_else(|| "codex".to_string()),
        "messages": messages,
        "saved_at": now_epoch_ms() as u64,
    }));
    let manifest_bytes = serde_json::to_vec_pretty(&value)
        .map_err(|e| format!("encode Forge job manifest: {e}"))?;
    write_forge_job_manifest_to_dirs(&request.job_id, &manifest_bytes, &all_job_dirs)?;
    Ok(())
}

/// Fast non-cryptographic fingerprint of file bytes — used as run-cache key.
/// Good enough for "same file?" identity; not for security.
#[tauri::command]
async fn publish_forge_job_to_mcp(
    job_id: String,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<JsonValue, String> {
    if !safe_forge_job_id(&job_id) {
        return Err("invalid Forge job id".to_string());
    }
    let jobs_dir = forge_jobs_dir_from_state(&state)?;
    let all_job_dirs = forge_job_mirror_dirs(&jobs_dir);
    let (manifest_path, bytes) = read_forge_job_manifest_from_dirs(&job_id, &all_job_dirs)?;
    let manifest_dir = manifest_path
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| jobs_dir.clone());
    let mut value: JsonValue = serde_json::from_slice(&bytes)
        .map_err(|e| format!("decode Forge job manifest: {e}"))?;
    let log_path = manifest_dir.join(format!("{job_id}.log"));
    let obj = value
        .as_object_mut()
        .ok_or_else(|| "Forge job manifest is not an object".to_string())?;
    let visualization_3d = obj.get("visualization_3d").cloned().unwrap_or(JsonValue::Null);
    let artifacts_3d = obj.get("artifacts_3d").cloned().unwrap_or_else(|| json!([]));
    let visual_mapping = obj.get("visual_mapping").cloned().unwrap_or(JsonValue::Null);
    obj.insert(
        "mcp_result".to_string(),
        json!({
            "available": true,
            "published_ms": now_epoch_ms() as u64,
            "job_id": job_id.clone(),
            "manifest_path": manifest_path.display().to_string(),
            "manifest_bytes": std::fs::metadata(&manifest_path).map(|m| m.len()).unwrap_or(0),
            "log_path": log_path.display().to_string(),
            "log_bytes": std::fs::metadata(&log_path).map(|m| m.len()).unwrap_or(0),
            "result_reference": {
                "tool": "read_forge_job_manifest",
                "job_id": job_id.clone()
            },
            "visualization_3d": visualization_3d,
            "artifacts_3d": artifacts_3d,
            "visual_mapping": visual_mapping,
            "agent_delivery_guidance": [
                "Use Forge MCP read { kind:'artifacts', job_id } to fetch downloadable visual mapping and 3D artifact references.",
                "Use forge_analyze_3d_mapping when the user asks what the 3D geometry means; it returns compact PCA/cluster/outlier diagnostics without raw points.",
                "Do not inline .ply/.json metrics/proof artifacts into the LLM context.",
                "Attach/import the referenced files in the target agent app when supported."
            ]
        }),
    );
    let manifest_bytes = serde_json::to_vec_pretty(&value)
        .map_err(|e| format!("encode Forge job manifest: {e}"))?;
    write_forge_job_manifest_to_dirs(&job_id, &manifest_bytes, &all_job_dirs)?;
    Ok(value)
}

fn quick_file_hash(bytes: &[u8]) -> u64 {
    let mut h: u64 = bytes.len() as u64;
    for &b in bytes {
        h = h.wrapping_mul(0x517cc1b727220a95).wrapping_add(b as u64);
    }
    h
}

/// Cached full run: all emitted lines + the final report. Replayed verbatim on
/// repeated identical (file_hash, kind) calls so the UI receives results instantly.
struct CachedRun {
    entries: Vec<(bool, String)>, // (is_log, msg)
    report: ProcessReport,
}

#[tauri::command]
async fn start_computation(
    bytes: Vec<u8>,
    kind: String,
    mode: String,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
    app: tauri::AppHandle,
) -> Result<ProcessReport, String> {
    // Session 2026-05-03 : la dropdown MODE A/B/C/D/E/F a été supprimée
    // de l'UI car le backend Forge fait maintenant l'auto-routing :
    //   - CPU auto-router v0/v1/v2 (75-243 ns sur Léger workloads)
    //   - dispatch_batch entry-level CPU-fast bypass
    //   - Multi-GPU split CUDA + WGPU parallèle quand 2 vendors différents
    //   - is_cpu_auto_routable filtre Léger CPU vs Lourd GPU
    //
    // Le paramètre `mode` est ignoré et forcé à "dispatch" — le path
    // unique qui invoque toute la chaîne d'auto-routing. Les branches
    // bypass/dedup/force-gpu/kasm-bypass/raw-mem ci-dessous sont
    // conservées comme code de référence pour benchmarking comparatif
    // mais ne sont plus accessibles depuis l'UI.
    let _user_mode = mode;
    let mode = "dispatch".to_string();
    let file_hash = quick_file_hash(&bytes);
    let file_hash_part = format!("file_hash={file_hash}");
    let bytes_part = format!("bytes={}", bytes.len());
    let home_compute_key = scan::compute_core::ComputeSurface::Home.stage_key(
        "start_computation:v1",
        &[&kind, &mode, &file_hash_part, &bytes_part],
    );
    let cache_key = (kind.clone(), mode.clone(), file_hash);

    let mut app_state = state.lock().map_err(|e| e.to_string())?;
    let backend = app_state.backend_mut()?;

    // ─── Run-level cache — best compute is no compute ─────────────
    if let Some(cached) = backend.run_cache.get(&cache_key) {
        emit_log(
            &app,
            format!("[{kind}] ⚡ CACHE HIT — same file+program, replaying instantly"),
        );
        emit_log(
            &app,
            format!(
                "[{kind}] compute_core={} surface=home/start_computation cache=hit",
                scan::compute_core::compact_hash(&home_compute_key)
            ),
        );
        for (is_log, msg) in &cached.entries {
            if *is_log {
                emit_log(&app, msg.clone());
            } else {
                emit_result(&app, msg.clone());
            }
        }
        return Ok(cached.report.clone());
    }

    let mut entries: Vec<(bool, String)> = Vec::new();
    macro_rules! log {
        ($($arg:tt)*) => {{
            let msg = format!($($arg)*);
            entries.push((true, msg.clone()));
            emit_log(&app, msg);
        }};
    }
    macro_rules! res {
        ($($arg:tt)*) => {{
            let msg = format!($($arg)*);
            entries.push((false, msg.clone()));
            emit_result(&app, msg);
        }};
    }

    // ─── Φ.ν.7g — Reverse Synthesis early dispatch ──────────────────
    //
    // Les kinds `reverse_synth_*` ne sont PAS des programmes KASM
    // pré-stockés (puisque c'est Forge qui doit les TROUVER). On
    // détourne ici avant le lookup `programs.get` qui échouerait.
    //
    // Le bypass de la self-test classique est volontaire : il n'y a
    // pas de référence Rust pour un programme que Forge doit
    // synthétiser à la volée. La correction est garantie par le
    // déterminisme bit-pour-bit du KASM (cf. doctrine §0) + le
    // self-test post-synthèse qui re-exécute les 10 premiers examples
    // sur le programme produit pour vérifier la stabilité.
    log!(
        "[{}] compute_core={} surface=home/start_computation route=dispatch",
        kind,
        scan::compute_core::compact_hash(&home_compute_key)
    );

    if kind.starts_with("reverse_synth_") {
        let t_start = Instant::now();
        log!("[{}] ⚙ reverse synthesis dispatch — parsing CSV...", kind);
        let bars = match synth_strategy::parse_csv(&bytes) {
            Ok(b) => b,
            Err(e) => {
                let msg = format!("CSV parse error: {e}");
                log!("✗ {msg}");
                return Err(msg);
            }
        };
        log!(
            "[{}] ✓ parsed {} bars (range: {} → {})",
            kind,
            bars.len(),
            ms_to_iso(bars.first().map(|b| b.time_ms).unwrap_or(0)),
            ms_to_iso(bars.last().map(|b| b.time_ms).unwrap_or(0)),
        );

        let cfg = synth_strategy::SynthConfig::default();
        log!(
            "[{}] config : SL={}pt, target_pnl/day={}pt, horizon={}bars, train_split={:.0}%",
            kind,
            cfg.sl_points,
            cfg.target_pnl_per_day,
            cfg.max_horizon_bars,
            cfg.train_split * 100.0,
        );

        // ─── Split temporel train / holdout ─────────────────────────
        // CRITIQUE : Forge ne doit voir QUE le train. Le holdout sert
        // exclusivement à mesurer la généralisation out-of-sample.
        let train_end_bar = synth_strategy::train_holdout_split(bars.len(), cfg);
        log!(
            "[{}] split temporel : train [{}, {}) | holdout [{}, {})",
            kind,
            synth_strategy::MIN_HISTORY,
            train_end_bar,
            train_end_bar,
            bars.len(),
        );

        log!("[{}] building train examples (atlas-backed) ...", kind);
        let synth_file_hash = quick_file_hash(&bytes);
        let train_examples = synth_strategy::build_examples_in_range_masked_with_atlas(
            &bars,
            synth_strategy::MIN_HISTORY..train_end_bar,
            cfg,
            &synth_strategy::FeatureMask::all(),
            &backend.atlas,
            synth_file_hash,
        );
        let n_long = train_examples.iter().filter(|(_, l)| *l == 1).count();
        let n_short = train_examples.iter().filter(|(_, l)| *l == -1).count();
        let n_flat = train_examples.iter().filter(|(_, l)| *l == 0).count();
        log!(
            "[{}] ✓ {} train examples : LONG={} ({:.1}%) SHORT={} ({:.1}%) FLAT={} ({:.1}%)",
            kind,
            train_examples.len(),
            n_long, 100.0 * n_long as f64 / train_examples.len().max(1) as f64,
            n_short, 100.0 * n_short as f64 / train_examples.len().max(1) as f64,
            n_flat, 100.0 * n_flat as f64 / train_examples.len().max(1) as f64,
        );

        // ─── Forge synthesis : progressive deepening ────────────────
        // Plutôt qu'un seul gros call evolve_i64_program(generations=5,
        // max_nodes=25), on fait 4 stages avec max_nodes croissant :
        //
        //   stage 1 : max_nodes=10 (~1-3s)  — programmes simples
        //   stage 2 : max_nodes=15 (~3-8s)  — programmes moyens
        //   stage 3 : max_nodes=20 (~8-20s) — programmes complexes
        //   stage 4 : max_nodes=25 (~20-60s)— search complète
        //
        // Avantages :
        //   - **Live progress** : 4 milestones loggés au user pendant
        //     la search au lieu d'un seul gros bloc silencieux
        //   - **Strats simples trouvées vite** : si stage 1 trouve déjà
        //     un programme à exact_train, on peut early-exit
        //   - **Best-of cumulatif** : on garde le programme avec le
        //     meilleur train_loss across stages
        let stages: [(usize, usize); 4] = [
            (10, 5),   // (max_nodes, generations)
            (15, 5),
            (20, 5),
            (25, 5),
        ];
        log!(
            "[{}] ⚙ Forge synthesis (progressive deepening, 4 stages, examples={}) ──",
            kind,
            train_examples.len(),
        );
        let synth_t0 = Instant::now();
        let mut best_outcome: Option<scan::MonsterEvolutionOutcome> = None;
        let mut total_candidates: usize = 0;
        for (stage_idx, &(max_nodes, generations)) in stages.iter().enumerate() {
            let stage_t0 = Instant::now();
            log!(
                "[{}]   stage {}/4 : max_nodes={}, generations={} ...",
                kind,
                stage_idx + 1,
                max_nodes,
                generations,
            );
            let evo_cfg = MonsterEvolutionConfig {
                generations,
                max_nodes,
                beam_width: 768,
                holdout_stride: 4,
                progress: None,
                skip_prepass: false,
            };
            // Φ.ν.7g — Heartbeat thread : émet un log toutes les 10s
            // pendant que evolve_i64_program tourne (sinon UI muet
            // pendant 30s à 5min selon la complexité du stage). Le
            // thread se kill quand stop=true (synth terminée). Polling
            // 200ms pour réagir vite au stop sans busy loop.
            let stop = Arc::new(AtomicBool::new(false));
            let heartbeat = {
                let stop = Arc::clone(&stop);
                let app_clone = app.clone();
                let kind_clone = kind.clone();
                let stage_num = stage_idx + 1;
                thread::spawn(move || {
                    let hb_start = Instant::now();
                    let mut last_emit = Instant::now();
                    while !stop.load(Ordering::Relaxed) {
                        thread::sleep(Duration::from_millis(200));
                        if last_emit.elapsed() >= Duration::from_secs(10) {
                            emit_log(&app_clone, format!(
                                "[{}]   ⏱  stage {}/4 still running... ({}s elapsed, max_nodes={})",
                                kind_clone, stage_num,
                                hb_start.elapsed().as_secs(),
                                max_nodes,
                            ));
                            last_emit = Instant::now();
                        }
                    }
                })
            };
            let synth_result = backend.node.evolve_i64_program(&train_examples, evo_cfg);
            stop.store(true, Ordering::Relaxed);
            let _ = heartbeat.join();
            match synth_result {
                Ok(outcome) => {
                    let stage_elapsed = stage_t0.elapsed();
                    total_candidates = total_candidates.saturating_add(outcome.candidates_evaluated);
                    log!(
                        "[{}]   stage {}/4 ✓ {:.2}s : source={} tried={} kept={} nodes={} train_loss={} exact_train={} exact_holdout={} atlas_score={:.0}%",
                        kind,
                        stage_idx + 1,
                        stage_elapsed.as_secs_f64(),
                        outcome.source,
                        outcome.combinations_tried,
                        outcome.candidates_evaluated,
                        outcome.program.nodes().len(),
                        outcome.train_loss,
                        outcome.exact_train,
                        outcome.exact_holdout,
                        if outcome.combinations_tried > 0 { 100.0 * outcome.atlas_score_hits as f64 / outcome.combinations_tried as f64 } else { 0.0 },
                    );
                    let is_better = best_outcome
                        .as_ref()
                        .map(|prev| {
                            (outcome.holdout_loss, outcome.train_loss, outcome.program.nodes().len())
                                < (prev.holdout_loss, prev.train_loss, prev.program.nodes().len())
                        })
                        .unwrap_or(true);
                    if is_better {
                        best_outcome = Some(outcome.clone());
                    }
                    // Early exit si on a déjà un programme exact sur train+holdout interne
                    if outcome.exact_train && outcome.exact_holdout {
                        log!(
                            "[{}]   early exit : stage {} a trouvé exact_train + exact_holdout, stages suivants skipés",
                            kind,
                            stage_idx + 1,
                        );
                        break;
                    }
                }
                Err(e) => {
                    log!(
                        "[{}]   stage {}/4 ✗ {} (continuing with next stage)",
                        kind,
                        stage_idx + 1,
                        e,
                    );
                }
            }
        }
        let synth_elapsed = synth_t0.elapsed();
        let outcome = best_outcome.ok_or_else(|| {
            "Forge synth failed: aucun stage n'a produit de programme valide".to_string()
        })?;
        log!(
            "[{}] ✓ synth done in {:.2}s total ({} candidates across all stages)",
            kind,
            synth_elapsed.as_secs_f64(),
            total_candidates,
        );
        log!(
            "[{}]   best : source={} nodes={} train_loss={} exact_train={} exact_holdout={}",
            kind,
            outcome.source,
            outcome.program.nodes().len(),
            outcome.train_loss,
            outcome.exact_train,
            outcome.exact_holdout,
        );
        log!("[{}] strategy hash: {}", kind, outcome.program_hash);

        // ─── Évaluation par-jour sur train et holdout ───────────────
        // On lance le programme synthétisé via call_one_i64 (bénéficie
        // automatiquement de l'auto-router CPU + du RAM cache pour les
        // features qui se répètent). Le predict_label callback fait
        // la conversion i64 sortie KASM → ±1 / 0 via signum().
        let prog_hash = outcome.program_hash;
        let predict = |features: i64| -> i64 {
            backend
                .node
                .call_one_i64(&prog_hash, features)
                .map(|v| v.signum())
                .unwrap_or(0)
        };
        let eval_t0 = Instant::now();
        log!("[{}] ⚙ evaluating strategy on TRAIN ({} bars) ...", kind, train_end_bar - synth_strategy::MIN_HISTORY);
        let eval_train = {
            let app_clone = app.clone();
            let kind_clone = kind.clone();
            synth_strategy::eval_strategy_with_progress(
                &bars,
                synth_strategy::MIN_HISTORY..train_end_bar,
                cfg,
                predict,
                move |done, total| {
                    let pct = 100.0 * done as f64 / total.max(1) as f64;
                    emit_log(&app_clone, format!(
                        "[{}]   train eval : {}/{} bars ({:.0}%)",
                        kind_clone, done, total, pct,
                    ));
                },
            )
        };
        log!("[{}] ⚙ evaluating strategy on HOLDOUT ({} bars) ...", kind, bars.len() - train_end_bar);
        let eval_holdout = {
            let app_clone = app.clone();
            let kind_clone = kind.clone();
            synth_strategy::eval_strategy_with_progress(
                &bars,
                train_end_bar..bars.len(),
                cfg,
                predict,
                move |done, total| {
                    let pct = 100.0 * done as f64 / total.max(1) as f64;
                    emit_log(&app_clone, format!(
                        "[{}]   holdout eval : {}/{} bars ({:.0}%)",
                        kind_clone, done, total, pct,
                    ));
                },
            )
        };
        let eval_elapsed = eval_t0.elapsed();
        log!(
            "[{}] ✓ eval done in {:.2}s ({} train + {} holdout decisions)",
            kind,
            eval_elapsed.as_secs_f64(),
            eval_train.total_trades,
            eval_holdout.total_trades,
        );

        res!("══ Reverse Synthesis — Forge real synth ══");
        res!("Strategy hash : {}", outcome.program_hash);
        res!("Source: {}  | KASM nodes: {}  | Synth time: {:.2}s | tried={} kept={} atlas_score={:.0}%",
             outcome.source, outcome.program.nodes().len(),
             synth_elapsed.as_secs_f64(),
             outcome.combinations_tried, outcome.candidates_evaluated,
             if outcome.combinations_tried > 0 { 100.0 * outcome.atlas_score_hits as f64 / outcome.combinations_tried as f64 } else { 0.0 });
        res!("");
        res!("─── TRAIN (in-sample) ───");
        res!("  {} jours évalués, {} trades ({} long, {} short)",
             eval_train.days_evaluated, eval_train.total_trades,
             eval_train.long_trades, eval_train.short_trades);
        res!("  WR par-trade : {:.1}%  | avg P&L/trade : {:.4}p  | total P&L : {:.3}p",
             eval_train.pct_winning_trades(),
             eval_train.avg_pnl_per_trade(),
             eval_train.total_pnl_points);
        res!("  ★ {:.1}% jours profitables (cumul ≥ +{}p)  [cible : ≥ 85%]",
             eval_train.pct_days_target_hit(), cfg.target_pnl_per_day);
        res!("");
        res!("─── HOLDOUT (out-of-sample, bougies non vues par Forge) ───");
        res!("  {} jours évalués, {} trades ({} long, {} short)",
             eval_holdout.days_evaluated, eval_holdout.total_trades,
             eval_holdout.long_trades, eval_holdout.short_trades);
        res!("  WR par-trade : {:.1}%  | avg P&L/trade : {:.4}p  | total P&L : {:.3}p",
             eval_holdout.pct_winning_trades(),
             eval_holdout.avg_pnl_per_trade(),
             eval_holdout.total_pnl_points);
        res!("  ★ {:.1}% jours profitables (cumul ≥ +{}p)  [cible : ≥ 85%]",
             eval_holdout.pct_days_target_hit(), cfg.target_pnl_per_day);
        res!("");
        let success = eval_holdout.pct_days_target_hit() >= 85.0
            && eval_holdout.total_trades >= 500;
        if success {
            res!("✓ STRATÉGIE TROUVÉE : holdout atteint la cible 85% jours profitables avec ≥500 trades");
        } else {
            res!("✗ Cible non atteinte sur holdout : {:.1}% jours profitables / {} trades (besoin ≥85% / ≥500)",
                 eval_holdout.pct_days_target_hit(), eval_holdout.total_trades);
            res!("  → Étape B (genetic search avec fitness aligné par-jour) reste à activer");
        }

        let elapsed = t_start.elapsed();
        let report = ProcessReport {
            kind: kind.clone(),
            total_kmers: train_examples.len(),
            distinct: eval_holdout.days_target_hit,
            elapsed_ms: elapsed.as_secs_f64() * 1000.0,
            ns_per_kmer: if train_examples.is_empty() {
                0.0
            } else {
                elapsed.as_nanos() as f64 / train_examples.len() as f64
            },
        };
        log!(
            "[{}] ✓ end-to-end {:.2}s ({} train ex, synth {:.2}s, eval {:.2}s)",
            kind,
            report.elapsed_ms / 1000.0,
            report.total_kmers,
            synth_elapsed.as_secs_f64(),
            eval_elapsed.as_secs_f64(),
        );
        backend.run_cache.insert(
            cache_key,
            CachedRun { entries: entries.clone(), report: report.clone() },
        );
        return Ok(report);
    }

    let program_hash = backend
        .programs
        .get(kind.as_str())
        .copied()
        .ok_or_else(|| format!("unknown program: {kind}"))?;

    // ─── Correctness self-test (10 inputs déterministes) ────────────
    let test_inputs: [i64; 10] = [
        0,
        1,
        42,
        -1,
        i64::MAX,
        i64::MIN,
        0x0123_4567_89AB_CDEF,
        -0x0123_4567_89AB_CDEF,
        0x5555_5555_5555_5555,
        0x1234_5678_9ABC_DEF0_u64 as i64,
    ];
    let test_calls: Vec<BatchCall> = test_inputs
        .iter()
        .map(|&x| BatchCall::new(program_hash, x.to_le_bytes().to_vec()))
        .collect();
    let test_results = backend
        .node
        .dispatch_batch(&test_calls, &backend.node)
        .map_err(|e| e.to_string())?;
    let mut mismatches: Vec<(i64, i64, i64)> = Vec::new();
    for (i, x) in test_inputs.iter().enumerate() {
        let expected = expected_for_program(&kind, *x).ok_or_else(|| {
            format!("no reference for program {kind}")
        })?;
        let expected_hash = Hash::for_blob(&expected.to_le_bytes());
        let actual_hash = test_results[i].call().result;
        if expected_hash != actual_hash {
            // On reload le résultat depuis le cache pour pouvoir loguer
            // la valeur i64 obtenue (pas juste son hash).
            // Dans tous les cas le hash mismatch suffit à invalider.
            mismatches.push((*x, expected, 0));
        }
    }
    if !mismatches.is_empty() {
        let summary: Vec<String> = mismatches
            .iter()
            .map(|(x, e, _a)| format!("input={x:#x} expected={e}"))
            .collect();
        emit_log(
            &app,
            format!(
                "✗ SELF-TEST {kind} FAILED: {} mismatch(es) - {}",
                mismatches.len(),
                summary.join(" | ")
            ),
        );
        return Err(format!(
            "Forge produced an incorrect result for program {kind} ({} mismatch(es) on {} deterministic inputs). File processing aborted.",
            mismatches.len(),
            test_inputs.len()
        ));
    }
    log!(
        "SELF-TEST {kind}: {}/{} inputs verified against Rust reference (Forge is correct)",
        test_inputs.len(),
        test_inputs.len()
    );

    // Phase 12.0 — analyse structurale du programme
    let structure = backend
        .node
        .analyze_program(&program_hash)
        .map_err(|e| e.to_string())?;
    let recurring_summary = if structure.recurring_ops.is_empty() {
        "(no recurring op - program is non-decomposable)".to_string()
    } else {
        structure
            .recurring_ops
            .iter()
            .map(|(op, c)| format!("{op}×{c}"))
            .collect::<Vec<_>>()
            .join(", ")
    };
    log!(
        "[Phi.12.0] {kind} -> class {} ({} nodes), recurring: {}",
        structure.size_label,
        structure.node_count,
        recurring_summary
    );

    log!("[{kind}] decoding k-mers (k={K})...");
    let (kmers, classes) = encode_kmers_with_class(&bytes);
    if kmers.is_empty() {
        return Err("no valid k-mer found".into());
    }
    let dispatch_chunk_size = dispatch_chunk_size();
    log!(
        "[{kind}] mode={} : {} k-mers extracted",
        mode,
        kmers.len()
    );

    let mut ram_memo = 0usize;
    let mut structural_rule = 0usize;
    let mut learned_oracle = 0usize;
    let mut git_memo = 0usize;
    let mut computed = 0usize;
    let mut dedup_distinct = 0usize;
    let mut dedup_ms = 0.0f64;
    let mut dispatch_ms = 0.0f64;

    let total = kmers.len();
    let start = Instant::now();

    match mode.as_str() {
        "bypass" => {
            // Pure-Rust path: ref_splitmix64 (or its kind-equivalent) per
            // k-mer. Forge dispatch_batch is never called for the bulk —
            // self-test alone proved Forge produces identical bytes.
            let mut sink: u64 = 0;
            for &k in &kmers {
                let r = expected_for_program(&kind, k)
                    .ok_or_else(|| format!("no reference for program {kind}"))?;
                sink = sink.wrapping_add(r as u64);
            }
            // Defeat dead-code elimination (sink is never read elsewhere).
            std::hint::black_box(sink);
            log!(
                "[{kind}] bypass : {} hashes computed via Rust-native reference (Forge untouched)",
                total
            );
        }
        "dedup" => {
            // Build distinct set, dispatch only on it, scatter is implicit
            // (freq map below is built from the raw kmers vec anyway).
            let dedup_start = Instant::now();
            let mut distinct: HashMap<i64, ()> = HashMap::with_capacity(total / 2);
            for &k in &kmers {
                distinct.insert(k, ());
            }
            let distinct_kmers: Vec<i64> = distinct.keys().copied().collect();
            dedup_ms = dedup_start.elapsed().as_secs_f64() * 1000.0;
            dedup_distinct = distinct_kmers.len();
            log!(
                "[{kind}] dedup : {} -> {} distinct ({:.1}% redundancy filtered) in {:.1} ms",
                total,
                dedup_distinct,
                (1.0 - dedup_distinct as f64 / total.max(1) as f64) * 100.0,
                dedup_ms
            );

            let dispatch_start = Instant::now();
            let total_chunks = dedup_distinct.div_ceil(dispatch_chunk_size);
            for (i, chunk) in distinct_kmers.chunks(dispatch_chunk_size).enumerate() {
                let calls: Vec<BatchCall> = chunk
                    .iter()
                    .map(|k| BatchCall::new(program_hash, k.to_le_bytes().to_vec()))
                    .collect();
                let results = backend
                    .node
                    .dispatch_batch(&calls, &backend.node)
                    .map_err(|e| e.to_string())?;

                let mut chunk_ram = 0usize;
                let mut chunk_rule = 0usize;
                let mut chunk_other = 0usize;
                let mut chunk_computed = 0usize;
                for r in &results {
                    match r.call().source {
                        MonsterSource::RamMemo => {
                            ram_memo += 1;
                            chunk_ram += 1;
                        }
                        MonsterSource::StructuralRule => {
                            structural_rule += 1;
                            chunk_rule += 1;
                        }
                        MonsterSource::LearnedOracle => {
                            learned_oracle += 1;
                            chunk_other += 1;
                        }
                        MonsterSource::GitMemo => {
                            git_memo += 1;
                            chunk_other += 1;
                        }
                        MonsterSource::ExecutedHot => {
                            computed += 1;
                            chunk_computed += 1;
                        }
                    }
                }
                log!(
                    "[{kind}] chunk {}/{} ({} distinct calls) : ram={} rule={} other={} computed={}",
                    i + 1,
                    total_chunks,
                    chunk.len(),
                    chunk_ram,
                    chunk_rule,
                    chunk_other,
                    chunk_computed
                );
            }
            dispatch_ms = dispatch_start.elapsed().as_secs_f64() * 1000.0;
        }
        "kasm-bypass" => {
            // Bypass dispatch_batch infrastructure but execute via KASM
            // (Forge bytecode), not Rust ref impl. Uses MonsterNode's
            // public batch API call_many_values_i64 which routes to the
            // tightest available KASM execution path (HashChain native
            // loop for kmer_hash) without per-call BatchCall allocations.
            let result_values = backend
                .node
                .call_many_values_i64(&program_hash, &kmers)
                .map_err(|e| e.to_string())?;
            std::hint::black_box(&result_values);
            log!(
                "kasm-bypass : {} hashes via call_many_values_i64 (Forge KASM batch, no dispatch_batch plumbing)",
                result_values.len()
            );
        }
        "raw-mem" => {
            // Zero Forge plumbing — pure local HashMap<i64,i64> in main.rs.
            // No BatchCall, no Arc, no RwLock, no IdentityHasher, no
            // MonsterSource accounting. Cache miss falls back to Rust
            // reference (since this mode is "what if we just memoize raw").
            let mut cache: HashMap<i64, i64> = HashMap::with_capacity(total / 2);
            let mut sink: u64 = 0;
            let mut hits = 0usize;
            let mut misses = 0usize;
            for &k in &kmers {
                let r = if let Some(&cached) = cache.get(&k) {
                    hits += 1;
                    cached
                } else {
                    misses += 1;
                    let v = expected_for_program(&kind, k)
                        .ok_or_else(|| format!("no reference for program {kind}"))?;
                    cache.insert(k, v);
                    v
                };
                sink = sink.wrapping_add(r as u64);
            }
            std::hint::black_box(sink);
            log!(
                "raw-mem : {} kmers, local cache hits={} misses={} ({} unique)",
                total,
                hits,
                misses,
                cache.len()
            );
        }
        "force-gpu" => {
            // Bypass the CPU brain entirely: build a contiguous byte buffer
            // and call BulkEvaluator::eval_batch directly on MonsterNode,
            // which routes to gpunode_runtime. Educational mode: shows the
            // raw cost of the muscle path without any cache mediation.
            //
            // Note: gpunode CUDA kernel only handles AffineI64 programs
            // (out = inp * mul + add). kmer_hash is HashChain, so muscle
            // will fall back to eval_serial (CPU interpreter loop).
            let bs = backend.node.gpunode_bootstrap();
            log!(
                "force-gpu : GPUs detected={}, CUDA enabled={}, NVIDIA={}, deployed gpunodes={}, nvrtc available={}",
                bs.detected_gpu_count,
                bs.cuda_enabled,
                bs.nvidia_detected,
                bs.deployed_gpunodes,
                bs.nvrtc_available
            );
            if let Some(warn) = bs.cuda_toolkit_warning() {
                log!("⚠ {}", warn);
                res!("⚠ CUDA Toolkit missing — see Forge logs for details");
            }
            log!(
                "force-gpu : delegating to gpunode_runtime.eval_batch on {} calls (brain bypassed)",
                total
            );

            // Pack all args into one Vec<u8> so BatchInput slices are zero-copy.
            let pack_start = Instant::now();
            let mut bytes_buf: Vec<u8> = Vec::with_capacity(total * 8);
            for &k in &kmers {
                bytes_buf.extend_from_slice(&k.to_le_bytes());
            }
            let inputs: Vec<BatchInput<'_>> = (0..total)
                .map(|i| BatchInput {
                    func: program_hash,
                    args: &bytes_buf[i * 8..(i + 1) * 8],
                })
                .collect();
            log!(
                "force-gpu : packed {} BatchInputs in {:.1} ms (bytes_buf={} MB)",
                inputs.len(),
                pack_start.elapsed().as_secs_f64() * 1000.0,
                bytes_buf.len() / 1_000_000
            );

            log!("force-gpu : launching gpunode_runtime.eval_batch (this is where CUDA kernel triggers if applicable)...");
            let muscle_start = Instant::now();
            let packed = BulkEvaluator::eval_batch(&backend.node, &inputs)
                .map_err(|e| format!("muscle eval_batch error: {e}"))?;
            let muscle_ms = muscle_start.elapsed().as_secs_f64() * 1000.0;

            // Surface what gpunode actually did (CUDA ran / panicked / fell back)
            // straight into the UI so the user doesn't have to check stderr.
            if let Some(status) = take_last_cuda_status() {
                log!("force-gpu : muscle status — {}", status);
            }

            log!(
                "force-gpu : gpunode_runtime returned {} results ({} bytes packed) in {:.1} ms",
                packed.len(),
                packed.bytes.len(),
                muscle_ms
            );
            // Throughput-based heuristic to tell user which path was taken.
            let ns_per_call = muscle_start.elapsed().as_nanos() as f64 / total as f64;
            if ns_per_call < 200.0 {
                log!("force-gpu : ~{:.0} ns/call → CUDA kernel ran on GPU (sub-microsecond)", ns_per_call);
            } else if ns_per_call < 2000.0 {
                log!("force-gpu : ~{:.0} ns/call → likely CUDA kernel + PCIe transfer", ns_per_call);
            } else {
                log!("force-gpu : ~{:.0} ns/call → likely fell back to eval_serial CPU (CUDA path refused or unavailable)", ns_per_call);
            }
        }
        _ /* "dispatch" */ => {
            let plan = ComputationPlan::build(
                &backend.node,
                kmers.iter().map(|k| (program_hash, k.to_le_bytes().to_vec())),
            );
            let atlas_pre_hits = plan.atlas_result_hits();
            git_memo += atlas_pre_hits;
            let novel: Vec<BatchCall> = plan
                .calls
                .iter()
                .enumerate()
                .filter(|(i, _)| !plan.atlas_result_known[*i])
                .map(|(_, c)| c.clone())
                .collect();
            log!(
                "[{kind}] ComputationPlan: {} inputs → {} unique ({:.1}% FNV dedup) | {} CSE classes | atlas skip {} | novel {}",
                plan.total_planned,
                plan.calls.len(),
                plan.input_dedup_pct(),
                plan.n_cse_classes,
                atlas_pre_hits,
                novel.len(),
            );

            if novel.is_empty() {
                log!("[{kind}] all calls atlas-known — zero compute");
            } else {
                let program_bytes = backend
                    .node
                    .store()
                    .load(&program_hash)
                    .ok_or_else(|| format!("program not in store: {program_hash}"))?;
                let program = Program::from_bytes(&program_bytes)
                    .map_err(|e| format!("invalid program: {e}"))?;
                let cpu_fast = program.nodes().len() <= 64
                    && program.inputs() == 1
                    && program.outputs() == 1;

                if cpu_fast {
                    log!(
                        "[{kind}] CPU-direct : {} calls × {} nodes — kasm::try_execute_i64_inline (no dispatch)",
                        novel.len(),
                        program.nodes().len()
                    );
                    let atlas = backend.node.atlas();
                    for call in &novel {
                        let arg = i64::from_le_bytes(call.args[..8].try_into().unwrap());
                        if let Some(result_i64) = scan::kasm::try_execute_i64_inline(&program, arg) {
                            if let Some(ref a) = atlas {
                                let result_hash = Hash::for_blob(&result_i64.to_le_bytes());
                                let key = scan::atlas::Atlas::result_key(
                                    call.func.as_bytes(),
                                    &call.args,
                                );
                                let _ = a.record_result(&key, result_hash.as_bytes());
                            }
                            computed += 1;
                        } else {
                            computed += 1;
                        }
                    }
                } else {
                    log!(
                        "[{kind}] GPU/heavy path : {} calls × {} nodes — dispatch_batch",
                        novel.len(),
                        program.nodes().len()
                    );
                    let total_chunks = novel.len().div_ceil(dispatch_chunk_size);
                    for (i, chunk) in novel.chunks(dispatch_chunk_size).enumerate() {
                        let results = backend
                            .node
                            .dispatch_batch(chunk, &backend.node)
                            .map_err(|e| e.to_string())?;
                        for r in &results {
                            match r.call().source {
                                MonsterSource::RamMemo => ram_memo += 1,
                                MonsterSource::StructuralRule => structural_rule += 1,
                                MonsterSource::LearnedOracle => learned_oracle += 1,
                                MonsterSource::GitMemo => git_memo += 1,
                                MonsterSource::ExecutedHot => computed += 1,
                            }
                        }
                        log!(
                            "[{kind}] chunk {}/{} ({} calls dispatched)",
                            i + 1,
                            total_chunks,
                            chunk.len()
                        );
                    }
                }
            }
        }
    }
    let elapsed = start.elapsed();

    // ─── Calculs biologiques (free, post-dispatch) ──────────────────
    let mut freq: HashMap<i64, u32> = HashMap::with_capacity(total / 2);
    let mut per_class_total: HashMap<u8, u64> = HashMap::new();
    for (km, cl) in kmers.iter().zip(classes.iter()) {
        *freq.entry(*km).or_insert(0) += 1;
        *per_class_total.entry(*cl).or_insert(0) += 1;
    }
    let distinct = freq.len();

    let mut top: Vec<(i64, u32)> = freq.iter().map(|(&k, &v)| (k, v)).collect();
    top.sort_unstable_by(|a, b| b.1.cmp(&a.1));
    top.truncate(TOP_N);

    let mut classes_sorted: Vec<(u8, u64)> = per_class_total.into_iter().collect();
    classes_sorted.sort_by_key(|(c, _)| *c);

    // ─── forge-result : pour le scientifique (onglet Résultats) ─────
    res!("=== Forge - analysis {kind} ===");
    res!("File: {} bytes", bytes.len());
    res!("KASM program: {kind}");
    res!(
        "Structure: {} ({} nodes, {})",
        structure.size_label,
        structure.node_count,
        if structure.is_decomposable {
            format!("decomposable: {}", recurring_summary)
        } else {
            "non-decomposable (atomic for Forge)".to_string()
        }
    );
    res!("");
    res!("-- k-mer summary --");
    res!("  total k-mers        : {}", total);
    res!("  distinct k-mers     : {}", distinct);
    res!(
        "  average redundancy   : {:.2}x ({:.1}% repeated positions)",
        total as f64 / distinct.max(1) as f64,
        (1.0 - distinct as f64 / total as f64) * 100.0
    );
    res!("");
    res!("-- class distribution (gene family) --");
    let total_f = total as f64;
    for (cl, n) in &classes_sorted {
        let label = if *cl == UNKNOWN_CLASS {
            "?".to_string()
        } else {
            cl.to_string()
        };
        res!(
            "  class {} : {:>10} k-mers ({:.1}%)",
            label,
            n,
            *n as f64 / total_f * 100.0
        );
    }
    res!("");
    res!("-- Top {} most frequent k-mers --", TOP_N);
    for (km, count) in &top {
        res!(
            "  {} : {:>7}x ({:.4}%)",
            decode_kmer(*km),
            count,
            *count as f64 / total_f * 100.0
        );
    }

    // ─── forge-log : pour le dev (onglet Forge) ─────────────────────
    log!("");
    log!("=== report {kind} mode={mode} ===");
    log!(
        "elapsed = {:.1} ms ({:.1} ns/k-mer effective on {} positions)",
        elapsed.as_secs_f64() * 1000.0,
        elapsed.as_nanos() as f64 / total.max(1) as f64,
        total
    );

    match mode.as_str() {
        "bypass" => {
            log!(
                "bypass : {} hashes via Rust-native ref_splitmix64 (Forge dispatch_batch never called for bulk)",
                total
            );
            log!("  Forge lanes : 0 (mode=bypass)");
        }
        "force-gpu" => {
            log!(
                "force-gpu : {} calls bypassed brain, hit muscle (gpunode_runtime.eval_batch)",
                total
            );
            log!("  Forge brain lanes : 0 (mode=force-gpu, brain bypassed)");
        }
        "kasm-bypass" => {
            log!(
                "kasm-bypass : {} hashes via Forge KASM batch (no dispatch_batch, no BatchCall)",
                total
            );
            log!("  Forge brain lanes : 0 (mode=kasm-bypass)");
        }
        "raw-mem" => {
            log!(
                "raw-mem : {} hashes via local HashMap<i64,i64> + Rust ref impl on miss (zero Forge dispatch infra)",
                total
            );
            log!("  Forge brain lanes : 0 (mode=raw-mem)");
        }
        "dedup" => {
            let denom = dedup_distinct.max(1) as f64;
            let total_hits = ram_memo + structural_rule + learned_oracle + git_memo;
            log!(
                "dedup phase  : {:.1} ms ({:.0} ns/kmer to dedup all {})",
                dedup_ms,
                dedup_ms * 1_000_000.0 / total.max(1) as f64,
                total
            );
            log!(
                "dispatch     : {:.1} ms on {} distinct ({:.0} ns/distinct)",
                dispatch_ms,
                dedup_distinct,
                dispatch_ms * 1_000_000.0 / denom
            );
            log!(
                "total hits   : {} / {} distinct ({:.1}%)",
                total_hits,
                dedup_distinct,
                total_hits as f64 / denom * 100.0
            );
            log!("- Forge lane breakdown (on distinct) -");
            log!("  RamMemo        : {:>10} ({:.1}%)", ram_memo, ram_memo as f64 / denom * 100.0);
            log!("  StructuralRule : {:>10} ({:.1}%)", structural_rule, structural_rule as f64 / denom * 100.0);
            log!("  LearnedOracle  : {:>10} ({:.1}%)", learned_oracle, learned_oracle as f64 / denom * 100.0);
            log!("  GitMemo        : {:>10} ({:.1}%)", git_memo, git_memo as f64 / denom * 100.0);
            log!("  Computed       : {:>10} ({:.1}%) - muscle (CPU/GPU)", computed, computed as f64 / denom * 100.0);
        }
        _ /* dispatch */ => {
            let total_hits = ram_memo + structural_rule + learned_oracle + git_memo;
            log!(
                "total hits : {} / {} ({:.1}%)",
                total_hits,
                total,
                total_hits as f64 / total_f * 100.0
            );
            log!("- Forge lane breakdown -");
            log!(
                "  RamMemo        : {:>10} ({:.1}%) - cache content-addressed",
                ram_memo,
                ram_memo as f64 / total_f * 100.0
            );
            log!(
                "  StructuralRule : {:>10} ({:.1}%) - native rule (HashChain etc.)",
                structural_rule,
                structural_rule as f64 / total_f * 100.0
            );
            log!(
                "  LearnedOracle  : {:>10} ({:.1}%) - learned shortcut",
                learned_oracle,
                learned_oracle as f64 / total_f * 100.0
            );
            log!(
                "  GitMemo        : {:>10} ({:.1}%) - disk memo",
                git_memo,
                git_memo as f64 / total_f * 100.0
            );
            log!(
                "  Computed       : {:>10} ({:.1}%) - muscle (CPU/GPU)",
                computed,
                computed as f64 / total_f * 100.0
            );
        }
    }

    // Phase 12.1 — sub-scale (op-level Hash64 memoization)
    let stats = backend.node.stats();
    let op_total = stats.op_memo_hits + stats.op_memo_misses;
    if op_total > 0 {
        log!("- Phase 12.1 sub-scale (Hash64 op-memo) -");
        log!(
            "  Hash64 op hits : {:>10} ({:.1}% of {} Hash64 calls)",
            stats.op_memo_hits,
            stats.op_memo_hits as f64 / op_total as f64 * 100.0,
            op_total
        );
        log!(
            "  Hash64 op miss : {:>10} ({:.1}%) - compute + insert into op_memo",
            stats.op_memo_misses,
            stats.op_memo_misses as f64 / op_total as f64 * 100.0
        );
    }

    let report = ProcessReport {
        kind,
        total_kmers: total,
        distinct,
        elapsed_ms: elapsed.as_secs_f64() * 1000.0,
        ns_per_kmer: elapsed.as_nanos() as f64 / total.max(1) as f64,
    };

    // Store for instant replay on repeated (file, program) pairs.
    backend.run_cache.insert(cache_key, CachedRun { entries, report: report.clone() });

    Ok(report)
}

/// Opens a URL in the user's default browser. Used by the GPU startup
/// modal to let the user click straight to the CUDA Toolkit download page.
/// Validates against an allow-list to prevent abuse via injected URLs.
#[tauri::command]
async fn open_url(url: String) -> Result<(), String> {
    const ALLOWED_PREFIXES: &[&str] = &[
        "https://developer.nvidia.com/",
        "https://docs.rs/wgpu/",
        "https://github.com/gfx-rs/wgpu",
    ];
    if !ALLOWED_PREFIXES.iter().any(|p| url.starts_with(p)) {
        return Err(format!("URL not in allow-list: {url}"));
    }
    #[cfg(windows)]
    {
        std::process::Command::new("cmd")
            .args(["/C", "start", "", &url])
            .spawn()
            .map_err(|e| format!("failed to open url: {e}"))?;
    }
    #[cfg(target_os = "macos")]
    {
        std::process::Command::new("open")
            .arg(&url)
            .spawn()
            .map_err(|e| format!("failed to open url: {e}"))?;
    }
    #[cfg(target_os = "linux")]
    {
        std::process::Command::new("xdg-open")
            .arg(&url)
            .spawn()
            .map_err(|e| format!("failed to open url: {e}"))?;
    }
    Ok(())
}

#[derive(Serialize)]
struct WgpuSwitchResult {
    /// "available" — wgpu compiled in, runtime switch performed
    /// "needs-rebuild" — wgpu not in this build, user must rebuild
    status: String,
    message: String,
    rebuild_command: Option<String>,
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct WorkspaceFolderInfo {
    name: String,
    path: String,
    reveal_label: String,
}

static WORKSPACE_OVERRIDE: OnceLock<Mutex<Option<PathBuf>>> = OnceLock::new();

fn workspace_override_lock() -> &'static Mutex<Option<PathBuf>> {
    WORKSPACE_OVERRIDE.get_or_init(|| Mutex::new(None))
}

pub(crate) fn forge_workspace_dir() -> PathBuf {
    if let Ok(guard) = workspace_override_lock().lock() {
        if let Some(ref p) = *guard {
            return p.clone();
        }
    }
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    manifest_dir
        .ancestors()
        .nth(3)
        .map(PathBuf::from)
        .unwrap_or(manifest_dir)
}

pub(crate) fn forge_store_dir() -> PathBuf {
    if let Some(raw) = std::env::var_os("FORGE_STORE_DIR") {
        let trimmed = raw.to_string_lossy().trim().to_string();
        if !trimmed.is_empty() {
            return PathBuf::from(trimmed);
        }
    }
    forge_workspace_dir().join(".forge-store")
}

fn collect_forge_store_candidates(primary_store_path: &Path, app_data_store: Option<PathBuf>) -> Vec<PathBuf> {
    let workspace = forge_workspace_dir();
    let mut candidates = vec![
        workspace.join(".forge-store"),
        workspace.join("examples").join("forge_tauri_ui").join(".forge-store"),
        workspace.join("examples").join("forge_tauri_ui").join("src-tauri").join(".forge-store"),
    ];
    if let Some(app_data_store) = app_data_store {
        candidates.push(app_data_store);
    }
    let mut out = Vec::new();
    let mut seen = HashSet::new();
    for candidate in candidates {
        let key = candidate.to_string_lossy().to_string();
        if candidate == primary_store_path || !seen.insert(key) {
            continue;
        }
        if candidate.exists() {
            out.push(candidate);
        }
    }
    out
}

fn copy_file_if_missing_or_newer(source: &Path, target: &Path) -> Result<(), String> {
    let should_copy = match std::fs::metadata(target) {
        Ok(target_meta) => {
            let source_meta = std::fs::metadata(source)
                .map_err(|e| format!("stat source '{}': {e}", source.display()))?;
            let source_modified = source_meta.modified().unwrap_or(SystemTime::UNIX_EPOCH);
            let target_modified = target_meta.modified().unwrap_or(SystemTime::UNIX_EPOCH);
            source_modified > target_modified
        }
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => true,
        Err(err) => return Err(format!("stat target '{}': {err}", target.display())),
    };
    if !should_copy {
        return Ok(());
    }
    if let Some(parent) = target.parent() {
        std::fs::create_dir_all(parent)
            .map_err(|e| format!("create parent dir '{}': {e}", parent.display()))?;
    }
    std::fs::copy(source, target)
        .map_err(|e| format!("copy '{}' -> '{}': {e}", source.display(), target.display()))?;
    Ok(())
}

fn copy_dir_recursive_missing_or_newer(source_dir: &Path, target_dir: &Path) -> Result<(), String> {
    if !source_dir.exists() {
        return Ok(());
    }
    std::fs::create_dir_all(target_dir)
        .map_err(|e| format!("create dir '{}': {e}", target_dir.display()))?;
    let entries = std::fs::read_dir(source_dir)
        .map_err(|e| format!("read dir '{}': {e}", source_dir.display()))?;
    for entry in entries {
        let entry = entry.map_err(|e| format!("read dir entry '{}': {e}", source_dir.display()))?;
        let source_path = entry.path();
        let target_path = target_dir.join(entry.file_name());
        let file_type = entry
            .file_type()
            .map_err(|e| format!("read file type '{}': {e}", source_path.display()))?;
        if file_type.is_dir() {
            copy_dir_recursive_missing_or_newer(&source_path, &target_path)?;
        } else if file_type.is_file() {
            copy_file_if_missing_or_newer(&source_path, &target_path)?;
        }
    }
    Ok(())
}

fn merge_named_object_arrays(
    target: &mut serde_json::Map<String, JsonValue>,
    source: &serde_json::Map<String, JsonValue>,
    key: &str,
    identity_fields: &[&str],
) {
    let target_slot = target.entry(key.to_string()).or_insert_with(|| json!([]));
    if !target_slot.is_array() {
        *target_slot = json!([]);
    }
    let target_array = target_slot.as_array_mut().expect("array slot");
    let mut seen = HashSet::new();
    for item in target_array.iter() {
        if let Some(obj) = item.as_object() {
            for field in identity_fields {
                if let Some(value) = obj.get(*field).and_then(JsonValue::as_str) {
                    if !value.trim().is_empty() {
                        seen.insert(format!("{field}:{value}"));
                    }
                }
            }
        }
    }
    let Some(source_array) = source.get(key).and_then(JsonValue::as_array) else {
        return;
    };
    for item in source_array {
        let Some(obj) = item.as_object() else {
            continue;
        };
        let mut matched = false;
        for field in identity_fields {
            if let Some(value) = obj.get(*field).and_then(JsonValue::as_str) {
                let marker = format!("{field}:{value}");
                if seen.contains(&marker) {
                    matched = true;
                    break;
                }
            }
        }
        if matched {
            continue;
        }
        for field in identity_fields {
            if let Some(value) = obj.get(*field).and_then(JsonValue::as_str) {
                if !value.trim().is_empty() {
                    seen.insert(format!("{field}:{value}"));
                }
            }
        }
        target_array.push(item.clone());
    }
}

fn merge_my_atlas_file(target_path: &Path, source_path: &Path) -> Result<(), String> {
    if !source_path.exists() {
        return Ok(());
    }
    let source_bytes = std::fs::read(source_path)
        .map_err(|e| format!("read source atlas '{}': {e}", source_path.display()))?;
    let source_value = serde_json::from_slice::<JsonValue>(&source_bytes)
        .map_err(|e| format!("decode source atlas '{}': {e}", source_path.display()))?;
    let Some(source_obj) = source_value.as_object() else {
        return Ok(());
    };
    let mut target_value = if target_path.exists() {
        let target_bytes = std::fs::read(target_path)
            .map_err(|e| format!("read target atlas '{}': {e}", target_path.display()))?;
        serde_json::from_slice::<JsonValue>(&target_bytes)
            .map_err(|e| format!("decode target atlas '{}': {e}", target_path.display()))?
    } else {
        json!({
            "schema": "forge_my_atlas_v1",
            "programs": [],
            "metric_tags": [],
            "runs": []
        })
    };
    if !target_value.is_object() {
        target_value = json!({
            "schema": "forge_my_atlas_v1",
            "programs": [],
            "metric_tags": [],
            "runs": []
        });
    }
    let target_obj = target_value.as_object_mut().expect("atlas object");
    target_obj
        .entry("schema".to_string())
        .or_insert_with(|| json!("forge_my_atlas_v1"));
    merge_named_object_arrays(target_obj, source_obj, "programs", &["program_hash", "program_id", "title"]);
    merge_named_object_arrays(target_obj, source_obj, "metric_tags", &["tag", "title"]);
    merge_named_object_arrays(target_obj, source_obj, "runs", &["run_hash", "job_id", "title"]);
    if let Some(parent) = target_path.parent() {
        std::fs::create_dir_all(parent)
            .map_err(|e| format!("create atlas parent '{}': {e}", parent.display()))?;
    }
    let bytes = serde_json::to_vec_pretty(&target_value)
        .map_err(|e| format!("encode merged atlas '{}': {e}", target_path.display()))?;
    std::fs::write(target_path, bytes)
        .map_err(|e| format!("write merged atlas '{}': {e}", target_path.display()))?;
    Ok(())
}

fn migrate_legacy_forge_store_data(primary_store_path: &Path, app_data_store: Option<PathBuf>) -> Result<(), String> {
    std::fs::create_dir_all(primary_store_path)
        .map_err(|e| format!("create primary store '{}': {e}", primary_store_path.display()))?;
    let legacy_stores = collect_forge_store_candidates(primary_store_path, app_data_store);
    for legacy_store in legacy_stores {
        copy_dir_recursive_missing_or_newer(
            &legacy_store.join("programs"),
            &primary_store_path.join("programs"),
        )?;
        copy_dir_recursive_missing_or_newer(
            &legacy_store.join("jobs"),
            &primary_store_path.join("jobs"),
        )?;
        let legacy_jobs_dir = legacy_store.join("jobs");
        if legacy_jobs_dir.exists() {
            let entries = std::fs::read_dir(&legacy_jobs_dir)
                .map_err(|e| format!("read jobs dir '{}': {e}", legacy_jobs_dir.display()))?;
            for entry in entries {
                let entry = entry.map_err(|e| format!("read jobs entry '{}': {e}", legacy_jobs_dir.display()))?;
                let source_path = entry.path();
                let Some(name) = source_path.file_name() else {
                    continue;
                };
                let name = name.to_string_lossy();
                if !name.ends_with(".artifacts") {
                    continue;
                }
                copy_dir_recursive_missing_or_newer(
                    &source_path,
                    &primary_store_path.join("jobs").join(name.as_ref()),
                )?;
            }
        }
        merge_my_atlas_file(
            &primary_store_path.join("atlas").join("my_atlas.json"),
            &legacy_store.join("atlas").join("my_atlas.json"),
        )?;
    }
    Ok(())
}

#[tauri::command]
async fn pick_workspace_folder() -> Result<Option<WorkspaceFolderInfo>, String> {
    let picked = tauri::async_runtime::spawn_blocking(|| {
        rfd::FileDialog::new()
            .set_title("Choose Forge workspace")
            .set_directory(forge_workspace_dir())
            .pick_folder()
    })
    .await
    .map_err(|e| format!("workspace folder picker failed: {e}"))?;
    let info = picked.map(|p| {
        *workspace_override_lock().lock().unwrap() = Some(p.clone());
        let name = p.file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("Forge")
            .to_string();
        let reveal_label = if cfg!(windows) {
            "Show in Explorer"
        } else if cfg!(target_os = "macos") {
            "Show in Finder"
        } else {
            "Show in file manager"
        };
        WorkspaceFolderInfo {
            name,
            path: p.display().to_string(),
            reveal_label: reveal_label.to_string(),
        }
    });
    Ok(info)
}
#[tauri::command]
fn get_workspace_folder() -> WorkspaceFolderInfo {
    let path = forge_workspace_dir();
    let name = path
        .file_name()
        .and_then(|v| v.to_str())
        .unwrap_or("Forge")
        .to_string();
    let reveal_label = if cfg!(windows) {
        "Show in Explorer"
    } else if cfg!(target_os = "macos") {
        "Show in Finder"
    } else {
        "Show in file manager"
    };
    WorkspaceFolderInfo {
        name,
        path: path.display().to_string(),
        reveal_label: reveal_label.to_string(),
    }
}

#[tauri::command]
async fn reveal_workspace_folder(path: Option<String>) -> Result<(), String> {
    let folder = path
        .filter(|p| !p.trim().is_empty())
        .map(PathBuf::from)
        .unwrap_or_else(forge_workspace_dir);
    if !folder.is_dir() {
        return Err(format!("workspace folder does not exist: {}", folder.display()));
    }

    #[cfg(windows)]
    {
        std::process::Command::new("explorer")
            .arg(&folder)
            .spawn()
            .map_err(|e| format!("failed to open Explorer: {e}"))?;
    }
    #[cfg(target_os = "macos")]
    {
        std::process::Command::new("open")
            .arg(&folder)
            .spawn()
            .map_err(|e| format!("failed to open Finder: {e}"))?;
    }
    #[cfg(all(unix, not(target_os = "macos")))]
    {
        std::process::Command::new("xdg-open")
            .arg(&folder)
            .spawn()
            .map_err(|e| format!("failed to open file manager: {e}"))?;
    }
    Ok(())
}

/// Attempts a runtime switch to the WGPU backend. If wgpu wasn't compiled
/// into this Forge binary (current default for the Tauri example because
/// of an upstream wgpu-hal compile issue), returns a "needs-rebuild" status
/// with the exact cargo command the user has to run.
#[tauri::command]
async fn try_switch_to_wgpu() -> Result<WgpuSwitchResult, String> {
    if cfg!(feature = "wgpu") {
        // Both backends compiled in: would need a runtime config flag here
        // to actually re-route eval_batch through the WGPU code path. For
        // now we report success — the cascade in gpunode.rs already prefers
        // CUDA → WGPU → CPU, so disabling CUDA at runtime would suffice.
        Ok(WgpuSwitchResult {
            status: "available".to_string(),
            message: "WGPU is compiled in. Set FORGE_CUDA=0 in your environment and restart Forge \
                      to route GPU work through WGPU instead of CUDA."
                .to_string(),
            rebuild_command: None,
        })
    } else {
        Ok(WgpuSwitchResult {
            status: "needs-rebuild".to_string(),
            message: "WGPU is not compiled into this Forge build. To switch backend, you need to \
                      rebuild Forge with the wgpu feature flag. Run the command below in a terminal \
                      from examples/forge_tauri_ui/src-tauri, then restart the app."
                .to_string(),
            rebuild_command: Some(
                "cargo tauri dev --features wgpu --no-default-features".to_string(),
            ),
        })
    }
}

#[tauri::command]
async fn list_programs(
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<Vec<String>, String> {
    let mut app_state = state.lock().map_err(|e| e.to_string())?;
    let backend = app_state.backend_mut()?;
    let mut names: Vec<String> = backend.programs.keys().map(|k| k.to_string()).collect();
    names.sort();
    Ok(names)
}

#[tauri::command]
async fn prepare_alpha_backend(
    state: tauri::State<'_, Mutex<ForgeAppState>>,
    app: tauri::AppHandle,
) -> Result<BackendReadyReport, String> {
    alpha_trace(&app, "backend", "prepare_alpha_backend.enter");
    emit_alpha_log(
        &app,
        "[start-prof] preparing compute backend (Store + Atlas) before Start...".to_string(),
    );
    let report = ensure_backend_ready(&state, &app, "prepare_alpha_backend")?;
    emit_alpha_log(
        &app,
        format!(
            "[start-prof] compute backend ready open={}ms wait={}ms already_ready={}",
            report.open_ms, report.wait_ms, report.already_ready
        ),
    );
    alpha_trace(
        &app,
        "backend",
        format!(
            "prepare_alpha_backend.done open_ms={} wait_ms={} already_ready={}",
            report.open_ms, report.wait_ms, report.already_ready
        ),
    );
    Ok(report)
}

// ─── inspect_program_map ────────────────────────────────────────────────────
//
// Unified preview command. Called by the frontend when the user has selected
// a program (and optionally uploaded a file). Returns the same metrics that
// `start_computation` would compute — built from a real ComputationPlan when
// `bytes` is provided, structural analysis only otherwise. No estimates,
// no hardcoded constants : every number is measured.

#[derive(Serialize, Deserialize, Clone)]
struct ComputationPlanReport {
    kind: String,
    /// Static program analysis (always populated for stored programs).
    node_count: usize,
    opcodes: Vec<String>,
    recurring_ops: Vec<String>,
    cse_canonical_hash: String,
    /// nodes(before CSE) - nodes(after CSE). >0 = CSE merges duplicates.
    cse_node_delta: i32,
    /// Plan metrics (populated only when `bytes` is provided).
    /// `None` = no file given, so no measurement.
    plan: Option<PlanMetrics>,
    /// Operational pre-start manifest for alpha synth: which layers are
    /// already materialized, which Atlas keyspaces are expected, and what
    /// remains deferred until Start.
    alpha_manifest: Option<AlphaPrestartManifest>,
}

#[derive(Serialize, Deserialize, Clone)]
struct PlanMetrics {
    /// Raw planned calls before any dedup.
    total_planned: usize,
    /// Unique after FNV-1a (func || args) dedup.
    unique_after_fnv: usize,
    input_dedup_pct: f64,
    /// Distinct func hashes referenced in the plan.
    distinct_programs: usize,
    /// Equivalence classes after cse() + semantic_fingerprint.
    n_cse_classes: usize,
    /// Calls already known by MonsterNode's RAM cache (atlas peek hits).
    atlas_hits: usize,
    atlas_hit_pct: f64,
    /// Calls whose result is already persisted in `forge.atlas` from a
    /// prior session — MonsterNode dispatch will short-circuit them.
    atlas_result_hits: usize,
    atlas_result_pct: f64,
    /// Calls that need real computation = unique − (brain ∪ atlas RESULT).
    truly_novel: usize,
}

#[derive(Clone)]
struct AlphaPrestartCache {
    manifest: AlphaPrestartManifest,
    bars: std::sync::Arc<Vec<synth_strategy::Bar>>,
    raw_feature_cache: std::sync::Arc<Vec<Option<[i64; synth_strategy::BASE_FEATURE_COUNT]>>>,
}

#[derive(Serialize, Deserialize, Clone)]
struct AlphaPrestartManifest {
    file_hash: u64,
    bars_total: usize,
    min_history_bar: usize,
    raw_feature_rows_ready: usize,
    raw_feature_rows_missing: usize,
    raw_feature_scalars_expected: usize,
    layers_ready: Vec<String>,
    layers_deferred_to_start: Vec<String>,
    atlas_keyspaces: Vec<String>,
}

#[derive(Clone)]
struct AlphaStartExecutionPlan {
    parsed_bars_from_prestart: bool,
    raw_cache_source: &'static str,
    raw_rows_ready: usize,
    raw_rows_missing: usize,
    refresh_prestart_after_raw_fill: bool,
    labels_source: &'static str,
    stage1_predictions_source: &'static str,
    confluence_source: &'static str,
    stage2_predictions_source: &'static str,
}

fn write_u16(out: &mut Vec<u8>, value: u16) {
    out.extend_from_slice(&value.to_le_bytes());
}

fn write_string(out: &mut Vec<u8>, value: &str) {
    let bytes = value.as_bytes();
    write_u16(out, bytes.len().min(u16::MAX as usize) as u16);
    out.extend_from_slice(&bytes[..bytes.len().min(u16::MAX as usize)]);
}

fn read_u16(bytes: &[u8], cursor: &mut usize) -> Result<u16, String> {
    let mut raw = [0u8; 2];
    raw.copy_from_slice(read_exact(bytes, cursor, 2)?);
    Ok(u16::from_le_bytes(raw))
}

fn read_string(bytes: &[u8], cursor: &mut usize) -> Result<String, String> {
    let len = read_u16(bytes, cursor)? as usize;
    let raw = read_exact(bytes, cursor, len)?;
    std::str::from_utf8(raw)
        .map(|s| s.to_string())
        .map_err(|e| format!("alpha pre-start artifact invalid utf8: {e}"))
}

fn build_alpha_prestart_manifest(
    file_hash: u64,
    bars: &[synth_strategy::Bar],
    raw_feature_cache: &[Option<[i64; synth_strategy::BASE_FEATURE_COUNT]>],
) -> AlphaPrestartManifest {
    let expected_start = synth_strategy::MIN_HISTORY.min(raw_feature_cache.len());
    let expected_end = bars.len().saturating_sub(1);
    let raw_feature_rows_ready = raw_feature_cache[expected_start..expected_end]
        .iter()
        .filter(|row| row.is_some())
        .count();
    let raw_feature_rows_missing = 0usize;
    let raw_feature_scalars_expected = raw_feature_rows_ready * synth_strategy::BASE_FEATURE_COUNT;
    AlphaPrestartManifest {
        file_hash,
        bars_total: bars.len(),
        min_history_bar: synth_strategy::MIN_HISTORY,
        raw_feature_rows_ready,
        raw_feature_rows_missing,
        raw_feature_scalars_expected,
        layers_ready: vec![
            "bars(parsed_csv)".to_string(),
            "raw_features_vwap(base_feature_rows)".to_string(),
            "alpha_prestart_artifact(store+atlas)".to_string(),
        ],
        layers_deferred_to_start: vec![
            "binary_labels(file_hash,sl,tp,spread,horizon)".to_string(),
            "stage1_predictions(file_hash,program_hash,bar)".to_string(),
            "confluence_rows(file_hash,modelset_fp,feature_id,bar)".to_string(),
            "stage2_predictions(file_hash,program_hash,bar)".to_string(),
            "alpha_selection(file_hash,request_fp)".to_string(),
        ],
        atlas_keyspaces: vec![
            "alpha_prestart[file_hash]".to_string(),
            format!(
                "feature[file_hash,feature_id:0..{},bar:min_history..last]",
                synth_strategy::BASE_FEATURE_COUNT.saturating_sub(1)
            ),
            "label[file_hash,bar,sl,tp,spread,horizon]".to_string(),
            "prediction[file_hash,program_hash,bar]".to_string(),
            "confluence_feature[file_hash,modelset_fp,feature_id,bar]".to_string(),
            "alpha_selection[file_hash,request_fp]".to_string(),
        ],
    }
}

fn log_alpha_prestart_manifest<F: FnMut(String)>(manifest: &AlphaPrestartManifest, mut emit: F) {
    emit(format!(
        "pre-start manifest : bars={} | raw rows ready={} | missing={} | expected raw scalars={}",
        manifest.bars_total,
        manifest.raw_feature_rows_ready,
        manifest.raw_feature_rows_missing,
        manifest.raw_feature_scalars_expected
    ));
    emit(format!(
        "  ready layers : {}",
        manifest.layers_ready.join(" | ")
    ));
    emit(format!(
        "  deferred to Start : {}",
        manifest.layers_deferred_to_start.join(" | ")
    ));
    emit(format!(
        "  atlas keyspaces : {}",
        manifest.atlas_keyspaces.join(" | ")
    ));
}

fn build_alpha_start_execution_plan(
    prestart: Option<&AlphaPrestartCache>,
    total_bars: usize,
) -> AlphaStartExecutionPlan {
    match prestart {
        Some(prestart) => AlphaStartExecutionPlan {
            parsed_bars_from_prestart: true,
            raw_cache_source: if prestart.manifest.raw_feature_rows_missing == 0 {
                "manifest-ready"
            } else {
                "manifest+atlas-misses"
            },
            raw_rows_ready: prestart.manifest.raw_feature_rows_ready,
            raw_rows_missing: prestart.manifest.raw_feature_rows_missing,
            refresh_prestart_after_raw_fill: prestart.manifest.raw_feature_rows_missing > 0,
            labels_source: "atlas-first/misses-only",
            stage1_predictions_source: "atlas-first/misses-only",
            confluence_source: "atlas-first/misses-only",
            stage2_predictions_source: "atlas-first/misses-only",
        },
        None => AlphaStartExecutionPlan {
            parsed_bars_from_prestart: false,
            raw_cache_source: "atlas-first/full-scan-on-miss",
            raw_rows_ready: 0,
            raw_rows_missing: total_bars.saturating_sub(synth_strategy::MIN_HISTORY),
            refresh_prestart_after_raw_fill: true,
            labels_source: "atlas-first/misses-only",
            stage1_predictions_source: "atlas-first/misses-only",
            confluence_source: "atlas-first/misses-only",
            stage2_predictions_source: "atlas-first/misses-only",
        },
    }
}

fn log_alpha_start_execution_plan<F: FnMut(String)>(plan: &AlphaStartExecutionPlan, mut emit: F) {
    emit(format!(
        "start plan : bars={} | raw={} | raw ready={} | raw missing={} | refresh_prestart={}",
        if plan.parsed_bars_from_prestart {
            "prestart"
        } else {
            "csv-parse"
        },
        plan.raw_cache_source,
        plan.raw_rows_ready,
        plan.raw_rows_missing,
        plan.refresh_prestart_after_raw_fill
    ));
    emit(format!(
        "  deferred execution policy : labels={} | stage1_preds={} | confluence={} | stage2_preds={}",
        plan.labels_source,
        plan.stage1_predictions_source,
        plan.confluence_source,
        plan.stage2_predictions_source
    ));
}

fn avoided_pct(avoided: usize, recomputed: usize) -> f64 {
    let total = avoided + recomputed;
    if total == 0 {
        0.0
    } else {
        100.0 * avoided as f64 / total as f64
    }
}

fn build_alpha_prestart_artifact(
    file_hash: u64,
    bars: &[synth_strategy::Bar],
    raw_feature_cache: &[Option<[i64; synth_strategy::BASE_FEATURE_COUNT]>],
) -> Vec<u8> {
    let manifest = build_alpha_prestart_manifest(file_hash, bars, raw_feature_cache);
    let mut out = Vec::with_capacity(16 + bars.len() * (48 + 1 + 8 * synth_strategy::BASE_FEATURE_COUNT));
    out.extend_from_slice(b"ALPHAPRE2");
    out.extend_from_slice(&file_hash.to_le_bytes());
    out.extend_from_slice(&(bars.len() as u32).to_le_bytes());
    out.extend_from_slice(&(manifest.raw_feature_rows_ready as u32).to_le_bytes());
    out.extend_from_slice(&(manifest.raw_feature_rows_missing as u32).to_le_bytes());
    out.extend_from_slice(&(manifest.raw_feature_scalars_expected as u32).to_le_bytes());
    write_u16(&mut out, manifest.layers_ready.len() as u16);
    for item in &manifest.layers_ready {
        write_string(&mut out, item);
    }
    write_u16(&mut out, manifest.layers_deferred_to_start.len() as u16);
    for item in &manifest.layers_deferred_to_start {
        write_string(&mut out, item);
    }
    write_u16(&mut out, manifest.atlas_keyspaces.len() as u16);
    for item in &manifest.atlas_keyspaces {
        write_string(&mut out, item);
    }
    for bar in bars {
        out.extend_from_slice(&bar.time_ms.to_le_bytes());
        out.extend_from_slice(&bar.open.to_le_bytes());
        out.extend_from_slice(&bar.high.to_le_bytes());
        out.extend_from_slice(&bar.low.to_le_bytes());
        out.extend_from_slice(&bar.close.to_le_bytes());
        out.extend_from_slice(&bar.volume.to_le_bytes());
    }
    for row in raw_feature_cache {
        match row {
            Some(values) => {
                out.push(1);
                for value in values {
                    out.extend_from_slice(&value.to_le_bytes());
                }
            }
            None => out.push(0),
        }
    }
    out
}

fn read_exact<'a>(bytes: &'a [u8], cursor: &mut usize, n: usize) -> Result<&'a [u8], String> {
    if bytes.len().saturating_sub(*cursor) < n {
        return Err("alpha pre-start artifact truncated".to_string());
    }
    let start = *cursor;
    *cursor += n;
    Ok(&bytes[start..start + n])
}

fn read_u32(bytes: &[u8], cursor: &mut usize) -> Result<u32, String> {
    let mut raw = [0u8; 4];
    raw.copy_from_slice(read_exact(bytes, cursor, 4)?);
    Ok(u32::from_le_bytes(raw))
}

fn read_u64(bytes: &[u8], cursor: &mut usize) -> Result<u64, String> {
    let mut raw = [0u8; 8];
    raw.copy_from_slice(read_exact(bytes, cursor, 8)?);
    Ok(u64::from_le_bytes(raw))
}

fn read_i64(bytes: &[u8], cursor: &mut usize) -> Result<i64, String> {
    let mut raw = [0u8; 8];
    raw.copy_from_slice(read_exact(bytes, cursor, 8)?);
    Ok(i64::from_le_bytes(raw))
}

fn read_f64(bytes: &[u8], cursor: &mut usize) -> Result<f64, String> {
    let mut raw = [0u8; 8];
    raw.copy_from_slice(read_exact(bytes, cursor, 8)?);
    Ok(f64::from_le_bytes(raw))
}

fn decode_alpha_prestart_artifact(bytes: &[u8]) -> Result<AlphaPrestartCache, String> {
    if !bytes.starts_with(b"ALPHAPRE2") {
        return Err("alpha pre-start artifact magic mismatch".to_string());
    }
    let mut cursor = 9;
    let file_hash = read_u64(bytes, &mut cursor)?;
    let n_bars = read_u32(bytes, &mut cursor)? as usize;
    let raw_feature_rows_ready = read_u32(bytes, &mut cursor)? as usize;
    let raw_feature_rows_missing = read_u32(bytes, &mut cursor)? as usize;
    let raw_feature_scalars_expected = read_u32(bytes, &mut cursor)? as usize;
    let ready_len = read_u16(bytes, &mut cursor)? as usize;
    let mut layers_ready = Vec::with_capacity(ready_len);
    for _ in 0..ready_len {
        layers_ready.push(read_string(bytes, &mut cursor)?);
    }
    let deferred_len = read_u16(bytes, &mut cursor)? as usize;
    let mut layers_deferred_to_start = Vec::with_capacity(deferred_len);
    for _ in 0..deferred_len {
        layers_deferred_to_start.push(read_string(bytes, &mut cursor)?);
    }
    let keyspaces_len = read_u16(bytes, &mut cursor)? as usize;
    let mut atlas_keyspaces = Vec::with_capacity(keyspaces_len);
    for _ in 0..keyspaces_len {
        atlas_keyspaces.push(read_string(bytes, &mut cursor)?);
    }
    let mut bars = Vec::with_capacity(n_bars);
    for _ in 0..n_bars {
        bars.push(synth_strategy::Bar {
            time_ms: read_i64(bytes, &mut cursor)?,
            open: read_f64(bytes, &mut cursor)?,
            high: read_f64(bytes, &mut cursor)?,
            low: read_f64(bytes, &mut cursor)?,
            close: read_f64(bytes, &mut cursor)?,
            volume: read_f64(bytes, &mut cursor)?,
        });
    }
    let mut raw_feature_cache = Vec::with_capacity(n_bars);
    for _ in 0..n_bars {
        let present = read_exact(bytes, &mut cursor, 1)?[0] != 0;
        if present {
            let mut row = [0i64; synth_strategy::BASE_FEATURE_COUNT];
            for value in &mut row {
                *value = read_i64(bytes, &mut cursor)?;
            }
            raw_feature_cache.push(Some(row));
        } else {
            raw_feature_cache.push(None);
        }
    }
    Ok(AlphaPrestartCache {
        manifest: AlphaPrestartManifest {
            file_hash,
            bars_total: n_bars,
            min_history_bar: synth_strategy::MIN_HISTORY,
            raw_feature_rows_ready,
            raw_feature_rows_missing,
            raw_feature_scalars_expected,
            layers_ready,
            layers_deferred_to_start,
            atlas_keyspaces,
        },
        bars: std::sync::Arc::new(bars),
        raw_feature_cache: std::sync::Arc::new(raw_feature_cache),
    })
}

fn load_alpha_prestart_from_store(
    backend: &ForgeBackend,
    file_hash: u64,
) -> Result<Option<AlphaPrestartCache>, String> {
    let key = scan::atlas::Atlas::alpha_prestart_key(file_hash);
    let Some(blob_hash) = backend.atlas.lookup_result(&key) else {
        return Ok(None);
    };
    let blob_hash = Hash::from_bytes(blob_hash);
    let Some(bytes) = backend.node.store().load(&blob_hash) else {
        return Ok(None);
    };
    match decode_alpha_prestart_artifact(&bytes) {
        Ok(cache) => Ok(Some(cache)),
        Err(_) => Ok(None),
    }
}

fn ensure_alpha_prestart_from_bytes(
    backend: &ForgeBackend,
    file_hash: u64,
    bytes: &[u8],
) -> Result<Option<AlphaPrestartCache>, String> {
    if let Some(prestart) = load_alpha_prestart_from_store(backend, file_hash)? {
        return Ok(Some(prestart));
    }
    let bars = std::sync::Arc::new(
        synth_strategy::parse_csv(bytes)
            .map_err(|e| format!("parse alpha pre-start CSV: {e}"))?,
    );
    let raw_feature_cache = std::sync::Arc::new(
        synth_strategy::build_raw_feature_cache_with_atlas(
            bars.as_slice(),
            synth_strategy::MIN_HISTORY..bars.len(),
            &backend.atlas,
            file_hash,
        )
        .0,
    );
    persist_alpha_prestart_to_store(
        backend,
        file_hash,
        bars.as_slice(),
        raw_feature_cache.as_slice(),
    )?;
    let manifest = build_alpha_prestart_manifest(file_hash, bars.as_slice(), raw_feature_cache.as_slice());
    Ok(Some(AlphaPrestartCache {
        manifest,
        bars,
        raw_feature_cache,
    }))
}

fn persist_alpha_prestart_to_store(
    backend: &ForgeBackend,
    file_hash: u64,
    bars: &[synth_strategy::Bar],
    raw_feature_cache: &[Option<[i64; synth_strategy::BASE_FEATURE_COUNT]>],
) -> Result<bool, String> {
    let artifact = build_alpha_prestart_artifact(file_hash, bars, raw_feature_cache);
    let blob_hash = backend
        .node
        .store()
        .store(&artifact)
        .map_err(|e| format!("store alpha pre-start artifact: {e}"))?;
    let inserted = backend
        .atlas
        .record_result(&scan::atlas::Atlas::alpha_prestart_key(file_hash), blob_hash.as_bytes())
        .map_err(|e| format!("atlas alpha pre-start artifact: {e}"))?;
    backend
        .atlas
        .flush()
        .map_err(|e| format!("flush alpha pre-start artifact: {e}"))?;
    Ok(inserted)
}

fn load_alpha_inspect_report_from_store(
    backend: &ForgeBackend,
    file_hash: u64,
) -> Result<Option<ComputationPlanReport>, String> {
    let key = scan::atlas::Atlas::alpha_inspect_key(file_hash);
    let Some(blob_hash) = backend.atlas.lookup_result(&key) else {
        return Ok(None);
    };
    let blob_hash = Hash::from_bytes(blob_hash);
    let Some(bytes) = backend.node.store().load(&blob_hash) else {
        return Ok(None);
    };
    serde_json::from_slice::<ComputationPlanReport>(&bytes)
        .map(Some)
        .map_err(|e| format!("decode alpha inspect report: {e}"))
}

fn persist_alpha_inspect_report_to_store(
    backend: &ForgeBackend,
    file_hash: u64,
    report: &ComputationPlanReport,
) -> Result<bool, String> {
    let artifact = serde_json::to_vec(report)
        .map_err(|e| format!("encode alpha inspect report: {e}"))?;
    let blob_hash = backend
        .node
        .store()
        .store(&artifact)
        .map_err(|e| format!("store alpha inspect report: {e}"))?;
    let inserted = backend
        .atlas
        .record_result(&scan::atlas::Atlas::alpha_inspect_key(file_hash), blob_hash.as_bytes())
        .map_err(|e| format!("atlas alpha inspect report: {e}"))?;
    backend
        .atlas
        .flush()
        .map_err(|e| format!("flush alpha inspect report: {e}"))?;
    Ok(inserted)
}

fn alpha_inspect_report_sidecar_path(store_path: &std::path::Path, file_hash: u64) -> PathBuf {
    store_path
        .join("alpha-inspect-cache")
        .join(format!("{file_hash:016x}.json"))
}

fn load_alpha_inspect_report_sidecar(
    store_path: &std::path::Path,
    file_hash: u64,
) -> Result<Option<ComputationPlanReport>, String> {
    let path = alpha_inspect_report_sidecar_path(store_path, file_hash);
    let bytes = match std::fs::read(&path) {
        Ok(bytes) => bytes,
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(err) => return Err(format!("read alpha inspect sidecar: {err}")),
    };
    serde_json::from_slice::<ComputationPlanReport>(&bytes)
        .map(Some)
        .map_err(|e| format!("decode alpha inspect sidecar: {e}"))
}

fn persist_alpha_inspect_report_sidecar(
    store_path: &std::path::Path,
    file_hash: u64,
    report: &ComputationPlanReport,
) -> Result<(), String> {
    let path = alpha_inspect_report_sidecar_path(store_path, file_hash);
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)
            .map_err(|e| format!("create alpha inspect sidecar dir: {e}"))?;
    }
    let bytes = serde_json::to_vec(report)
        .map_err(|e| format!("encode alpha inspect sidecar: {e}"))?;
    let tmp_path = path.with_extension("json.tmp");
    std::fs::write(&tmp_path, &bytes)
        .map_err(|e| format!("write alpha inspect sidecar tmp: {e}"))?;
    std::fs::rename(&tmp_path, &path)
        .map_err(|e| format!("commit alpha inspect sidecar: {e}"))?;
    Ok(())
}

fn with_cached_inspect_elapsed(mut report: ComputationPlanReport, cached_label: &str) -> ComputationPlanReport {
    report
        .recurring_ops
        .retain(|line| !line.starts_with("inspect elapsed :"));
    report.recurring_ops.push(format!(
        "inspect elapsed : 0 ms ({cached_label})"
    ));
    report
}

#[tauri::command]
async fn inspect_program_map(
    kind: String,
    bytes: Option<Vec<u8>>,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
    app: tauri::AppHandle,
) -> Result<ComputationPlanReport, String> {
    let inspect_t0 = Instant::now();
    let file_hash = bytes.as_ref().map(|b| quick_file_hash(b));
    alpha_trace(
        &app,
        "backend",
        format!(
            "inspect.enter kind={} bytes={} file_hash={}",
            kind,
            bytes.as_ref().map(|b| b.len()).unwrap_or(0),
            file_hash
                .map(|v| v.to_string())
                .unwrap_or_else(|| "<none>".to_string())
        ),
    );
    let store_path = {
        let app_state = state.lock().map_err(|e| e.to_string())?;
        app_state.store_path.clone()
    };
    if kind == "reverse_synth_alpha" {
        if let Some(fh) = file_hash {
            if let Some(cached) = load_alpha_inspect_report_sidecar(&store_path, fh)? {
                alpha_trace(
                    &app,
                    "backend",
                    format!("inspect.cache_hit sidecar-before-backend file_hash={fh}"),
                );
                return Ok(with_cached_inspect_elapsed(
                    cached,
                    "persisted disk cache hit before backend open",
                ));
            }
        }
    }

    let mut app_state = state.lock().map_err(|e| e.to_string())?;
    let backend = app_state.backend_mut()?;
    alpha_trace(&app, "backend", "inspect.backend_ready");
    if kind == "reverse_synth_alpha" {
        if let (Some(fh), Some(raw)) = (file_hash, bytes.as_ref()) {
            alpha_trace(
                &app,
                "backend",
                format!("inspect.prestart_ensure.begin file_hash={fh} bytes={}", raw.len()),
            );
            let _ = ensure_alpha_prestart_from_bytes(&backend, fh, raw)?;
            alpha_trace(
                &app,
                "backend",
                format!("inspect.prestart_ensure.done file_hash={fh}"),
            );
        }
    }
    // Fast-path : if the same (kind, file_hash) was inspected earlier in
    // this process, return the cached report. The analysis is deterministic
    // given those two inputs — recomputing is pure waste.
    if let Some(fh) = file_hash {
        if let Some(cached) = backend.inspect_cache.get(&(kind.clone(), fh)) {
            alpha_trace(
                &app,
                "backend",
                format!("inspect.cache_hit memory file_hash={fh}"),
            );
            if kind == "reverse_synth_alpha" {
                if let Err(err) = persist_alpha_inspect_report_sidecar(&store_path, fh, cached) {
                    alpha_trace(
                        &app,
                        "backend",
                        format!("inspect.sidecar.persist_after_memory_hit.error file_hash={fh} err={err}"),
                    );
                }
            }
            return Ok(with_cached_inspect_elapsed(
                cached.clone(),
                "in-process cache hit for same file",
            ));
        }
        if kind == "reverse_synth_alpha" {
            if let Some(cached) = load_alpha_inspect_report_from_store(&backend, fh)? {
                alpha_trace(
                    &app,
                    "backend",
                    format!("inspect.cache_hit atlas file_hash={fh}"),
                );
                if let Err(err) = persist_alpha_inspect_report_sidecar(&store_path, fh, &cached) {
                    alpha_trace(
                        &app,
                        "backend",
                        format!("inspect.sidecar.persist_after_atlas_hit.error file_hash={fh} err={err}"),
                    );
                }
                backend
                    .inspect_cache
                    .insert((kind.clone(), fh), cached.clone());
                return Ok(with_cached_inspect_elapsed(
                    cached,
                    "persisted atlas cache hit for same file",
                ));
            }
        }
    }

    // ── Branch A : reverse_synth — no stored program yet ──
    // With bytes we measure (1) feature-vector dedup and (2) the depth-2
    // candidate space CSE-collapse ratio. Without bytes, just declare the
    // opcode space the beam will explore.
    if kind.starts_with("reverse_synth_") {
        let opcodes = vec!["Add", "Sub", "Mul", "BitXor", "BitAnd", "BitOr"]
            .into_iter()
            .map(String::from)
            .collect();
        let mut recurring_ops = Vec::new();
        let alpha_prestart = if kind == "reverse_synth_alpha" {
            bytes.as_ref().and_then(|b| {
                let fh = quick_file_hash(b);
                ensure_alpha_prestart_from_bytes(&backend, fh, b).ok().flatten()
            })
        } else {
            None
        };
        if let Some(prestart) = alpha_prestart.as_ref() {
            log_alpha_prestart_manifest(&prestart.manifest, |line| recurring_ops.push(line));
        }
        let plan = bytes.as_ref().and_then(|b| {
            let parsed_bars = if alpha_prestart.is_some() {
                None
            } else {
                Some(synth_strategy::parse_csv(b).ok()?)
            };
            let bars = parsed_bars
                .as_deref()
                .unwrap_or_else(|| alpha_prestart.as_ref().unwrap().bars.as_slice());
            let cfg = synth_strategy::SynthConfig::default();
            let examples = synth_strategy::build_examples_in_range(
                bars,
                synth_strategy::MIN_HISTORY..bars.len(),
                cfg,
            );
            if examples.is_empty() {
                return None;
            }
            // Feature-vector input dedup.
            let total = examples.len();
            let mut seen: HashMap<i64, ()> = HashMap::with_capacity(total / 2);
            for (input, _) in &examples {
                seen.insert(*input, ());
            }
            let unique = seen.len();
            let pct = 100.0 * (total - unique) as f64 / total as f64;

            // Meta-fractal: enumerate the depth-2 + depth-3 synth candidate
            // space and group by CSE+semantic_fingerprint. The class-count is
            // the real count of distinct programs the beam would actually score.
            let mut candidates = enumerate_synth_candidates_d2(&examples);
            let d2_raw = candidates.len();
            candidates.extend(enumerate_synth_candidates_d3(&examples));
            let cse = cse_classify_candidates_with_reps(&candidates);
            let raw = cse.raw;
            let classes = cse.n_classes;
            let redundancy = cse.redundancy_pct;
            // Record CSE fingerprints into the unified atlas BEFORE filtering
            // so the atlas tracks the full equivalence classes. Cross-run
            // counter : how many of THIS run's classes were already seen.
            let cse_prior = cse
                .fingerprints
                .iter()
                .filter(|fp| {
                    backend
                        .atlas
                        .record(scan::atlas::kind::CSE, fp)
                        .map(|new| !new)
                        .unwrap_or(false)
                })
                .count();

            // Effective candidate space the synth would actually score:
            // drop provably-constant classes (synth simplify discards them).
            let live_after_static = cse.live_reps.len();
            recurring_ops.push(format!(
                "candidate space d2+d3: {raw} raw ({d2_raw} d2 + {} d3) -> {classes} CSE classes ({redundancy:.1}% redundancy, {} provably-constant SKIPPED, {} already known by atlas -> {} live reps)",
                raw - d2_raw,
                cse.static_count,
                cse_prior,
                live_after_static
            ));

            recurring_ops.push("runtime atlas filter at Start: full pair bundles + per-opcode memo are applied again before GPU dispatch (only true misses become GPU jobs)".to_string());
            recurring_ops.push("alpha pre-start persists raw VWAP feature scalars into Atlas so Start can rehydrate the mapping cross-session".to_string());
            // Sub-tree mining: skip heavy mining when atlas already has a
            // substantial subtree count from prior sessions — the metric
            // is dominated by the atlas count anyway, re-mining it costs
            // ~2 s for ~3 k unique fingerprints we already know about.
            const SUBTREE_WARM_THRESHOLD: usize = 1000;
            let prior_subtree_count = backend.atlas.count_kind(scan::atlas::kind::SUBTREE);
            if prior_subtree_count >= SUBTREE_WARM_THRESHOLD {
                recurring_ops.push(format!(
                    "sub-tree mining: SKIPPED (atlas warm, {} unique sub-trees already known)",
                    prior_subtree_count
                ));
            } else {
                let sub = analyze_subtree_redundancy(&candidates);
                let sub_prior = sub
                    .fingerprints
                    .iter()
                    .filter(|fp| {
                        backend
                            .atlas
                            .record(scan::atlas::kind::SUBTREE, fp)
                            .map(|new| !new)
                            .unwrap_or(false)
                    })
                    .count();
                recurring_ops.push(format!(
                    "sub-tree mining: {} sub-evaluations -> {} unique sub-trees ({:.1}% sub-level redundancy, {} already known by atlas)",
                    sub.total_subtrees, sub.unique_subtrees, sub.redundancy_pct, sub_prior
                ));
            }

            // Sub-window mining: feature extraction itself is the lowest
            // level we can mine without touching synth_strategy.rs internals.
            // 7 windowed features per bar × bars naïve vs sliding-window O(1).
            let win = analyze_subwindow_redundancy(bars.len());
            recurring_ops.push(format!(
                "sub-window mining (feature extraction over {} bars): {} naive ops -> {} sliding-window ({:.1}% redundancy)",
                win.bar_count,
                fmt_ops(win.total_naive_ops),
                fmt_ops(win.total_sliding_ops),
                win.redundancy_pct
            ));
            for (name, naive_ops, sliding_ops, pct) in &win.per_feature {
                recurring_ops.push(format!(
                    "    {name:<10} : {} naive -> {} sliding ({pct:.1}%)",
                    fmt_ops(*naive_ops),
                    fmt_ops(*sliding_ops)
                ));
            }

            // Sample of unique feature inputs (used both by trace classifier
            // and atlas peek). Bounded to 64 to keep the command under
            // ~200 ms even on cold caches.
            let unique_inputs: Vec<i64> = {
                let mut s: HashMap<i64, ()> = HashMap::new();
                for (i, _) in &examples {
                    s.insert(*i, ());
                    if s.len() >= 64 {
                        break;
                    }
                }
                s.into_keys().collect()
            };

            // Trace-equivalence: stricter than CSE, runs each LIVE rep on
            // the user's real sample inputs and groups by output trace hash.
            // We deliberately skip the static-output reps — they all collapse
            // to the same constant trace and would inflate the redundancy
            // numbers without telling us anything we don't already know.
            let trace = trace_classify_reps(&cse.live_reps, &unique_inputs, 32);
            let trace_prior = trace
                .fingerprints
                .iter()
                .filter(|h| {
                    let padded = scan::atlas::Atlas::pad_u64(**h);
                    backend
                        .atlas
                        .record(scan::atlas::kind::TRACE, &padded)
                        .map(|new| !new)
                        .unwrap_or(false)
                })
                .count();
            let trace_extra = classes.saturating_sub(trace.n_trace_classes);
            let trace_redundancy = if classes > 0 {
                100.0 * trace_extra as f64 / classes as f64
            } else {
                0.0
            };
            recurring_ops.push(format!(
                "trace classes (data-equivalent over {} sample inputs): {} (vs {} CSE classes - {} extra collapses, +{:.1}%, {} already known)",
                unique_inputs.len().min(32),
                trace.n_trace_classes,
                classes,
                trace_extra,
                trace_redundancy,
                trace_prior
            ));
            recurring_ops.push(format!(
                "  degenerate candidates: {} tautological (constant output) | {} identity (output=input) | top trace class: {} members",
                trace.tautological, trace.identity, trace.top_class_size
            ));

            // Atlas warm-up: skip the 8 192-call peek sweep when the atlas
            // already has enough PEEK entries from prior sessions. The
            // peek loop costs ~150 ms; replaying the count from atlas is
            // free.
            const PEEK_WARM_THRESHOLD: usize = 4000;
            let prior_peek_count = backend.atlas.count_kind(scan::atlas::kind::PEEK);
            let (_, peek_hits, peek_pct) = if prior_peek_count >= PEEK_WARM_THRESHOLD {
                recurring_ops.push(format!(
                    "atlas peek: SKIPPED (atlas warm, {} peek pairs already known)",
                    prior_peek_count
                ));
                // Surface the persisted PEEK count as the hit count so
                // downstream metrics still reflect the cumulative state.
                (prior_peek_count, prior_peek_count, 100.0)
            } else {
                let (t, h, p) = synth_atlas_warm_estimate(
                    &backend.node,
                    &cse.live_reps,
                    &unique_inputs,
                    256,
                    32,
                );
                if t > 0 {
                    recurring_ops.push(format!(
                        "atlas peek: {h}/{t} (program x input) pairs resolvable without interpreter ({p:.1}%)"
                    ));
                }
                (t, h, p)
            };

            // Atlas summary line — total persisted hashes across all
            // sessions for this Forge install. Crosses CSE/trace/subtree/peek.
            recurring_ops.push(format!(
                "atlas total : {} hashes persisted ({} CSE + {} trace + {} subtree + {} peek) -> {}",
                backend.atlas.total(),
                backend.atlas.count_kind(scan::atlas::kind::CSE),
                backend.atlas.count_kind(scan::atlas::kind::TRACE),
                backend.atlas.count_kind(scan::atlas::kind::SUBTREE),
                backend.atlas.count_kind(scan::atlas::kind::PEEK),
                backend.atlas.path().display()
            ));

            // RESULT persistence: actual computed values memoized across sessions.
            // Distinct from structural hashes — these are real output values written
            // during previous Start runs (train scores, opmemo, dispatch results).
            let result_persisted = backend.atlas.count_kind(scan::atlas::kind::RESULT);
            recurring_ops.push(format!(
                "atlas RESULT cross-sessions : {} persisted computed results -> reused automatically on next Start without recompute",
                result_persisted
            ));

            // Routing preview: inspect candidates (d2/d3) are ≤12 nodes but
            // the beam search scoring path uses gpu_synth::score_batch_gpu
            // which splits across CUDA + WGPU when pairs ≥ 32 and n_examples ≥ 1000.
            let gpu_mode = if cfg!(all(feature = "cuda", feature = "wgpu")) {
                "DUAL-GPU (CUDA + WGPU split)"
            } else if cfg!(feature = "cuda") {
                "CUDA single-GPU"
            } else if cfg!(feature = "wgpu") {
                "WGPU single-GPU"
            } else {
                "CPU-only (no GPU features)"
            };
            recurring_ops.push(format!(
                "routing synth beam : {} (threshold: pairs>=8, work>=50k) | inspect d2/d3 cache : {}/{} CSE classes already in atlas",
                gpu_mode, cse_prior, classes
            ));

            // Total redundancy chain: raw → CSE → trace → truly novel.
            // Use trace_classes as the most aggressive denominator.
            let truly_distinct = trace.n_trace_classes.max(1);
            Some(PlanMetrics {
                total_planned: total,
                unique_after_fnv: unique,
                input_dedup_pct: pct,
                distinct_programs: raw,
                n_cse_classes: trace.n_trace_classes,
                atlas_hits: peek_hits,
                atlas_hit_pct: peek_pct,
                // Synth path doesn't have stored (program, input) results
                // pre-Start (the programs are synthesized at run time).
                atlas_result_hits: 0,
                atlas_result_pct: 0.0,
                truly_novel: truly_distinct.saturating_sub(peek_hits.min(truly_distinct)),
            })
        });
        if recurring_ops.is_empty() {
            recurring_ops.push("beam search enumerates candidates at runtime".to_string());
        }
        let mut report = ComputationPlanReport {
            kind: kind.clone(),
            node_count: 0,
            opcodes,
            recurring_ops,
            cse_canonical_hash: "N/A — synthesized at runtime".to_string(),
            cse_node_delta: 0,
            plan,
            alpha_manifest: alpha_prestart.as_ref().map(|p| p.manifest.clone()),
        };
        let elapsed_ms = inspect_t0.elapsed().as_secs_f64() * 1000.0;
        alpha_trace(
            &app,
            "backend",
            format!(
                "inspect.computed kind={} elapsed_ms={elapsed_ms:.0} has_plan={} recurring_ops={}",
                kind,
                report.plan.is_some(),
                report.recurring_ops.len()
            ),
        );
        report.recurring_ops.push(format!(
            "inspect elapsed : {:.0} ms (cached on next call with same file)",
            elapsed_ms
        ));
        if let Some(fh) = file_hash {
            backend
                .inspect_cache
                .insert((kind.clone(), fh), report.clone());
            if kind == "reverse_synth_alpha" {
                match persist_alpha_inspect_report_to_store(&backend, fh, &report) {
                    Ok(true) => report.recurring_ops.push(
                        "inspect report persisted in Atlas for instant replay next time".to_string(),
                    ),
                    Ok(false) => report.recurring_ops.push(
                        "inspect report already present in Atlas".to_string(),
                    ),
                    Err(err) => report.recurring_ops.push(format!(
                        "inspect report persist error: {err}"
                    )),
                }
                if let Err(err) = persist_alpha_inspect_report_sidecar(&store_path, fh, &report) {
                    report
                        .recurring_ops
                        .push(format!("inspect sidecar persist error: {err}"));
                }
            }
            backend
                .inspect_cache
                .insert((kind.clone(), fh), report.clone());
        }
        return Ok(report);
    }

    // ── Branch B : stored program (DNA k-mer programs) ──
    let func = backend
        .programs
        .get(kind.as_str())
        .copied()
        .ok_or_else(|| format!("unknown program: {kind}"))?;

    let prog_bytes = backend
        .node
        .store()
        .load(&func)
        .ok_or_else(|| format!("program {kind} not found in store"))?;
    let prog = Program::from_bytes(&prog_bytes).map_err(|e| format!("{e:?}"))?;

    let node_count = prog.nodes().len();
    let cse_prog = prog.cse().unwrap_or_else(|_| prog.clone());
    let cse_node_delta = node_count as i32 - cse_prog.nodes().len() as i32;
    let cse_hash = cse_prog.structural_hash_hex();
    let cse_canonical_hash = cse_hash[..16.min(cse_hash.len())].to_string();

    let mut op_counts: HashMap<String, u32> = HashMap::new();
    for n in prog.nodes() {
        *op_counts.entry(format!("{:?}", n.op)).or_insert(0) += 1;
    }
    let mut opcodes: Vec<String> = op_counts.keys().cloned().collect();
    opcodes.sort();
    let mut recurring_ops: Vec<String> = op_counts
        .iter()
        .filter(|(_, &c)| c >= 2)
        .map(|(n, c)| format!("{n}×{c}"))
        .collect();
    recurring_ops.sort();

    // Real plan only when the user has uploaded a file.
    let plan = bytes.as_ref().and_then(|b| {
        let (kmers, _classes) = encode_kmers_with_class(b);
        if kmers.is_empty() {
            return None;
        }
        let p = ComputationPlan::build(
            &backend.node,
            kmers.iter().map(|k| (func, k.to_le_bytes().to_vec())),
        );
        let unique = p.calls.len();
        let atlas_hits = p.atlas_hits();
        let atlas_pct = if unique == 0 {
            0.0
        } else {
            100.0 * atlas_hits as f64 / unique as f64
        };
        let atlas_result_hits = p.atlas_result_hits();
        let atlas_result_pct = if unique == 0 {
            0.0
        } else {
            100.0 * atlas_result_hits as f64 / unique as f64
        };
        Some(PlanMetrics {
            total_planned: p.total_planned,
            unique_after_fnv: unique,
            input_dedup_pct: p.input_dedup_pct(),
            distinct_programs: p.distinct_funcs(),
            n_cse_classes: p.n_cse_classes,
            atlas_hits,
            atlas_hit_pct: atlas_pct,
            atlas_result_hits,
            atlas_result_pct,
            truly_novel: p.truly_novel(),
        })
    });

    let mut report = ComputationPlanReport {
        kind: kind.clone(),
        node_count,
        opcodes,
        recurring_ops,
        cse_canonical_hash,
        cse_node_delta,
        plan,
        alpha_manifest: None,
    };
    let elapsed_ms = inspect_t0.elapsed().as_secs_f64() * 1000.0;
    report.recurring_ops.push(format!(
        "inspect elapsed : {:.0} ms (cached on next call with same file)",
        elapsed_ms
    ));
    if let Some(fh) = file_hash {
        backend
            .inspect_cache
            .insert((kind.clone(), fh), report.clone());
        if kind == "reverse_synth_alpha" {
            match persist_alpha_inspect_report_to_store(&backend, fh, &report) {
                Ok(true) => report.recurring_ops.push(
                    "inspect report persisted in Atlas for instant replay next time".to_string(),
                ),
                Ok(false) => report.recurring_ops.push(
                    "inspect report already present in Atlas".to_string(),
                ),
                Err(err) => report.recurring_ops.push(format!(
                    "inspect report persist error: {err}"
                )),
            }
            if let Err(err) = persist_alpha_inspect_report_sidecar(&store_path, fh, &report) {
                report
                    .recurring_ops
                    .push(format!("inspect sidecar persist error: {err}"));
            }
            backend
                .inspect_cache
                .insert((kind.clone(), fh), report.clone());
        }
    }
    Ok(report)
}

/// Returns Forge's GPU capability report — what acceleration paths are
/// available on this machine and what the user can do to unlock more.
/// Called once at UI startup so the user sees the picture immediately
/// rather than discovering missing components mid-test.
#[tauri::command]
async fn gpu_report() -> Result<Vec<String>, String> {
    Ok(gpu_capability_report())
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
struct BangerRuntimeStatus {
    backend_ready: bool,
    backend_open_ms: u64,
    backend_wait_ms: u64,
    backend_already_ready: bool,
    atlas_attached: bool,
    installed_programs: usize,
    run_cache_entries: usize,
    inspect_cache_entries: usize,
    semantic_cache_entries: usize,
    gpu_report: Vec<String>,
}

#[tauri::command]
async fn banger_runtime_status(
    state: tauri::State<'_, Mutex<ForgeAppState>>,
    app: tauri::AppHandle,
) -> Result<BangerRuntimeStatus, String> {
    let report = ensure_backend_ready(&state, &app, "banger_runtime_status")?;
    let app_state = state.lock().map_err(|e| e.to_string())?;
    let backend = app_state
        .backend
        .as_ref()
        .ok_or_else(|| "Forge backend unavailable after warmup".to_string())?;

    Ok(BangerRuntimeStatus {
        backend_ready: true,
        backend_open_ms: report.open_ms,
        backend_wait_ms: report.wait_ms,
        backend_already_ready: report.already_ready,
        atlas_attached: backend.node.atlas().is_some(),
        installed_programs: backend.programs.len(),
        run_cache_entries: backend.run_cache.len(),
        inspect_cache_entries: backend.inspect_cache.len(),
        semantic_cache_entries: app_state.semantic_cache.len(),
        gpu_report: gpu_capability_report(),
    })
}

#[derive(Serialize)]
struct HardwareGpu {
    /// "Nvidia" | "Amd" | "Intel" | "Apple" | "Microsoft" | "Other"
    vendor: String,
    /// Full adapter name as reported by the OS, e.g. "NVIDIA GeForce RTX 4080".
    name: String,
    /// "cuda" | "wgpu" | "inactive"
    backend: String,
}

#[derive(Serialize)]
struct HardwareInfo {
    cpu_brand: String,
    cpu_threads: usize,
    os: String,
    arch: String,
    gpus: Vec<HardwareGpu>,
    cuda_enabled: bool,
    nvrtc_available: bool,
}

#[derive(Serialize, Clone, Default)]
#[serde(rename_all = "camelCase")]
struct WebExplorerRendererProbe {
    sampled_at_ms: u64,
    parent_pid: u32,
    webview2_process_count: usize,
    process_ids: Vec<u32>,
    gpu_engine: String,
    gpu_engine_samples: Vec<String>,
    source: String,
    error: String,
}

#[cfg(windows)]
fn webexplorer_renderer_probe_now() -> WebExplorerRendererProbe {
    let parent_pid = std::process::id();
    let script = format!(
        r#"
$parent = {parent_pid}
$procs = @(Get-CimInstance Win32_Process -Filter "Name='msedgewebview2.exe'" -ErrorAction SilentlyContinue | Where-Object {{ $_.ParentProcessId -eq $parent -or $_.CommandLine -match 'embedded-browser-webview|--webview|tauri' }})
foreach ($p in $procs) {{ "PROC|$($p.ProcessId)|$($p.ParentProcessId)" }}
try {{
  $ids = @($procs | ForEach-Object {{ [string]$_.ProcessId }})
  if ($ids.Count -gt 0) {{
    $samples = (Get-Counter '\GPU Engine(*)\Utilization Percentage' -ErrorAction Stop).CounterSamples
    foreach ($s in $samples) {{
      foreach ($id in $ids) {{
        if ($s.InstanceName -like "pid_$id*") {{ "GPU|$($s.InstanceName)|$([math]::Round($s.CookedValue, 3))" }}
      }}
    }}
  }}
}} catch {{ "ERR|$($_.Exception.Message)" }}
"#
    );
    let output = Command::new("powershell.exe")
        .args(["-NoProfile", "-Command", &script])
        .creation_flags(0x08000000)
        .output();
    let mut probe = WebExplorerRendererProbe {
        sampled_at_ms: now_epoch_ms() as u64,
        parent_pid,
        source: "powershell:cim+gpu-counter".to_string(),
        ..WebExplorerRendererProbe::default()
    };
    let Ok(output) = output else {
        probe.error = "failed to launch powershell probe".to_string();
        return probe;
    };
    if !output.status.success() {
        probe.error = String::from_utf8_lossy(&output.stderr).trim().to_string();
        if probe.error.is_empty() {
            probe.error = format!("powershell exited with {}", output.status);
        }
        return probe;
    }
    let mut engines = Vec::new();
    for line in String::from_utf8_lossy(&output.stdout).lines().map(str::trim) {
        if let Some(rest) = line.strip_prefix("PROC|") {
            let mut parts = rest.split('|');
            if let Some(pid) = parts.next().and_then(|it| it.parse::<u32>().ok()) {
                probe.process_ids.push(pid);
            }
        } else if let Some(rest) = line.strip_prefix("GPU|") {
            let sample = rest.to_string();
            if !sample.is_empty() {
                engines.push(sample);
            }
        } else if let Some(rest) = line.strip_prefix("ERR|") {
            probe.error = rest.to_string();
        }
    }
    probe.process_ids.sort_unstable();
    probe.process_ids.dedup();
    probe.webview2_process_count = probe.process_ids.len();
    engines.sort();
    engines.dedup();
    probe.gpu_engine = if engines.is_empty() {
        "not active in last Windows GPU counter sample".to_string()
    } else {
        engines
            .iter()
            .filter_map(|sample| sample.split('|').next())
            .filter_map(|name| name.rsplit("engtype_").next())
            .map(str::to_string)
            .collect::<Vec<_>>()
            .join(" / ")
    };
    probe.gpu_engine_samples = engines;
    probe
}

#[cfg(not(windows))]
fn webexplorer_renderer_probe_now() -> WebExplorerRendererProbe {
    WebExplorerRendererProbe {
        sampled_at_ms: now_epoch_ms() as u64,
        parent_pid: std::process::id(),
        source: "unsupported-platform".to_string(),
        error: "WebView2 process/GPU-engine probe is Windows-only.".to_string(),
        ..WebExplorerRendererProbe::default()
    }
}

#[tauri::command]
async fn webexplorer_renderer_probe() -> Result<WebExplorerRendererProbe, String> {
    std::thread::spawn(webexplorer_renderer_probe_now)
        .join()
        .map_err(|_| "webexplorer renderer probe worker panicked".to_string())
}

/// Cleans up the raw cpuid brand string into something compact for display:
/// strips trademark markers, trailing "Processor"/"CPU", clock-speed suffix,
/// and the "with X Graphics" tail that AMD APUs append for the integrated
/// GPU (the user already sees the iGPU in the GPU list, no need to repeat).
fn cleanup_cpu_brand(raw: &str) -> String {
    let mut s = raw.to_string();
    for marker in ["(R)", "(r)", "(TM)", "(tm)", "(C)", "(c)"] {
        s = s.replace(marker, "");
    }
    if let Some(idx) = s.to_lowercase().find(" with ") {
        if s[idx..].to_lowercase().contains("graphics") {
            s.truncate(idx);
        }
    }
    if let Some(idx) = s.find('@') {
        s.truncate(idx);
    }
    for tail in ["Processor", "processor", "CPU", "cpu"] {
        let trimmed = s.trim_end();
        if let Some(stripped) = trimmed.strip_suffix(tail) {
            s = stripped.trim_end().trim_end_matches(',').to_string();
        }
    }
    s.split_whitespace().collect::<Vec<_>>().join(" ")
}

/// Reads the CPU brand string via the x86 cpuid leaves 0x80000002–0x80000004.
/// Pure std — no extra crate. Returns a generic label on non-x86 hosts.
fn detect_cpu_brand() -> String {
    #[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
    {
        #[cfg(target_arch = "x86_64")]
        use std::arch::x86_64::__cpuid;
        #[cfg(target_arch = "x86")]
        use std::arch::x86::__cpuid;
        let max = __cpuid(0x80000000).eax;
        if max < 0x80000004 {
            return "Unknown CPU".to_string();
        }
        let mut bytes: Vec<u8> = Vec::with_capacity(48);
        for leaf in 0x80000002u32..=0x80000004u32 {
            let r = __cpuid(leaf);
            bytes.extend_from_slice(&r.eax.to_le_bytes());
            bytes.extend_from_slice(&r.ebx.to_le_bytes());
            bytes.extend_from_slice(&r.ecx.to_le_bytes());
            bytes.extend_from_slice(&r.edx.to_le_bytes());
        }
        // Strip nul bytes and trim.
        let s: String = bytes
            .into_iter()
            .take_while(|&b| b != 0)
            .map(|b| b as char)
            .collect();
        let trimmed = s.trim();
        if trimmed.is_empty() {
            "Unknown CPU".to_string()
        } else {
            cleanup_cpu_brand(trimmed)
        }
    }
    #[cfg(not(any(target_arch = "x86", target_arch = "x86_64")))]
    {
        format!("{} CPU", std::env::consts::ARCH)
    }
}

#[cfg(windows)]
fn windows_gpu_name_fallback() -> Vec<String> {
    let output = Command::new("powershell.exe")
        .args([
            "-NoProfile",
            "-Command",
            "Get-CimInstance Win32_VideoController | Select-Object -ExpandProperty Name",
        ])
        .creation_flags(0x08000000)
        .output();
    let Ok(output) = output else {
        return Vec::new();
    };
    if !output.status.success() {
        return Vec::new();
    }
    String::from_utf8_lossy(&output.stdout)
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .map(str::to_string)
        .collect()
}

#[cfg(not(windows))]
fn windows_gpu_name_fallback() -> Vec<String> {
    Vec::new()
}

fn backend_hint_for_gpu_name(name: &str) -> String {
    let lower = name.to_ascii_lowercase();
    if lower.contains("nvidia") && cfg!(feature = "cuda") {
        "cuda".to_string()
    } else if cfg!(feature = "wgpu") {
        "wgpu".to_string()
    } else {
        "inactive".to_string()
    }
}

/// Returns CPU + per-GPU hardware info for display in the panel footer.
/// Does NOT touch ForgeAppState/Mutex so it's safe to call at boot while the
/// backend is still initialising. Recomputes a fresh GpuNodeRuntime each call
/// (cheap — adapter enumeration only).
#[tauri::command]
async fn get_hardware_info() -> Result<HardwareInfo, String> {
    // Offload GPU adapter enumeration so this boot-time probe never occupies
    // the Tauri command runtime while the UI is trying to load sessions/assets.
    let runtime = tauri::async_runtime::spawn_blocking(scan::GpuNodeRuntime::bootstrap_best_effort)
        .await
        .map_err(|err| format!("hardware-info worker failed: {err}"))?;
    let bs = runtime.bootstrap();
    let nodes = runtime.node_ids();
    let mut gpus: Vec<HardwareGpu> = nodes
        .iter()
        .map(|n| {
            let label = n.backend.label();
            let backend = if label.starts_with("CUDA") {
                "cuda"
            } else if label.starts_with("WGPU") {
                "wgpu"
            } else {
                "inactive"
            }
            .to_string();
            HardwareGpu {
                vendor: format!("{:?}", n.vendor),
                name: n.name.clone(),
                backend,
            }
        })
        .collect();
    if gpus.is_empty() {
        gpus = windows_gpu_name_fallback()
            .into_iter()
            .map(|name| HardwareGpu {
                vendor: "Other".to_string(),
                name: name.clone(),
                backend: backend_hint_for_gpu_name(&name),
            })
            .collect();
    }
    let threads = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(0);
    Ok(HardwareInfo {
        cpu_brand: detect_cpu_brand(),
        cpu_threads: threads,
        os: std::env::consts::OS.to_string(),
        arch: std::env::consts::ARCH.to_string(),
        gpus,
        cuda_enabled: bs.cuda_enabled,
        nvrtc_available: bs.nvrtc_available,
    })
}

#[derive(Serialize)]
struct GpuStartupAlert {
    /// "missing-toolkit" | "no-gpu-support"
    severity: String,
    title: String,
    body: String,
    download_url: Option<String>,
}

/// Returns a structured alert ONLY when there's a critical GPU situation
/// the user needs to act on (Toolkit missing, no GPU support compiled).
/// Returns null otherwise. Used by the frontend to pop a modal at startup.
#[tauri::command]
async fn gpu_startup_alert(
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<Option<GpuStartupAlert>, String> {
    let mut app_state = state.lock().map_err(|e| e.to_string())?;
    let backend = app_state.backend_mut()?;
    let bs = backend.node.gpunode_bootstrap();
    let cuda_compiled = cfg!(feature = "cuda");
    let wgpu_compiled = cfg!(feature = "wgpu");

    if cuda_compiled && bs.nvidia_detected && bs.cuda_enabled && !bs.nvrtc_available {
        return Ok(Some(GpuStartupAlert {
            severity: "missing-toolkit".to_string(),
            title: format!(
                "CUDA Toolkit missing — {} NVIDIA GPU{} sitting idle",
                bs.detected_gpu_count,
                if bs.detected_gpu_count > 1 { "s" } else { "" }
            ),
            body: "Forge detected your NVIDIA GPU(s) and the CUDA driver, but the CUDA Toolkit is not installed. \
                   Without it, Forge cannot compile GPU kernels at runtime — all computations fall back to CPU.\n\n\
                   To unlock full GPU acceleration:\n\
                   • Option A — Install the CUDA Toolkit (~3 GB), the proper NVIDIA path.\n\
                   • Option B — Rebuild Forge with `--features wgpu` instead of `--features cuda`. \
                   No download (uses your existing GPU driver via Vulkan/DX12), works on any vendor.\n\n\
                   If you JUST installed the Toolkit: close all terminals + Forge, open a fresh terminal, then relaunch. \
                   Process PATH is frozen at start — running processes don't see new install paths.\n\n\
                   You can continue with CPU-only for now if you want."
                .to_string(),
            download_url: Some("https://developer.nvidia.com/cuda-downloads".to_string()),
        }));
    }

    if !cuda_compiled && !wgpu_compiled {
        return Ok(Some(GpuStartupAlert {
            severity: "no-gpu-support".to_string(),
            title: "Forge built without GPU support".to_string(),
            body: "This Forge build has neither cuda nor wgpu features enabled. \
                   All computations will run on CPU. To unlock GPU acceleration, rebuild Forge with \
                   `--features cuda` (NVIDIA only) or `--features wgpu` (any GPU)."
                .to_string(),
            download_url: None,
        }));
    }

    Ok(None)
}

// ═══════════════════════════════════════════════════════════════════
// Φ.ν.7g — Section α Alpha : Tauri command paramétrée
// ═══════════════════════════════════════════════════════════════════
//
// Reuse de tout le moteur reverse_synth (parser CSV + features +
// simulator + builder + Forge synth + eval) mais avec config
// dynamique reçue depuis le panel UI Alpha au lieu d'être hardcodée
// sur NATGAS H4.
//
// Channels IPC dédiés (alpha-log, alpha-signal) pour ne pas polluer
// les events de la section Î¨ DNA. Le frontend Alpha listen ces deux
// channels exclusivement.

#[derive(Debug, Clone, Deserialize)]
