#[cfg(test)]
mod tests {
    use super::*;

    fn sample_alpha_bars(n: usize) -> Vec<synth_strategy::Bar> {
        let mut bars = Vec::with_capacity(n);
        let start_ms = 3 * 3_600_000_i64;
        for i in 0..n {
            let t = start_ms + i as i64 * 4 * 3_600_000_i64;
            let phase = i as f64 / 4.0;
            let drift = i as f64 * 0.0008;
            let base = 3.0 + 0.16 * phase.sin() + drift;
            let open = base;
            let close = base + 0.025 * (phase * 0.7).cos();
            let high = open.max(close) + 0.03 + 0.005 * phase.cos().abs();
            let low = open.min(close) - 0.03 - 0.005 * phase.sin().abs();
            let volume = 500.0 + (i % 17) as f64 * 23.0;
            bars.push(synth_strategy::Bar {
                time_ms: t,
                open,
                high,
                low,
                close,
                volume,
            });
        }
        bars
    }

    #[test]
    fn depth2_enumerator_produces_non_trivial_cse_collapse() {
        let examples: Vec<(i64, i64)> = (0..20).map(|i| (i, 1)).collect();
        let candidates = enumerate_synth_candidates_d2(&examples);
        assert!(
            candidates.len() > 100,
            "expected >100 depth-2 candidates, got {}",
            candidates.len()
        );

        let s = cse_classify_candidates_with_reps(&candidates);
        let (raw, classes, redundancy) = (s.raw, s.n_classes, s.redundancy_pct);
        assert_eq!(raw, candidates.len());
        eprintln!(
            "[depth2 enum] {raw} raw candidates -> {classes} CSE classes ({redundancy:.1}% redundancy)"
        );
        assert!(
            classes < raw,
            "CSE should collapse some equivalents (raw={raw}, classes={classes})"
        );
        assert!(
            redundancy > 20.0,
            "expected >20% CSE redundancy on depth-2 space, got {redundancy:.1}%"
        );
    }

    #[test]
    fn depth3_enumerator_extends_redundancy() {
        let examples: Vec<(i64, i64)> = (0..20).map(|i| (i, 1)).collect();
        let mut candidates = enumerate_synth_candidates_d2(&examples);
        let d2_count = candidates.len();
        candidates.extend(enumerate_synth_candidates_d3(&examples));
        let total = candidates.len();
        assert!(
            total > d2_count,
            "d3 enumerator should add candidates ({total} <= {d2_count})"
        );

        let cse = cse_classify_candidates_with_reps(&candidates);
        assert_eq!(cse.raw, total);
        assert_eq!(cse.live_reps.len() + cse.static_count, cse.n_classes);
        eprintln!(
            "[d2+d3 enum] {} raw ({d2_count} d2 + {} d3) -> {} CSE classes ({:.1}% redundancy, {} provably-constant)",
            cse.raw,
            cse.raw - d2_count,
            cse.n_classes,
            cse.redundancy_pct,
            cse.static_count
        );
        assert!(
            cse.redundancy_pct > 30.0,
            "expected >30% CSE redundancy on depth-2+3 space, got {:.1}%",
            cse.redundancy_pct
        );
        assert!(
            cse.static_count > 0,
            "expected some provably-constant programs, got {}",
            cse.static_count
        );
    }

    #[test]
    fn trace_classifier_collapses_data_equivalent_beyond_cse() {
        let examples: Vec<(i64, i64)> = (0..20).map(|i| (i, 1)).collect();
        let mut candidates = enumerate_synth_candidates_d2(&examples);
        candidates.extend(enumerate_synth_candidates_d3(&examples));
        let cse = cse_classify_candidates_with_reps(&candidates);

        let inputs: Vec<i64> = (0..16).collect();
        let trace = trace_classify_reps(&cse.live_reps, &inputs, 16);
        eprintln!(
            "[trace classify] {} CSE reps -> {} trace classes | {} tautological | {} identity | top class: {} members | static (provably const): {}",
            cse.n_classes,
            trace.n_trace_classes,
            trace.tautological,
            trace.identity,
            trace.top_class_size,
            cse.static_count
        );
        assert!(
            trace.n_trace_classes <= cse.n_classes,
            "trace classes ({}) should be <= CSE classes ({})",
            trace.n_trace_classes,
            cse.n_classes
        );
        assert!(
            trace.n_trace_classes < cse.n_classes,
            "expected trace clustering to collapse beyond CSE (got {} == {})",
            trace.n_trace_classes,
            cse.n_classes
        );
        assert!(
            trace.tautological > 0,
            "expected some tautological candidates, got {}",
            trace.tautological
        );
    }

    #[test]
    fn subtree_mining_reveals_mass_sublevel_redundancy() {
        let examples: Vec<(i64, i64)> = (0..20).map(|i| (i, 1)).collect();
        let mut candidates = enumerate_synth_candidates_d2(&examples);
        candidates.extend(enumerate_synth_candidates_d3(&examples));

        let sub = analyze_subtree_redundancy(&candidates);
        assert!(
            sub.total_subtrees > candidates.len(),
            "expected more sub-trees than candidates (each d3 yields 2)"
        );
        assert!(
            sub.unique_subtrees < sub.total_subtrees,
            "expected dedup at sub-tree level"
        );
        eprintln!(
            "[sub-tree mining] {} candidates -> {} sub-evaluations -> {} unique sub-trees ({:.1}% redundancy)",
            candidates.len(),
            sub.total_subtrees,
            sub.unique_subtrees,
            sub.redundancy_pct
        );
        // Mass redundancy: every depth-3 candidate's INNER sub-tree is
        // structurally a depth-2 form, so all 21k inner sub-trees collapse
        // into the same ~200 depth-2 CSE classes. Expect >80%.
        assert!(
            sub.redundancy_pct > 80.0,
            "expected >80% sub-tree redundancy, got {:.1}%",
            sub.redundancy_pct
        );
    }

    #[test]
    fn subwindow_redundancy_reports_real_savings_on_natgas_size() {
        // NATGAS H4 is ~25,381 bars over 16 years.
        let stats = analyze_subwindow_redundancy(25_381);
        assert_eq!(stats.bar_count, 25_381);
        eprintln!(
            "[sub-window {} bars] {} naive -> {} sliding ({:.2}% redundancy)",
            stats.bar_count,
            fmt_ops(stats.total_naive_ops),
            fmt_ops(stats.total_sliding_ops),
            stats.redundancy_pct
        );
        for (name, naive, sliding, pct) in &stats.per_feature {
            eprintln!(
                "  {name:<10} {} naive -> {} sliding ({:.1}% redundancy)",
                fmt_ops(*naive),
                fmt_ops(*sliding),
                pct
            );
        }
        // The dominant features (SMA50, SMA200) are over 95% redundant
        // because their windows are large vs the per-bar slide cost.
        assert!(
            stats.redundancy_pct > 90.0,
            "expected >90% sub-window redundancy on 25k bars, got {:.1}%",
            stats.redundancy_pct
        );
        // SMA(200) specifically: 25,381 × 200 = 5.07M naïve, ~25k sliding.
        let sma200 = stats.per_feature.iter().find(|(n, _, _, _)| *n == "SMA(200)").expect("SMA(200) present");
        assert!(sma200.3 > 99.0, "SMA(200) should be >99% redundant, got {:.1}%", sma200.3);
    }

    #[test]
    fn atlas_peek_reports_brain_resolvable_pairs_on_cold_cache() {
        use scan::{MemoryGovernor, MonsterNode, Store};

        let path = std::env::temp_dir().join(format!(
            "forge-ui-test-atlas-peek-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&path);
        let store = Store::open(&path).expect("store open");
        let node = MonsterNode::new(store, MemoryGovernor::new(8 * 1024 * 1024));

        let examples: Vec<(i64, i64)> = (0..8).map(|i| (i, 1)).collect();
        let candidates = enumerate_synth_candidates_d2(&examples);
        let cse = cse_classify_candidates_with_reps(&candidates);
        let inputs: Vec<i64> = (0..16).collect();

        let (total, hits, pct) =
            synth_atlas_warm_estimate(&node, &cse.live_reps, &inputs, 64, 16);
        assert!(total > 0, "atlas peek total should be > 0");
        eprintln!(
            "[atlas peek] {hits}/{total} (program -> input) pairs brain-resolvable on cold cache ({pct:.1}%)"
        );
        // Most depth-2 affine programs (Add/Sub/Mul with a constant) are
        // resolved by the StructuralRule layer without the interpreter,
        // so we expect a healthy hit rate even on cold cache.
        assert!(
            pct > 5.0,
            "expected >5% brain-resolvable on cold cache, got {pct:.1}%"
        );

        let _ = std::fs::remove_dir_all(&path);
    }

    #[test]
    fn prestart_to_start_warm_path_avoids_raw_recompute() {
        let path = std::env::temp_dir().join(format!(
            "forge-ui-test-alpha-prestart-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&path);

        let backend = ForgeBackend::new(path.clone()).expect("backend");
        let bars = sample_alpha_bars(synth_strategy::MIN_HISTORY + 96);
        let file_hash = 0xA17A_1234_u64;

        let (raw_feature_cache, cold_stats) = synth_strategy::build_raw_feature_cache_with_atlas(
            &bars,
            synth_strategy::MIN_HISTORY..bars.len(),
            &backend.atlas,
            file_hash,
        );
        assert!(
            cold_stats.computed_rows > 0,
            "cold build should compute some raw rows"
        );

        let persisted = persist_alpha_prestart_to_store(
            &backend,
            file_hash,
            &bars,
            &raw_feature_cache,
        )
        .expect("persist prestart");
        assert!(persisted, "first pre-start artifact should be new");

        let loaded = load_alpha_prestart_from_store(&backend, file_hash)
            .expect("load prestart result")
            .expect("prestart present");
        assert_eq!(loaded.manifest.raw_feature_rows_missing, 0);

        let start_plan = build_alpha_start_execution_plan(Some(&loaded), bars.len());
        assert!(start_plan.parsed_bars_from_prestart);
        assert_eq!(start_plan.raw_cache_source, "manifest-ready");
        assert!(!start_plan.refresh_prestart_after_raw_fill);

        let (_warm_cache, warm_stats) = synth_strategy::build_raw_feature_cache_with_atlas(
            loaded.bars.as_slice(),
            synth_strategy::MIN_HISTORY..loaded.bars.len(),
            &backend.atlas,
            file_hash,
        );
        assert_eq!(
            warm_stats.computed_rows, 0,
            "warm path should not recompute any raw row"
        );
        assert!(
            warm_stats.atlas_hits >= loaded.manifest.raw_feature_rows_ready,
            "warm path should rehydrate rows from atlas"
        );
        assert_eq!(avoided_pct(warm_stats.atlas_hits, warm_stats.computed_rows), 100.0);

        drop(backend);
        let _ = std::fs::remove_dir_all(&path);
    }

    #[test]
    fn avoided_pct_reports_full_avoidance_when_recompute_is_zero() {
        assert_eq!(avoided_pct(12, 0), 100.0);
        assert_eq!(avoided_pct(0, 0), 0.0);
        assert!((avoided_pct(9, 3) - 75.0).abs() < 1e-9);
    }
}

